def restore_command_rank(chat_id, command_name):
    """يرجع الأمر للرتبة الأصلية الموجودة في إعدادات السورس."""
    key = normalize_command_name(command_name)
    original_rank = ORIGINAL_COMMAND_RANKS.get(key, "Member")
    command_ranks.setdefault(chat_id, {})[key] = original_rank
    save_command_ranks(chat_id)
    return original_rank


