# Gemini: إجبار اتصال generativelanguage.googleapis.com على IPv4 فقط
# يمنع أخطاء المنطقة الناتجة عن IPv6 في بعض السيرفرات.
# =========================================================
import socket as _gemini_socket
_gemini_original_getaddrinfo = _gemini_socket.getaddrinfo

def _gemini_ipv4_getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):
    if isinstance(host, str) and host.lower() in ("generativelanguage.googleapis.com", "upload.generativelanguage.googleapis.com"):
        family = _gemini_socket.AF_INET
        type = type or _gemini_socket.SOCK_STREAM
    return _gemini_original_getaddrinfo(host, port, family, type, proto, flags)

_gemini_socket.getaddrinfo = _gemini_ipv4_getaddrinfo

