def edit_commands_message(bot_obj, call, text, reply_markup=None, parse_mode="HTML"):
    """يعدل نص/كابتشن قائمة الأوامر مع الحفاظ على صورة القائمة."""
    chat_id = call.message.chat.id
    message_id = call.message.message_id
    try:
        # إذا كانت الرسالة صورة، تعديل الكابتشن يحافظ على الصورة دائمًا.
        bot_obj.edit_message_caption(
            text, chat_id, message_id,
            reply_markup=reply_markup, parse_mode=parse_mode
        )
        return True
    except Exception:
        try:
            bot_obj.edit_message_text(
                text, chat_id, message_id,
                reply_markup=reply_markup, parse_mode=parse_mode
            )
            return True
        except Exception:
            return False

def send_commands_menu(bot_obj, chat_id, text, reply_markup):
    """يرسل قائمة الأوامر بنفس صورة رسالة الخاص، مع fallback للنص."""
    try:
        photo = io.BytesIO(EMBEDDED_IMAGE)
        photo.name = "bot_private.jpg"
        return bot_obj.send_photo(
            chat_id, photo, caption=text,
            reply_markup=reply_markup, parse_mode="HTML"
        )
    except Exception as e:
        print(f"[COMMANDS PHOTO ERROR] {e}")
        return bot_obj.send_message(
            chat_id, text, reply_markup=reply_markup, parse_mode="HTML"
        )

