def arabic_error_message(error=None):
    msg = str(error or "").lower()
    if "not enough rights" in msg or "rights" in msg or "permission" in msg:
        return "ما قدرت أنفّذ الطلب، البوت ما عنده الصلاحية المطلوبة."
    if "user not found" in msg or "chat not found" in msg:
        return "ما قدرت ألقى المستخدم أو القروب، تأكد من البيانات وحاول مرة ثانية."
    if "message to delete not found" in msg:
        return "الرسالة مو موجودة أو انحذفت من قبل."
    if "flood" in msg or "too many requests" in msg:
        return "الطلبات كثيرة شوي الحين، انتظر لحظات وجرب مرة ثانية."
    if "timeout" in msg or "timed out" in msg:
        return "صار تأخير بالاتصال، جرّب مرة ثانية بعد شوي."
    if "token" in msg:
        return ""
    return ""

