# Pillow / PIL: يتم تثبيته تلقائياً إذا كان غير موجود حتى تعمل معالجة الملصقات المتحركة.
def _ensure_pillow():
    try:
        from PIL import Image  # noqa: F401
        return True
    except Exception:
        try:
            import subprocess, sys
            subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--no-input", "Pillow"],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=180, check=False)
            from PIL import Image  # noqa: F401
            return True
        except Exception:
            return False

_PILLOW_AVAILABLE = _ensure_pillow()

