@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and m.text.strip() in RAD_STOP_COMMANDS)
def rad_stop_command(message):
    global RAD_STOPPED
    if not _rad_is_developer(message):
        return
    _rad_save_state(True)
    bot.send_message(message.chat.id, "• تم ايقاف البوت تمامًا عن العمل ←By Developer\n• لتشغيله اكتب ← تشغيل راد")

@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and m.text.strip() in RAD_START_COMMANDS)
def rad_start_command(message):
    global RAD_STOPPED
    if not _rad_is_developer(message):
        return
    _rad_save_state(False)
    bot.send_message(message.chat.id, "• تم تشغيل البوت ←By Developer\n• يا مطور Welcome back")

def _rad_update_allowed(message):
    # أوامر المطور تبقى متاحة حتى أثناء الإيقاف.
    if _rad_is_developer(message) and (getattr(message, "text", "") or "").strip() in (RAD_STOP_COMMANDS | RAD_START_COMMANDS):
        return True
    if not RAD_STOPPED:
        return True
    # أثناء الإيقاف: الخاص يعرض رسالة الإيقاف فقط، والقروبات لا تعالج شيئًا.
    if getattr(getattr(message, "chat", None), "type", None) == "private":
        _rad_private_paused_message(message)
    return False

