# المستخدمون المكتومون مؤقتًا/دائمًا في الذاكرة
muted_users = {}

# تحميل الكتم الدائم المحفوظ بعد تشغيل البوت.
def load_persistent_mutes():
    try:
        cursor.execute("SELECT chat_id, user_id, until_time FROM temp_mutes")
        rows = cursor.fetchall()
        for chat_id, user_id, until_time in rows:
            if int(until_time) == 0:
                muted_users.setdefault(int(chat_id), {})[int(user_id)] = 0
            elif int(until_time) > int(time.time()):
                muted_users.setdefault(int(chat_id), {})[int(user_id)] = int(until_time)
    except Exception as e:
        print(f"[MUTE LOAD ERROR] {e}")


