@bot.message_handler(func=lambda m: m.chat.type in ["private", "group", "supergroup"] and m.text and m.text.startswith("قفل امر "))
def lock_command_request(message):
    raw = normalize_private_command(message.text.replace("قفل امر ", "", 1).strip())

    if raw == "اضف تفاعل" and message.chat.type in ["group", "supergroup"]:
        if message.from_user.id not in OWNER_IDS and get_rank(message.from_user.id, message.chat.id) != "Owner":
            bot.reply_to(message, "• هذا الامر يخص ↤ Owner والمطور")
            return
        set_command_lock("اضف تفاعل", "Disabled", chat_id=message.chat.id)
        bot.reply_to(message, "• تم الغاء امر ↤ اضف تفاعل\n• الحين محد يقدر يستخدمها في هذا القروب")
        return

    if raw == "عام اضف تفاعل":
        if message.from_user.id != PRIMARY_OWNER:
            bot.reply_to(message, "• هذا الامر يخص المطور")
            return
        set_command_lock("اضف تفاعل", "Disabled", global_scope=True)
        bot.reply_to(message, "• تم الغاء امر عام ↤ اضف تفاعل\n• الحين محد يقدر يستخدمها في القروبات كلها")
        return

    if message.from_user.id != PRIMARY_OWNER:
        return
    command = raw
    if not command:
        return
    scope = "global" if message.chat.type == "private" else "chat"
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
    def btn(label, rank):
        return telebot.types.InlineKeyboardButton(label, callback_data=f"lockcmd:{scope}:{rank}:{command}", style="primary")
    markup.row(btn("المطور", "Developer"), btn("Owner", "Owner"))
    markup.row(btn("Owner²", "Owner²"), btn("Helper", "Helper"))
    markup.row(btn("Member", "Member"))
    markup.row(telebot.types.InlineKeyboardButton("إغلاق", callback_data="lockcmd:close", style="danger", icon_custom_emoji_id=COMMANDS_CLOSE_ICON_ID))
    scope_text = "جميع القروبات" if scope == "global" else "هذا القروب"
    bot.reply_to(message, f"⌯︙هلا أيها المطور\n⌯︙تبي تقفل امر ← {command}\n⌯︙النطاق ← {scope_text}\n⌯︙لأي رتبة؟", reply_markup=markup)

@bot.message_handler(func=lambda m: m.chat.type in ["private", "group", "supergroup"] and m.text and m.text.startswith("فتح امر "))
def open_command_request(message):
    raw = normalize_private_command(message.text.replace("فتح امر ", "", 1).strip())

    if raw == "اضف تفاعل" and message.chat.type in ["group", "supergroup"]:
        if message.from_user.id not in OWNER_IDS and get_rank(message.from_user.id, message.chat.id) != "Owner":
            bot.reply_to(message, "• هذا الامر يخص ↤ Owner والمطور")
            return
        open_command_lock("اضف تفاعل", chat_id=message.chat.id)
        bot.reply_to(message, "• تم تشغيل امر ↤ اضف تفاعل\n• الحين تقدر تستخدمها في هذا القروب")
        return

    if raw == "عام اضف تفاعل":
        if message.from_user.id != PRIMARY_OWNER:
            bot.reply_to(message, "• هذا الامر يخص المطور")
            return
        open_command_lock("اضف تفاعل", global_scope=True)
        bot.reply_to(message, "• تم فتح امر عام ↤ اضف تفاعل\n• الحين تقدر تستخدمها في القروبات كلها")
        return

    if message.from_user.id != PRIMARY_OWNER:
        return
    command = raw
    if not command:
        return
    if message.chat.type == "private":
        open_command_lock(command, global_scope=True)
        scope_text = "جميع القروبات"
    else:
        open_command_lock(command, chat_id=message.chat.id)
        scope_text = "هذا القروب"
    default_rank = COMMAND_LOCK_DEFAULTS.get(command, "Developer")
    rank_text = "المطور" if default_rank == "Developer" else default_rank
    bot.reply_to(message, f"⌯︙تم فتح الامر\n⌯︙هذا الامر ← {command}\n⌯︙النطاق ← {scope_text}\n⌯︙ورجع مثل ما هو موجود بالكود ← {rank_text}")

@bot.message_handler(func=lambda m: m.chat.type in ["private", "group", "supergroup"] and m.text and m.text.strip() in ["اخفاء امر الرتبة", "اظهار امر الرتبة"])
def rank_visibility_command(message):
    if message.from_user.id != PRIMARY_OWNER:
        return
    hide = message.text.strip() == "اخفاء امر الرتبة"
    if message.chat.type == "private":
        set_command_hidden("الرتبة", global_scope=True, hidden=hide)
        first = "تم اخفاء امر في جميع القروبات" if hide else "تم اظهار امر في جميع القروبات"
    else:
        set_command_hidden("الرتبة", chat_id=message.chat.id, hidden=hide)
        first = "تم اخفاء امر في القروب" if hide else "تم اظهار امر في القروب"
    action = "لن يرد البوت على امر (رتبتي او رتبته)" if hide else "سيرد البوت على امر (رتبتي او رتبته)"
    bot.reply_to(message, f"⌯︙{first}\n⌯︙هذا الامر ← الرتبة\n⌯︙{action}")

@bot.callback_query_handler(func=lambda c: c.data.startswith("lockcmd:"))
def lock_command_callback(call):
    if call.from_user.id != PRIMARY_OWNER:
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return
    parts = call.data.split(":", 3)
    if len(parts) >= 2 and parts[1] == "close":
        try:
            safe_delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return
    if len(parts) < 4:
        try: bot.answer_callback_query(call.id)
        except Exception: pass
        return
    scope, rank, command = parts[1], parts[2], normalize_private_command(parts[3])
    if scope == "global":
        set_command_lock(command, rank, global_scope=True)
        scope_text = "جميع القروبات"
    else:
        set_command_lock(command, rank, chat_id=call.message.chat.id)
        scope_text = "هذا القروب"
    rank_text = "المطور" if rank == "Developer" else rank + (" وما اعلى" if rank != "Member" else "")
    txt = f"⌯︙تم قفل الامر\n⌯︙هذا الامر ← {command}\n⌯︙النطاق ← {scope_text}\n⌯︙وصار بس يستخدمه ← {rank_text}"
    markup = telebot.types.InlineKeyboardMarkup()
    markup.add(telebot.types.InlineKeyboardButton("إغلاق", callback_data="lockcmd:close", style="danger", icon_custom_emoji_id=COMMANDS_CLOSE_ICON_ID))
    try:
        bot.edit_message_text(txt, call.message.chat.id, call.message.message_id, reply_markup=markup)
    except Exception:
        pass
    try: bot.answer_callback_query(call.id)
    except Exception: pass

def _get_thread_db():
    if not hasattr(_db_local, "conn"):
        _db_local.conn = sqlite3.connect(
            DB_PATH,
            check_same_thread=False,
            timeout=30
        )
        _db_local.conn.execute("PRAGMA journal_mode=WAL")
        _db_local.conn.execute("PRAGMA synchronous=NORMAL")
        _db_local.conn.execute("PRAGMA foreign_keys=ON")
        _db_local.conn.execute("PRAGMA busy_timeout=30000")
        _db_local.cursor = _db_local.conn.cursor()
    return _db_local.conn, _db_local.cursor

_init_conn = sqlite3.connect(DB_PATH, timeout=30)
_init_conn.execute("PRAGMA journal_mode=WAL")
_init_conn.execute("PRAGMA synchronous=NORMAL")
_init_conn.execute("PRAGMA foreign_keys=ON")
_init_conn.execute("PRAGMA busy_timeout=30000")

_init_conn.execute("""
CREATE TABLE IF NOT EXISTS users (
    user_id INTEGER,
    chat_id INTEGER,
    rank TEXT,
    PRIMARY KEY (user_id, chat_id)
)
""")

