class CursorProxy:
    def execute(self, *args, **kwargs):
        return _get_thread_db()[1].execute(*args, **kwargs)
    def executemany(self, *args, **kwargs):
        return _get_thread_db()[1].executemany(*args, **kwargs)
    def fetchone(self):
        return _get_thread_db()[1].fetchone()
    def fetchall(self):
        return _get_thread_db()[1].fetchall()

class ConnProxy:
    def commit(self):
        return _get_thread_db()[0].commit()
    def rollback(self):
        return _get_thread_db()[0].rollback()

cursor = CursorProxy()
conn = ConnProxy()

def save_json_setting(chat_id, key, value):
    cursor.execute(
        "INSERT OR REPLACE INTO chat_settings(chat_id, setting_key, setting_value) VALUES(?,?,?)",
        (chat_id, key, json.dumps(value, ensure_ascii=False))
    )
    conn.commit()

def load_json_setting(chat_id, key, default=None):
    cursor.execute(
        "SELECT setting_value FROM chat_settings WHERE chat_id=? AND setting_key=?",
        (chat_id, key)
    )
    row = cursor.fetchone()
    if not row:
        return default
    try:
        return json.loads(row[0])
    except Exception:
        return default

def delete_setting(chat_id, key):
    cursor.execute(
        "DELETE FROM chat_settings WHERE chat_id=? AND setting_key=?",
        (chat_id, key)
    )
    conn.commit()

def load_persistent_state():
    # الحماية المتقدمة
    cursor.execute("SELECT chat_id, setting_value FROM chat_settings WHERE setting_key=?", ("advanced_protection",))
    for chat_id, raw in cursor.fetchall():
        try:
            states = json.loads(raw)
            if isinstance(states, dict):
                advanced_protection[chat_id] = states
                if states.get("users", False):
                    advanced_add_protection[chat_id] = True
        except Exception:
            pass

    # الحماية الأساسية
    cursor.execute("SELECT chat_id, setting_value FROM chat_settings WHERE setting_key=?", ("basic_protection",))
    for chat_id, raw in cursor.fetchall():
        try:
            states = json.loads(raw)
            if isinstance(states, dict):
                # ترقية إعدادات القروبات القديمة إلى مفاتيح الحماية الحالية.
                existing = [name for name in BASIC_PROTECTION_LABELS if name in states]
                legacy_all_on = bool(existing) and all(bool(states.get(name)) for name in existing)
                changed = False
                for name in BASIC_PROTECTION_LABELS:
                    if name not in states:
                        states[name] = legacy_all_on
                        changed = True
                basic_protection[chat_id] = states
                if changed:
                    save_json_setting(chat_id, "basic_protection", states)
        except Exception:
            pass

    # إعدادات التنظيف
    cursor.execute("SELECT chat_id, setting_value FROM chat_settings WHERE setting_key=?", ("cleaning",))
    for chat_id, raw in cursor.fetchall():
        try:
            data = json.loads(raw)
            if isinstance(data, dict):
                mode = int(data.get("mode", 0))
                settings = data.get("settings", {}) or {}
                if mode > 0:
                    cleaning_mode[chat_id] = mode
                    cleaning_settings[chat_id] = settings
        except Exception:
            pass

    # صلاحيات المشرفين
    cursor.execute("SELECT chat_id, setting_value FROM chat_settings WHERE setting_key=?", ("admin_permissions",))
    for chat_id, raw in cursor.fetchall():
        try:
            data = json.loads(raw)
            if isinstance(data, dict):
                admin_permissions[chat_id] = {int(target_id): perms for target_id, perms in data.items()}
        except Exception:
            pass

load_persistent_state()

