COMMAND_LOCK_DEFAULTS = {
    "المطور": "Member",
    "الاوامر": "Developer",
    "تفعيل التنظيف": "Developer",
    "الحماية": "Developer",
    "تفعيل حماية المتقدمة": "Developer",
    "قائمة الرتب": "Developer",
    "قائمة": "Developer",
    "رتبتي": "Member",
    "رتبته": "Member",
    "4": "Owner²",
    "5": "Owner²",
    "رفع مشرف": "Owner",
    "تنزيل مشرف": "Owner",
    "احصائيات": "Developer",
    "توب قروبات": "Developer",
    "توب القروبات": "Developer",
    "اضف تفاعل": "Developer",
}

for _cmd, _rank in COMMAND_LOCK_DEFAULTS.items():
    cursor.execute("INSERT OR IGNORE INTO private_command_locks(command, rank) VALUES(?,?)", (_cmd, _rank))
    cursor.execute("INSERT OR IGNORE INTO scoped_command_locks(scope, chat_id, command, rank) VALUES(?,?,?,?)", ("global", 0, _cmd, _rank))
conn.commit()

def normalize_private_command(command):
    command = str(command or "").strip()
    # المطور ومطور أمر واحد، حتى إذا كتب المالك أي صيغة منهما.
    if command in ("المطور", "مطور"):
        return "المطور"
    return command

def get_command_lock(command):
    command = normalize_private_command(command)
    cursor.execute("SELECT rank FROM private_command_locks WHERE command=?", (command,))
    row = cursor.fetchone()
    return row[0] if row else COMMAND_LOCK_DEFAULTS.get(command, "Developer")

def set_command_lock(command, rank):
    command = normalize_private_command(command)
    cursor.execute("INSERT OR REPLACE INTO private_command_locks(command, rank) VALUES(?,?)", (command, rank))
    conn.commit()

def open_command_lock(command):
    command = normalize_private_command(command)
    default_rank = COMMAND_LOCK_DEFAULTS.get(command, "Developer")
    cursor.execute("INSERT OR REPLACE INTO private_command_locks(command, rank) VALUES(?,?)", (command, default_rank))
    conn.commit()



def locked_command_denied(message, command):
    lock = get_command_lock(command)
    if lock == "Developer":
        text = "المطور"
    elif lock == "Owner":
        text = "Owner وما اعلى"
    elif lock == "Owner²":
        text = "Owner² وما اعلى"
    elif lock == "Helper":
        text = "Helper وما اعلى"
    elif lock == "Member":
        text = "Member وما اعلى"
    else:
        text = "المطور"
    bot.reply_to(message, f"• هذا الامر يخص - 「 {text} 」")

def can_use_locked_command(user_id, chat_id, command):
    lock = get_command_lock(command)

    # المطور = فقط الـ IDs الموجودة في OWNER_IDS
    if lock == "Developer":
        return user_id in OWNER_IDS

    # المطور دائمًا أعلى صلاحية
    if user_id in OWNER_IDS:
        return True

    level = get_rank_level(user_id, chat_id)
    required = {
        "Member": 0,
        "Owner": 3,
        "Owner²": 2,
        "Helper": 1,
    }.get(lock, 0)

    return level >= required

# =========================================================
# قفل الأوامر بنطاقين: عام من الخاص / محلي من القروب
# =========================================================
def get_command_lock(command, chat_id=None):
    command = normalize_private_command(command)
    if chat_id is not None and chat_id != 0:
        cursor.execute("SELECT rank FROM scoped_command_locks WHERE scope=? AND chat_id=? AND command=?", ("chat", int(chat_id), command))
        row = cursor.fetchone()
        if row:
            return row[0]
    cursor.execute("SELECT rank FROM scoped_command_locks WHERE scope=? AND chat_id=0 AND command=?", ("global", command))
    row = cursor.fetchone()
    if row:
        return row[0]
    cursor.execute("SELECT rank FROM private_command_locks WHERE command=?", (command,))
    row = cursor.fetchone()
    return row[0] if row else COMMAND_LOCK_DEFAULTS.get(command, "Developer")

def set_command_lock(command, rank, chat_id=None, global_scope=False):
    command = normalize_private_command(command)
    if global_scope or chat_id is None or chat_id == 0:
        cursor.execute("INSERT OR REPLACE INTO scoped_command_locks(scope, chat_id, command, rank) VALUES(?,?,?,?)", ("global", 0, command, rank))
        cursor.execute("INSERT OR REPLACE INTO private_command_locks(command, rank) VALUES(?,?)", (command, rank))
    else:
        cursor.execute("INSERT OR REPLACE INTO scoped_command_locks(scope, chat_id, command, rank) VALUES(?,?,?,?)", ("chat", int(chat_id), command, rank))
    conn.commit()

def open_command_lock(command, chat_id=None, global_scope=False):
    command = normalize_private_command(command)
    default_rank = COMMAND_LOCK_DEFAULTS.get(command, "Developer")
    if global_scope or chat_id is None or chat_id == 0:
        cursor.execute("DELETE FROM scoped_command_locks WHERE scope=? AND chat_id=0 AND command=?", ("global", command))
        cursor.execute("INSERT OR REPLACE INTO private_command_locks(command, rank) VALUES(?,?)", (command, default_rank))
    else:
        cursor.execute("DELETE FROM scoped_command_locks WHERE scope=? AND chat_id=? AND command=?", ("chat", int(chat_id), command))
    conn.commit()

def is_command_hidden(command, chat_id):
    command = normalize_private_command(command)
    cursor.execute("SELECT hidden FROM scoped_command_visibility WHERE scope=? AND chat_id=? AND command=?", ("chat", int(chat_id), command))
    row = cursor.fetchone()
    if row:
        return bool(row[0])
    cursor.execute("SELECT hidden FROM scoped_command_visibility WHERE scope=? AND chat_id=0 AND command=?", ("global", command))
    row = cursor.fetchone()
    return bool(row[0]) if row else False

def set_command_hidden(command, chat_id=None, global_scope=False, hidden=True):
    command = normalize_private_command(command)
    scope = "global" if global_scope or chat_id is None or chat_id == 0 else "chat"
    scope_chat_id = 0 if scope == "global" else int(chat_id)
    if hidden:
        cursor.execute("INSERT OR REPLACE INTO scoped_command_visibility(scope, chat_id, command, hidden) VALUES(?,?,?,1)", (scope, scope_chat_id, command))
    else:
        cursor.execute("DELETE FROM scoped_command_visibility WHERE scope=? AND chat_id=? AND command=?", (scope, scope_chat_id, command))
    conn.commit()

def locked_command_denied(message, command):
    command = normalize_private_command(command)
    if command == "اضف تفاعل" and get_command_lock(command, message.chat.id) == "Disabled":
        bot.reply_to(message, "• امر ↤ اضف تفاعل\n• ملغي من البوت")
        return
    lock = get_command_lock(command, message.chat.id)
    text = {
        "Developer": "المطور",
        "Owner": "Owner وما اعلى",
        "Owner²": "Owner² وما اعلى",
        "Helper": "Helper وما اعلى",
        "Member": "Member وما اعلى",
    }.get(lock, "المطور")
    bot.reply_to(message, f"• هذا الامر يخص ↤ {text}")

def can_use_locked_command(user_id, chat_id, command):
    lock = get_command_lock(command, chat_id)
    if lock == "Disabled":
        return False
    if lock == "Developer":
        return user_id in OWNER_IDS
    if user_id in OWNER_IDS:
        return True
    level = get_rank_level(user_id, chat_id)
    return level >= {"Member":0, "Helper":1, "Owner²":2, "Owner":3}.get(lock, 0)

def get_rank(user_id, chat_id):
    # رتبة Dev محجوزة حصراً للمعرّفات الموجودة في OWNER_IDS ولا يمكن رفعها أو تغييرها.
    if user_id in OWNER_IDS:
        return "Dev"

    cursor.execute(
        "SELECT rank FROM users WHERE user_id=? AND chat_id=?",
        (user_id, chat_id)
    )
    row = cursor.fetchone()
    return row[0] if row else "Member"

def is_dev_or_owner(user_id, chat_id):
    return user_id in OWNER_IDS or get_rank(user_id, chat_id) in ("Dev", "Owner")

def deny_rank(message, required_rank):
    # رسالة موحدة لكل الأوامر التي لها حد أدنى للرتبة.
    # الأوامر الخاصة بالمطور (الاوامر/الحماية/الحماية المتقدمة/التنظيف)
    # لا تستخدم هذه الدالة، ولها رسالتها الخاصة.
    mention = get_mention(message.from_user)
    rank_text = str(required_rank).strip()
    if rank_text in ("المطور", "Owner", "O", "o"):
        required_text = "Owner"
    elif rank_text in ("Owner²", "Owner2", "O2", "o2", "المطور الثاني"):
        required_text = "Owner²"
    elif rank_text in ("Helper", "H", "h"):
        required_text = "Helper"
    else:
        required_text = rank_text

    bot.reply_to(
        message,
        f"• عذرا يا 「 {mention} 」\n"
        f"• هذا الامر يخص: ← 「 {html.escape(required_text)} وما اعلى 」",
        parse_mode="HTML"
    )

def deny_callback_rank(call, required_rank):
    bot.answer_callback_query(
        call.id,
        f"• هذا الامر يخص 「 {required_rank} 」",
        show_alert=True
    )

RANK_LEVELS = {
    "Member": 0,
    "Helper": 1,
    "Owner²": 2,
    "Owner": 3,
}

def get_rank_level(user_id, chat_id):
    if user_id in OWNER_IDS:
        return 4
    rank = get_rank(user_id, chat_id)
    return RANK_LEVELS.get(rank, 0)

def register_group_stats(chat, active=1, invite_link=None, increment=0):
    """يحفظ بيانات القروب وإحصائياته بشكل مستقل عن جدول الرتب."""
    try:
        if not chat or getattr(chat, "type", None) not in ["group", "supergroup"]:
            return
        chat_id = int(chat.id)
        title = html.unescape(getattr(chat, "title", None) or "القروب")
        username = getattr(chat, "username", None)
        now = int(time.time())
        cursor.execute(
            """
            INSERT INTO group_stats(chat_id, title, username, invite_link, message_count, active, updated_at)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(chat_id) DO UPDATE SET
                title = COALESCE(excluded.title, group_stats.title),
                username = COALESCE(excluded.username, group_stats.username),
                invite_link = COALESCE(excluded.invite_link, group_stats.invite_link),
                message_count = group_stats.message_count + excluded.message_count,
                active = excluded.active,
                updated_at = excluded.updated_at
            """,
            (chat_id, title, username, invite_link, int(increment), int(active), now)
        )
        conn.commit()
    except Exception as e:
        print(f"[GROUP STATS ERROR] {e}")


def get_reliable_group_url(chat):
    """يرجع رابط القروب العام أو رابط دعوة محفوظ/فعلي، مع حفظه للإشعارات الخاصة."""
    if not chat:
        return None
    chat_id = int(chat.id)
    try:
        username = getattr(chat, "username", None)
        if username:
            url = f"https://t.me/{username}"
            register_group_stats(chat, active=1, invite_link=url, increment=0)
            return url
    except Exception:
        pass

    # استخدم الرابط المحفوظ أولاً حتى لا تعتمد التحذيرات الخاصة على export كل مرة.
    try:
        cursor.execute("SELECT invite_link FROM group_stats WHERE chat_id=?", (chat_id,))
        row = cursor.fetchone()
        if row and row[0]:
            return row[0]
    except Exception:
        pass

    try:
        fresh = bot.get_chat(chat_id)
        invite = getattr(fresh, "invite_link", None)
        if invite:
            register_group_stats(fresh, active=1, invite_link=invite, increment=0)
            return invite
    except Exception:
        pass

    try:
        invite = bot.export_chat_invite_link(chat_id)
        if invite:
            register_group_stats(chat, active=1, invite_link=invite, increment=0)
            return invite
    except Exception:
        pass
    return None


def _message_content_fingerprint(message):
    """بصمة المحتوى الفعلي للرسالة، بعيدًا عن بيانات العضو التي قد تتغير وحدها."""
    try:
        data = {
            "content_type": getattr(message, "content_type", None),
            "text": getattr(message, "text", None),
            "caption": getattr(message, "caption", None),
            "entities": [tuple(getattr(e, k, None) for k in ("type", "offset", "length", "url", "language", "custom_emoji_id")) for e in (getattr(message, "entities", None) or [])],
            "caption_entities": [tuple(getattr(e, k, None) for k in ("type", "offset", "length", "url", "language", "custom_emoji_id")) for e in (getattr(message, "caption_entities", None) or [])],
        }
        # Telegram يرسل photo كقائمة PhotoSize، لذلك قراءة file_unique_id
        # من القائمة نفسها تعطي None وتخلي استبدال الصورة يبدو كأنه لم يتغير.
        # نأخذ هوية الملف الفعلية (آخر/أكبر PhotoSize للصورة).
        for attr in ("photo", "video", "document", "audio", "animation", "voice", "sticker", "video_note"):
            obj = getattr(message, attr, None)
            if obj is None:
                continue
            if isinstance(obj, (list, tuple)):
                media_ids = []
                for item in obj:
                    mid = getattr(item, "file_unique_id", None) or getattr(item, "file_id", None)
                    if mid:
                        media_ids.append(str(mid))
                if media_ids:
                    data[attr] = tuple(media_ids)
            else:
                data[attr] = getattr(obj, "file_unique_id", None) or getattr(obj, "file_id", None)
        return repr(data)
    except Exception:
        return repr((getattr(message, "content_type", None), getattr(message, "text", None), getattr(message, "caption", None)))


def _remember_message_content(message):
    """يحفظ آخر محتوى معروف للرسالة حتى لا نعتبر تغيّر لقب العضو تعديلاً للنص."""
    try:
        chat = getattr(message, "chat", None)
        if not message or not chat or getattr(chat, "type", None) not in ["group", "supergroup"]:
            return
        key = (int(chat.id), int(message.message_id))
        message_content_fingerprints[key] = (time.time(), _message_content_fingerprint(message))
        if len(message_content_fingerprints) > MESSAGE_FINGERPRINT_LIMIT:
            oldest_key = next(iter(message_content_fingerprints), None)
            if oldest_key is not None:
                message_content_fingerprints.pop(oldest_key, None)
    except Exception as e:
        print(f"[MESSAGE FINGERPRINT ERROR] {e}")


def _remember_deletion_item(message, category_override=None):
    """يسجل الرسالة في سجل الحذف حسب نوعها، بدون حفظ نصوص أو وسائط كاملة."""
    try:
        if not message or getattr(getattr(message, "chat", None), "type", None) not in ["group", "supergroup"]:
            return
        user = getattr(message, "from_user", None)
        chat_id = int(message.chat.id)
        message_id = int(message.message_id)
        categories = {"all"}
        if category_override:
            categories.add(category_override)
        else:
            content_type = getattr(message, "content_type", None)
            mapping = {
                "photo": "photo",
                "video": "video",
                "animation": "animation",
                "sticker": "sticker",
                "voice": "voice",
                "audio": "audio",
            }
            if content_type in mapping:
                categories.add(mapping[content_type])
            text = getattr(message, "text", None) or ""
            caption = getattr(message, "caption", None) or ""
            if contains_link(text) or contains_link(caption):
                categories.add("links")
        if not categories:
            return
        with delete_history_lock:
            chat_history = delete_history.setdefault(chat_id, {})
            entry = chat_history.setdefault(message_id, set())
            entry.update(categories)
            if len(chat_history) > DELETE_HISTORY_LIMIT_PER_CHAT:
                oldest_ids = sorted(chat_history)[:len(chat_history) - DELETE_HISTORY_LIMIT_PER_CHAT]
                for old_id in oldest_ids:
                    chat_history.pop(old_id, None)
    except Exception as e:
        print(f"[DELETE HISTORY ERROR] {e}")


def _remember_edited_for_deletion(message):
    """يسجل الرسالة المعدلة حتى يظهر عداد «رسائل معدلة» في الحذف."""
    try:
        if not message or getattr(getattr(message, "chat", None), "type", None) not in ["group", "supergroup"]:
            return
        user = getattr(message, "from_user", None)
        if user is not None and getattr(user, "is_bot", False):
            return
        _remember_deletion_item(message, "edited")
    except Exception as e:
        print(f"[EDITED HISTORY ERROR] {e}")


def _deletion_snapshot(chat_id, category=None):
    with delete_history_lock:
        history = delete_history.get(int(chat_id), {})
        if category is None:
            return list(history.keys())
        return [mid for mid, cats in history.items() if category in cats]


def _forget_deletion_message(chat_id, message_id):
    with delete_history_lock:
        history = delete_history.get(int(chat_id))
        if history is not None:
            history.pop(int(message_id), None)
            if not history:
                delete_history.pop(int(chat_id), None)


def track_message(message):
    """تسجيل رسالة واحدة للمستخدم ولعداد رسائل القروب."""
    try:
        if not message or message.chat.type not in ["group", "supergroup"]:
            return
        # قفل الوسائط في حماية 3 يعمل مبكرًا من مسار التتبع أيضًا.
        try:
            _u = getattr(message, "from_user", None)
            _mkey = {"photo":"media_lock_photo", "animation":"media_lock_gif", "video":"media_lock_video", "sticker":"media_lock_sticker"}.get(getattr(message, "content_type", ""))
            if _u and _mkey and not is_full_protection_exempt(_u.id, message.chat.id) and advanced_protection_state(message.chat.id, _mkey):
                safe_delete_message(message.chat.id, message.message_id)
                return
        except Exception as _p3err:
            print(f"[PROTECTION 3 TRACK ERROR] {_p3err}", flush=True)
        # سجل أنواع الوسائط/الروابط لأوامر الحذف، ثم خزن البصمة كالمعتاد.
        _remember_deletion_item(message)
        # نأخذ البصمة قبل أي حماية؛ Telegram قد يرسل edited_message عند تغيّر لقب
        # العضو رغم أن نص الرسالة نفسه لم يتغير.
        _remember_message_content(message)
        user = getattr(message, "from_user", None)
        if not user or getattr(user, "is_bot", False):
            return
        chat_id = message.chat.id

        # سجل أفعال أوامر البوت المهمة. لا نسجل الرسائل العادية حتى يبقى السجل مفيدًا.
        _audit_text = (getattr(message, "text", None) or "").strip()
        _audit_exact = {
            "المطور", "مطور", "الاوامر", "رتبتي", "رتبته", "قائمة", "قائمة الرتب",
            "قائمة المكتومين", "قائمة المقيدين", "قائمة المحظورين", "مسح المكتومين",
            "مسح المقيدين", "مسح المحظورين", "فك القيود", "رفع مشرف", "تنزيل مشرف",
            "رفع", "تنزيل", "حذف", "مسح الكل", "حك", "الحماية", "تفعيل حماية المتقدمة",
            "تفعيل حماية 2", "تفعيل الحماية 2", "تعطيل حماية 2", "تعطيل الحماية 2",
            "تفعيل التنظيف", "استثناء", "استثناء عام", "استنثاء", "استنثاء عام",
            "استثناء العام", "الاستثناء العام", "تفعيل استثناء عام", "تعطيل استثناء عام",
            "احصائيات", "توب", "التوب", "توب قروبات", "توب القروبات", "المحددين", "قائمة المحددين", "قائمه المحددين", "تنظيف رسائل البوتات", "تعطيل تنظيف التحديد", "تفعيل تنظيف التحديد", "تصفير توب قروبات", "تصفير توب القروبات", "تصفير توب المتفاعلين", "تصفير توب متفاعلين", "تصفير توب", "اضف تفاعل", "الغاء امر اضف تفاعل", "تشغيل امر اضف تفاعل", "الغاء امر عام اضف تفاعل", "تشغيل امر عام اضف تفاعل", "4", "5", "O", "O2", "H"
        }
        _audit_prefixes = (
            "رفع مشرف ", "تنزيل مشرف ", "رفع ", "تنزيل ", "قفل امر ", "فتح امر ", "الغاء امر ", "تشغيل امر ",
            "تفعيل حماية ", "تعطيل حماية ", "تفعيل الحماية ", "تعطيل الحماية ",
            "تفعيل حماية متقدمة ", "تعطيل حماية متقدمة "
        )
        if _audit_text != "سجل" and (_audit_text in _audit_exact or any(_audit_text.startswith(x) for x in _audit_prefixes)):
            try:
                _actor_m = get_mention(user)
                _target = getattr(getattr(message, "reply_to_message", None), "from_user", None)
                _target_part = f" على {get_mention(_target)}" if _target else ""
                add_security_log(chat_id, "أمر بوت", f"{_actor_m} نفذ الأمر «{html.escape(_audit_text)}»{_target_part}", _actor_m)
            except Exception as _audit_error:
                print(f"[SECURITY AUDIT COMMAND ERROR] {_audit_error}", flush=True)
        user_id = user.id
        username = getattr(user, "username", None)
        first_name = getattr(user, "first_name", None) or ""
        last_name = getattr(user, "last_name", None) or ""
        cursor.execute(
            """
            INSERT INTO users(user_id, chat_id, rank, username, msg_count, first_name, last_name)
            VALUES(?, ?, ?, ?, 1, ?, ?)
            ON CONFLICT(user_id, chat_id) DO UPDATE SET
                msg_count = COALESCE(users.msg_count, 0) + 1,
                username = excluded.username,
                first_name = excluded.first_name,
                last_name = excluded.last_name
            """,
            (user_id, chat_id, "Member", username, first_name, last_name)
        )
        register_group_stats(message.chat, active=1, increment=0)
        conn.commit()
    except Exception as e:
        print(f"[STATS ERROR] تعذر تسجيل الرسالة: {e}")

def can_manage_rank(actor_id, chat_id, target_rank):
    actor_level = get_rank_level(actor_id, chat_id)
    target_level = RANK_LEVELS.get(target_rank, 0)
    return actor_level > target_level

def can_change_rank_safely(actor_id, chat_id, target_rank):
    """منع رفع/تنزيل شخص رتبته مساوية أو أعلى من المنفذ."""
    return get_rank_level(actor_id, chat_id) > RANK_LEVELS.get(target_rank, 0)


def rank_change_denied(message, action="رفع"):
    """رسالة حسب العملية عند محاولة تعديل شخص رتبته مساوية أو أعلى."""
    action_text = "ترفع" if action == "رفع" else "تنزل"
    bot.reply_to(
        message,
        f"• ما تقدر {action_text} شخص رتبته مساوية لك او اعلى منها",
    )


def requested_rank_not_higher_than_current(message, target, requested_rank, current_rank):
    """لا تسمح بتحويل صاحب رتبة أعلى إلى رتبة أدنى عبر أمر الرفع."""
    current_level = RANK_LEVELS.get(current_rank, 0)
    requested_level = RANK_LEVELS.get(requested_rank, 0)
    if current_level >= requested_level:
        bot.reply_to(
            message,
            f"• رتبة ↤︎ {get_mention(target)}\n"
            f"• مساوية أو اعلى من {html.escape(requested_rank)}",
            parse_mode="HTML"
        )
        return True
    return False


def required_rank_for_target(target_rank):
    if target_rank == "Owner":
        return "المطور"
    if target_rank == "Owner²":
        return "Owner"
    if target_rank == "Helper":
        return "Owner²"
    return "Helper"

def schedule_cleaning_delete(chat_id, message_id, delay):
    """جدولة حذف مؤجل مع Event مستقل يمكن لأمر الاستثناء إلغاؤه."""
    key = (int(chat_id), int(message_id))
    with general_exception_lock:
        # فحصان داخل نفس القفل: يمنع إنشاء مهمة تنظيف لرسالة استُثنيت للتو.
        if key in EXEMPTED_MESSAGE_KEYS or key in EXCEPTION_HARD_BLOCK or key in general_exception_cancelled:
            return
        if is_general_exception_id(chat_id, message_id):
            return
        if key in cleaning_delete_pending:
            return
        cleaning_delete_pending.add(key)
        event = threading.Event()
        cleaning_delete_events[key] = event
    threading.Thread(
        target=delete_after_delay,
        args=(chat_id, message_id, delay, event),
        daemon=True
    ).start()


def delete_after_delay(chat_id, message_id, delay, event=None):
    """ينتظر المدة ثم يمنح الاستثناء أولوية قبل الحذف، مع نافذة أمان قصيرة."""
    chat_id = int(chat_id)
    message_id = int(message_id)
    key = (chat_id, message_id)
    if event is None:
        with general_exception_lock:
            event = cleaning_delete_events.get(key)
            if event is None:
                event = threading.Event()
                cleaning_delete_events[key] = event
                cleaning_delete_pending.add(key)

    # إذا نفذ الاستثناء في أي وقت أثناء المدة، Event يوقظ المهمة ويلغيها.
    if event.wait(max(0, float(delay))):
        with general_exception_lock:
            cleaning_delete_pending.discard(key)
            cleaning_delete_events.pop(key, None)
        return

    # نافذة أمان تمنع السباق مع تحديث "استثناء" الذي يكون في طريقه للمعالج.
    # نتحقق عدة مرات بدل حذف الرسالة مباشرة عند انتهاء المؤقت.
    for _ in range(5):
        with general_exception_lock:
            if key not in cleaning_delete_pending:
                return
            if key in general_exception_cancelled or is_general_exception_id(chat_id, message_id):
                cleaning_delete_pending.discard(key)
                cleaning_delete_events.pop(key, None)
                return
        if event.wait(0.2):
            with general_exception_lock:
                cleaning_delete_pending.discard(key)
                cleaning_delete_events.pop(key, None)
            return

    with general_exception_lock:
        if key not in cleaning_delete_pending:
            return
        if key in general_exception_cancelled or is_general_exception_id(chat_id, message_id):
            cleaning_delete_pending.discard(key)
            cleaning_delete_events.pop(key, None)
            return
        # أبقِ الحالة مسجلة أثناء استدعاء بوابة الحذف المركزية.
        cleaning_delete_pending.discard(key)
        cleaning_delete_events.pop(key, None)
        if is_general_exception_id(chat_id, message_id):
            return
        try:
            safe_delete_message(chat_id, message_id)
        except Exception:
            pass


def get_mention(user):
    name = html.escape(user.first_name or "المستخدم", quote=True)
    return f'<a href="tg://user?id={user.id}">{name}</a>'

def get_all_devs_text(chat_id):
    """منشن أصحاب الرتب المسجلين في هذا القروب فقط، مع التحقق أنهم ما زالوا أعضاء."""
    try:
        cursor.execute(
            'SELECT user_id, rank FROM users '
            'WHERE chat_id=? AND rank IN ("Owner", "Owner²", "Helper")',
            (chat_id,)
        )
        special_users = cursor.fetchall()
    except Exception as e:
        print(f"[RANK MENTIONS DB ERROR] {e}", flush=True)
        special_users = []

    mentions = []
    seen = set()
    candidates = [(int(uid), str(rank)) for uid, rank in special_users]
    # أضف مالكي البوت فقط إن كانوا أعضاء فعليين في القروب.
    for oid in OWNER_IDS:
        try:
            oid = int(oid)
            if all(uid != oid for uid, _ in candidates):
                candidates.append((oid, "Owner"))
        except Exception:
            continue

    for user_id, rank in candidates:
        if user_id in seen:
            continue
        try:
            member = bot.get_chat_member(chat_id, user_id)
            status = getattr(member, "status", "")
            if status in ("left", "kicked", "banned"):
                continue
        except Exception:
            # عند تعذر التحقق لا نمنشن أشخاصًا قد لا يكونون بالقروب.
            continue
        mentions.append(
            f'<a href="tg://user?id={user_id}">{html.escape(rank)}</a>'
        )
        seen.add(user_id)
    return ", ".join(mentions) if mentions else "لا يوجد أصحاب رتب موجودون في القروب"

def get_bot_username():
    try:
        me = bot.get_me()
        return f"@{me.username}" if me.username else "البوت"
    except Exception:
        return "البوت"

def notify_ranks_bot_added(message):
    chat_id = message.chat.id
    added_by = message.from_user
    cursor.execute(
        'SELECT user_id, rank FROM users WHERE chat_id=? '
        'AND rank IN ("Owner", "Owner²", "Helper")',
        (chat_id,)
    )
    rows = cursor.fetchall()
    mentions = []
    seen = set()
    for owner_id in OWNER_IDS:
        if owner_id not in seen:
            mentions.append(f'<a href="tg://user?id={owner_id}">Owner</a>')
            seen.add(owner_id)
    for user_id, rank in rows:
        if user_id in seen:
            continue
        mentions.append(f'<a href="tg://user?id={user_id}">{html.escape(rank)}</a>')
        seen.add(user_id)
    if not mentions:
        return
    admins_text = "\n".join(f"{i} - {mention}" for i, mention in enumerate(mentions, 1))
    text = (
        "تنبيه\n"
        "━━━━━━━━━━━\n"
        f"{admins_text}\n\n"
        f"• المستخدم ذا : {get_mention(added_by)}\n"
        f"• قام باضافة البوت ذا : {html.escape(get_bot_username())}"
    )
    try:
        bot.send_message(chat_id, text, parse_mode="HTML")
    except Exception as e:
        print(f"خطأ في اشعار اضافة البوت: {e}")

def is_group(message):
    return message.chat.type in ["group", "supergroup"]

def advanced_protection_state(chat_id, key):
    if chat_id not in advanced_protection:
        saved = load_json_setting(chat_id, "advanced_protection", None)
        advanced_protection[chat_id] = saved if isinstance(saved, dict) else {
            "info": False, "description": False, "ban": False, "promote": False, "users": False, "photo_spam": False, "channels": False, "warning_spam": False
        }
        if isinstance(saved, dict) and saved.get("forbidden_words"):
            try:
                basic = load_json_setting(chat_id, "basic_protection", {}) or {}
                basic["forbidden_words"] = True
                save_json_setting(chat_id, "basic_protection", basic)
                advanced_protection[chat_id].pop("forbidden_words", None)
                save_json_setting(chat_id, "advanced_protection", advanced_protection[chat_id])
            except Exception:
                pass
        advanced_protection[chat_id].setdefault("description", False)
        advanced_protection[chat_id].setdefault("photo_spam", False)
        advanced_protection[chat_id].setdefault("warning_spam", False)
        advanced_protection[chat_id].setdefault("media_lock_photo", False)
        advanced_protection[chat_id].setdefault("media_lock_gif", False)
        advanced_protection[chat_id].setdefault("media_lock_video", False)
        advanced_protection[chat_id].setdefault("media_lock_sticker", False)
        advanced_protection[chat_id].setdefault("bot_guard", False)
        if advanced_protection[chat_id].get("users"):
            advanced_add_protection[chat_id] = True
    else:
        advanced_protection[chat_id].setdefault("photo_spam", False)
        advanced_protection[chat_id].setdefault("warning_spam", False)
        advanced_protection[chat_id].setdefault("media_lock_photo", False)
        advanced_protection[chat_id].setdefault("media_lock_gif", False)
        advanced_protection[chat_id].setdefault("media_lock_video", False)
        advanced_protection[chat_id].setdefault("media_lock_sticker", False)
    return advanced_protection.get(chat_id, {}).get(key, False)

