@bot.callback_query_handler(func=lambda call: call.data.startswith("basicprotect:"))
def basic_protection_callback(call):
    chat_id = call.message.chat.id
    if not is_dev_or_owner(call.from_user.id, chat_id):
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return

    parts = call.data.split(":")
    value = parts[1] if len(parts) > 1 else ""
    page = 0
    if len(parts) > 2:
        try:
            page = int(parts[2])
        except Exception:
            page = 0

    states = basic_protection.get(chat_id)
    if not isinstance(states, dict):
        states = {}
    for key in BASIC_PROTECTION_LABELS:
        states.setdefault(key, False)

    # نقل الإعداد القديم للحماية من الكلمات الممنوعة من المتقدمة إلى الحماية.
    try:
        legacy_adv = load_json_setting(chat_id, "advanced_protection", {}) or {}
        if isinstance(legacy_adv, dict) and legacy_adv.get("forbidden_words") and not states.get("forbidden_words"):
            states["forbidden_words"] = True
            legacy_adv["forbidden_words"] = False
            save_json_setting(chat_id, "advanced_protection", legacy_adv)
    except Exception:
        pass

    basic_protection[chat_id] = states

    if value == "page":
        try:
            page = int(parts[2])
        except Exception:
            page = 0
        bot.edit_message_reply_markup(
            chat_id, call.message.message_id,
            reply_markup=basic_protection_markup(chat_id, page)
        )
        bot.answer_callback_query(call.id)
        return

    if value in states:
        states[value] = not states[value]
        save_json_setting(chat_id, "basic_protection", states)
        text = "تم تحديث الحماية"
    elif value == "all_on":
        for key in states:
            states[key] = True
        save_json_setting(chat_id, "basic_protection", states)
        text = "تم تفعيل الحماية بالكامل"
    elif value == "all_off":
        for key in states:
            states[key] = False
        save_json_setting(chat_id, "basic_protection", states)
        text = "تم اغلاق الحماية بالكامل"
    elif value == "close":
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    else:
        bot.answer_callback_query(call.id)
        return

    try:
        bot.edit_message_reply_markup(
            chat_id, call.message.message_id,
            reply_markup=basic_protection_markup(chat_id, page)
        )
    except Exception:
        pass
    bot.answer_callback_query(call.id, text)

def handle_advanced_added_user(message):
    """حماية المستخدمين عند إضافة مستخدم إلى المجموعة."""
    chat_id = message.chat.id
    if message.chat.type not in ["group", "supergroup"]:
        return
    if not advanced_protection_enabled(chat_id, "users"):
        return
    actor = message.from_user
    if not actor:
        return
    try:
        bot_id = bot.get_me().id
    except Exception:
        bot_id = None
    actor_rank = get_rank(actor.id, chat_id)
    if actor.id in OWNER_IDS or actor_rank in ["Developer", "Owner"]:
        return
    for added_user in (message.new_chat_members or []):
        if not added_user or (bot_id is not None and added_user.id == bot_id) or actor.id == added_user.id:
            continue
        recent_key = (chat_id, added_user.id)
        recent_now = time.time()
        if recent_now - users_protection_recent.get(recent_key, 0) < 10:
            continue
        users_protection_recent[recent_key] = recent_now

        actor_mention = get_mention(actor)
        target_mention = get_mention(added_user)
        removed = False
        try:
            bot.ban_chat_member(chat_id, added_user.id)
            moderation_add(chat_id, added_user.id, "banned")
            removed = True
        except Exception as e:
            print(f"خطأ في طرد المستخدم عبر حماية المستخدمين: {e}")
        role_removed = False
        if actor_rank in ["Owner²", "Helper"]:
            try:
                cursor.execute("UPDATE users SET rank=? WHERE user_id=? AND chat_id=?", ("Member", actor.id, chat_id))
                conn.commit()
                role_removed = True
            except Exception as e:
                print(f"خطأ في تنزيل رتبة المضاف: {e}")
        result = "تم طرد المضاف للقروب" if removed else "تعذر تنفيذ إجراء الحماية"
        if role_removed:
            result += f" وتنزيل مشرف من : {actor_mention}"
        admin_mentions = get_all_devs_text(chat_id)
        add_security_log(chat_id, "إضافة مستخدم", f"{actor_mention} أضاف {target_mention} — {result}", actor_mention)
        try:
            bot.send_message(chat_id,
                "تنبيه لاصحاب الرتب\n━━━━━━━━━━━\n"
                f"• المستخدم ذا: 「 {actor_mention} 」\n"
                f"• قام باضافة المستخدم ذا: 「 {target_mention} 」\n\n"
                f"{result}\n\n"
                f"منشن الإدارة: {admin_mentions}", parse_mode="HTML")
        except Exception as e:
            print(f"خطأ في تنبيه حماية المستخدمين: {e}")


def handle_advanced_added_user_from_chat_member(event):
    """مسار احتياطي للإضافة عبر ChatMemberUpdated."""
    chat = getattr(event, "chat", None)
    old_member = getattr(event, "old_chat_member", None)
    new_member = getattr(event, "new_chat_member", None)
    actor = getattr(event, "from_user", None)
    target = getattr(new_member, "user", None) if new_member else None
    if not chat or chat.type not in ["group", "supergroup"] or not advanced_protection_enabled(chat.id, "users"):
        return
    if not old_member or not new_member or not actor or not target:
        return
    if getattr(old_member, "status", None) not in ["left", "kicked"] or getattr(new_member, "status", None) not in ["member", "administrator"]:
        return
    if actor.id == target.id:
        return
    try:
        bot_id = bot.get_me().id
    except Exception:
        bot_id = None
    if bot_id is not None and target.id == bot_id:
        return
    actor_rank = get_rank(actor.id, chat.id)
    if actor.id in OWNER_IDS or actor_rank in ["Developer", "Owner"]:
        return
    recent_key = (chat.id, target.id)
    recent_now = time.time()
    if recent_now - users_protection_recent.get(recent_key, 0) < 10:
        return
    users_protection_recent[recent_key] = recent_now
    removed = False
    try:
        bot.ban_chat_member(chat.id, target.id)
        moderation_add(chat.id, target.id, "banned")
        removed = True
    except Exception as e:
        print(f"خطأ في حماية المستخدمين عبر ChatMemberUpdated: {e}")
    role_removed = False
    if actor_rank in ["Owner²", "Helper"]:
        try:
            cursor.execute("UPDATE users SET rank=? WHERE user_id=? AND chat_id=?", ("Member", actor.id, chat.id))
            conn.commit()
            role_removed = True
        except Exception as e:
            print(f"خطأ في تنزيل رتبة المضاف عبر ChatMemberUpdated: {e}")
    actor_mention = get_mention(actor); target_mention = get_mention(target)
    result = "تم طرد المضاف للقروب" if removed else "تعذر تنفيذ إجراء الحماية"
    if role_removed: result += f" وتنزيل مشرف من : {actor_mention}"
    admin_mentions = get_all_devs_text(chat.id)
    add_security_log(chat.id, "إضافة مستخدم", f"{actor_mention} أضاف {target_mention} — {result}", actor_mention)
    try:
        bot.send_message(chat.id, "تنبيه لاصحاب الرتب\n━━━━━━━━━━━\n" f"• المستخدم ذا: 「 {actor_mention} 」\n" f"• قام باضافة المستخدم ذا: 「 {target_mention} 」\n\n" f"{result}\n\n" f"منشن الإدارة: {admin_mentions}", parse_mode="HTML")
    except Exception as e:
        print(f"خطأ في تنبيه حماية المستخدمين عبر ChatMemberUpdated: {e}")


