_DESCRIPTION_RIGHTS_WARNED = set()

def _set_member_change_info_permission(chat_id, enabled):
    """يمنع/يسمح للأعضاء العاديين بتغيير معلومات القروب.

    مهم: Telegram لا يسمح للـ Bot باستخدام setChatPermissions إلا إذا كان
    البوت مشرفاً ولديه صلاحية can_restrict_members (Ban users). إذا لم تكن
    الصلاحية موجودة، نتوقف بهدوء حتى لا يتكرر خطأ 400 في السجل، ولا نعطل
    بقية الحمايات مثل كاشف سورس راد.
    """
    try:
        try:
            me = bot.get_me()
            member = bot.get_chat_member(chat_id, me.id)
            if getattr(member, "status", None) not in ("administrator", "creator"):
                key = (int(chat_id), "not_admin")
                if key not in _DESCRIPTION_RIGHTS_WARNED:
                    _DESCRIPTION_RIGHTS_WARNED.add(key)
                    print(f"[DESCRIPTION PERMISSION] البوت ليس مشرفاً في القروب {chat_id}", flush=True)
                return False
            if getattr(member, "status", None) == "administrator" and not bool(getattr(member, "can_restrict_members", False)):
                key = (int(chat_id), "no_restrict")
                if key not in _DESCRIPTION_RIGHTS_WARNED:
                    _DESCRIPTION_RIGHTS_WARNED.add(key)
                    print(f"[DESCRIPTION PERMISSION] القروب {chat_id}: فعّل للبوت صلاحية Ban Users / تقييد الأعضاء حتى تعمل حماية الوصف.", flush=True)
                return False
        except Exception as e:
            key = (int(chat_id), "check_failed")
            if key not in _DESCRIPTION_RIGHTS_WARNED:
                _DESCRIPTION_RIGHTS_WARNED.add(key)
                print(f"[DESCRIPTION PERMISSION CHECK] {chat_id}: {e}", flush=True)
            return False

        chat = bot.get_chat(chat_id)
        permissions = getattr(chat, "permissions", None)
        if permissions is None:
            print(f"[DESCRIPTION PERMISSION] لا توجد صلاحيات افتراضية للقروب {chat_id}")
            return False

        # نحفظ القيمة الأصلية مرة واحدة حتى لا نغيّر إعداد القروب عند تعطيل الحماية.
        saved = load_json_setting(chat_id, "description_original_can_change_info", None)
        current_value = getattr(permissions, "can_change_info", None)
        if saved is None and current_value is not None:
            save_json_setting(chat_id, "description_original_can_change_info", bool(current_value))
            saved = bool(current_value)

        if hasattr(permissions, "to_dict"):
            data = permissions.to_dict()
        else:
            data = {}
            for name in (
                "can_send_messages", "can_send_audios", "can_send_documents",
                "can_send_photos", "can_send_videos", "can_send_video_notes",
                "can_send_voice_notes", "can_send_polls", "can_send_other_messages",
                "can_add_web_page_previews", "can_invite_users", "can_pin_messages",
                "can_manage_topics", "can_change_info"
            ):
                value = getattr(permissions, name, None)
                if value is not None:
                    data[name] = bool(value)

        # Bot API يقبل مفاتيح الصلاحيات كـ booleans. لا نرسل القيم None.
        data = {k: bool(v) for k, v in data.items() if isinstance(v, bool)}
        data["can_change_info"] = bool(enabled)

        payload = {
            "chat_id": int(chat_id),
            "permissions": data,
        }
        response = requests.post(
            f"https://api.telegram.org/bot{TOKEN}/setChatPermissions",
            json=payload,
            timeout=20
        )
        result = response.json()
        if not result.get("ok"):
            print(f"[DESCRIPTION PERMISSION ERROR] {result}")
            return False
        return True
    except Exception as e:
        print(f"[DESCRIPTION PERMISSION EXCEPTION] {e}")
        return False


