@bot.message_handler(content_types=["new_chat_members"])
def bot_added_handler(message):
    if message.chat.type not in ["group", "supergroup"]:
        return

    # حفظ بيانات المجموعة عند دخول أي أعضاء، بما في ذلك بوتنا نفسه.
    try:
        ensure_original_group_title(message.chat.id, message.chat.title)
    except Exception:
        pass

    # حفظ المجموعة حتى تدخل في عمليات الحظر العام متعددة القروبات.
    try:
        register_group_stats(message.chat, active=1, increment=0)
    except Exception:
        pass
    # إنفاذ الحظر العام وحماية البوتات على الأعضاء الجدد فور إضافتهم.
    try:
        _handle_new_members_global_and_bot_guard(message)
    except Exception as e:
        print(f"[GLOBAL/BOT JOIN GUARD ERROR] {type(e).__name__}: {e}", flush=True)
    # مسار الحماية المتقدمة الأصلي.
    handle_advanced_added_user(message)

