@bot.message_handler(func=lambda message: message.text in ["رتبتي", "رتبته"])
def show_rank(message):
    track_message(message)
    chat_id = message.chat.id
    # إظهار الرتبة يعتمد فقط على خيار «اخفاء رسالة الرتبة».
    # لا نربطه بإخفاء/قفل الأوامر حتى لا تختفي «رتبتي/رتبته» بالخطأ.
    if not rank_messages_enabled(chat_id):
        return
    if message.text == "رتبته" and message.reply_to_message:
        target = message.reply_to_message.from_user
        if getattr(target, "is_bot", False):
            return
        rank = get_rank(target.id, chat_id)
        bot.reply_to(message, f"• رتبته ↤︎ {html.escape(rank)}", parse_mode="HTML")
    else:
        rank = get_rank(message.from_user.id, chat_id)
        bot.reply_to(message, f"• رتبتك ↤︎ {html.escape(rank)}", parse_mode="HTML")

def resolve_target_user(message, target_text=""):
    if getattr(message, "reply_to_message", None):
        user = getattr(message.reply_to_message, "from_user", None)
        if user:
            return user
    value = (target_text or "").strip()
    value = re.sub(r"^(?:ل|الى|إلى)\s+", "", value).strip()
    if not value:
        return None
    if re.fullmatch(r"-?\d+", value):
        try:
            member = bot.get_chat_member(message.chat.id, int(value))
            return member.user if member else None
        except Exception:
            return None
    m = re.search(r"@([A-Za-z0-9_]{5,32})", value)
    if not m:
        return None
    username = m.group(1).lower()
    # ابحث أولاً في أعضاء هذا القروب، ثم في سجل المستخدمين العام؛
    # فقد يكون المستخدم مسجلاً في قروب آخر لكنه عضو في القروب الحالي أيضاً.
    try:
        cursor.execute(
            "SELECT user_id FROM users WHERE chat_id=? AND lower(replace(trim(username), '@', ''))=? ORDER BY rowid DESC LIMIT 1",
            (int(message.chat.id), username)
        )
        row = cursor.fetchone()
        if not row:
            cursor.execute(
                "SELECT user_id FROM users WHERE lower(replace(trim(username), '@', ''))=? ORDER BY rowid DESC LIMIT 10",
                (username,)
            )
            rows = cursor.fetchall()
        else:
            rows = [row]
        for cached_row in rows:
            try:
                member = bot.get_chat_member(int(message.chat.id), int(cached_row[0]))
                if member and getattr(member, "user", None):
                    return member.user
            except Exception:
                continue
    except Exception as e:
        print(f"[RESOLVE USERNAME CACHE ERROR] {e}", flush=True)
    # Fallback: resolve public usernames, including bot usernames, through Telegram,
    # then require the resolved account to be present in the target group.
    try:
        chat_obj = bot.get_chat("@" + m.group(1))
        if getattr(chat_obj, "id", None):
            try:
                member = bot.get_chat_member(message.chat.id, int(chat_obj.id))
                if member and getattr(member, "user", None):
                    return member.user
            except Exception as member_error:
                print(f"[RESOLVE USERNAME MEMBERSHIP ERROR] @{m.group(1)}: {member_error}")
    except Exception as e:
        print(f"[RESOLVE USERNAME FALLBACK] {e}")
    return None


def moderation_add(chat_id, user_id, status):
    try:
        cursor.execute(
            "INSERT OR IGNORE INTO moderation(chat_id,user_id,status) VALUES(?,?,?)",
            (chat_id, user_id, status)
        )
        conn.commit()
        return True
    except Exception as e:
        print(f"[ERROR] moderation_add فشل: {e}")
        return False

def moderation_remove(chat_id, user_id, status):
    try:
        cursor.execute(
            "DELETE FROM moderation WHERE chat_id=? AND user_id=? AND status=?",
            (chat_id, user_id, status)
        )
        conn.commit()
        return True
    except Exception as e:
        print(f"[ERROR] moderation_remove فشل: {e}")
        return False

def moderation_users(chat_id, status):
    cursor.execute(
        "SELECT user_id FROM moderation WHERE chat_id=? AND status=?",
        (chat_id, status)
    )
    ids = {uid for (uid,) in cursor.fetchall()}
    
    if status == "banned" and not ids:
        cursor.execute("SELECT user_id FROM users WHERE chat_id=?", (chat_id,))
        all_users = [uid for (uid,) in cursor.fetchall()]
        for uid in all_users:
            try:
                member = bot.get_chat_member(chat_id, uid)
                if member.status in ["kicked", "banned"]:
                    ids.add(uid)
                    moderation_add(chat_id, uid, "banned")
            except Exception:
                pass
    
    users = []
    for uid in ids:
        try:
            member = bot.get_chat_member(chat_id, uid)
            is_match = False
            if status == "banned":
                is_match = member.status in ["kicked", "banned"]
            elif status == "restricted":
                is_match = member.status == "restricted" and not member.can_send_messages
            if not is_match:
                if status == "banned":
                    users.append(type("UserObj", (), {"id": uid, "first_name": "المستخدم"}))
                    continue
                else:
                    moderation_remove(chat_id, uid, status)
                    continue
            users.append(member.user)
            moderation_add(chat_id, uid, status)
        except Exception:
            if uid in ids and status == "banned":
                users.append(type("UserObj", (), {"id": uid, "first_name": "المستخدم"}))
            elif status == "restricted":
                moderation_add(chat_id, uid, status)
    return users

def restriction_list_text(title, users):
    lines = [f"• {title}", " ━━━━━━━━━"]
    if not users:
        lines.append("لا يوجد")
    else:
        for i, user in enumerate(users, 1):
            lines.append(f"{i} - {get_mention(user)}")
    return "\n".join(lines)

def show_restriction_list(message, kind):
    chat_id = message.chat.id
    rank = get_rank(message.from_user.id, chat_id)
    if kind == "muted":
        if rank not in ["Helper", "Owner²", "Owner"] and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Helper")
            return
        users = []
        for uid in list(muted_users.get(chat_id, {})):
            try:
                users.append(bot.get_chat_member(chat_id, uid).user)
            except Exception:
                class U: pass
                u = U()
                u.id = uid
                u.first_name = "المستخدم"
                users.append(u)
        title = "قائمة المكتومين"
        clear_data = "clearlist:muted"
        clear_label = "مسح المكتومين"
    elif kind == "restricted":
        if rank not in ["Owner²", "Owner"] and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Owner")
            return
        users = moderation_users(chat_id, "restricted")
        title = "قائمة المقيدين"
        clear_data = "clearlist:restricted"
        clear_label = "مسح المقيدين"
    elif kind == "banned":
        if rank != "Owner" and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Owner")
            return
        users = moderation_users(chat_id, "banned")
        title = "قائمة المحظورين"
        clear_data = "clearlist:banned"
        clear_label = "مسح المحظورين"
    else:
        return
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
    markup.row(_styled_button(clear_label, clear_data, "primary"))
    markup.row(_back_button("back_list", "success"), _styled_button("اغلاق", "close_list"))
    bot.send_message(
        chat_id,
        restriction_list_text(title, users),
        reply_markup=markup,
        parse_mode="HTML"
    )

@bot.message_handler(func=lambda m: m.text in ["مسح المكتومين", "مسح المقيدين", "مسح المحظورين"])
def clear_restrictions_command(message):
    track_message(message)
    chat_id = message.chat.id
    rank = get_rank(message.from_user.id, chat_id)
    if message.text == "مسح المكتومين":
        if rank not in ["Helper", "Owner²", "Owner"] and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Helper")
            return
        count = len(muted_users.get(chat_id, {}))
        muted_users.pop(chat_id, None)
        cursor.execute("DELETE FROM temp_mutes WHERE chat_id=?", (chat_id,))
        conn.commit()
        bot.reply_to(message, f"تم مسح ( {count} ) من المكتومين")
    elif message.text == "مسح المقيدين":
        if rank not in ["Owner²", "Owner"] and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Owner")
            return
        # اجمع المقيدين من سجل الإدارة ومن قائمة المستخدمين المحفوظة؛ فقد يكون
        # التقييد موجوداً في تيليجرام بينما سجل moderation فارغ أو قديم.
        ids = set()
        try:
            cursor.execute("SELECT user_id FROM moderation WHERE chat_id=? AND lower(trim(status)) IN ('restricted','media_restricted','restricted_media','media')", (chat_id,))
            ids.update(int(r[0]) for r in cursor.fetchall() if r and r[0] is not None)
            cursor.execute("SELECT user_id FROM users WHERE chat_id=?", (chat_id,))
            ids.update(int(r[0]) for r in cursor.fetchall() if r and r[0] is not None)
        except Exception as e:
            print(f"[CLEAR RESTRICTED COLLECT ERROR] {e}", flush=True)
        count = 0
        perms = _restore_chat_permissions()
        for target_id in ids:
            try:
                member = bot.get_chat_member(chat_id, target_id)
                if getattr(member, "status", None) != "restricted":
                    for st in ("restricted", "media_restricted", "restricted_media", "media"):
                        moderation_remove(chat_id, target_id, st)
                    continue
                bot.restrict_chat_member(chat_id, target_id, permissions=perms)
                for st in ("restricted", "media_restricted", "restricted_media", "media"):
                    moderation_remove(chat_id, target_id, st)
                count += 1
            except Exception as e:
                print(f"[CLEAR RESTRICTED ERROR] user={target_id}: {e}", flush=True)
        bot.reply_to(message, f"• تم مسح التقييد عن ( {count} ) من المقيدين")
    else:
        if rank != "Owner" and message.from_user.id not in OWNER_IDS:
            deny_rank(message, "Owner")
            return
        users = moderation_users(chat_id, "banned")
        count = 0
        for u in users:
            try:
                bot.unban_chat_member(chat_id, u.id)
                moderation_remove(chat_id, u.id, "banned")
                count += 1
            except Exception:
                pass
        bot.reply_to(message, f"تم مسح الحظر عن ( {count} ) من المحظورين")

@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and (m.text.strip() == "فك القيود" or m.text.strip().startswith("فك القيود ")))
def release_restrictions_command(message):
    track_message(message)
    if getattr(message.chat, "type", None) == "private":
        if not message.from_user or int(message.from_user.id) not in OWNER_IDS:
            bot.reply_to(message, "• هذا الأمر للمطور فقط")
            return
        target = resolve_private_global_target(message, (message.text or "")[len("فك القيود"):].strip())
        if not target:
            bot.reply_to(message, "• أرسل فك القيود مع ID أو @username أو بالرد على رسالة المستخدم")
            return
        cursor.execute("DELETE FROM global_bans WHERE user_id=?", (int(target.id),))
        conn.commit()
        restored=0
        for group_id in _active_bot_groups():
            try:
                cursor.execute("SELECT action FROM global_ban_actions WHERE chat_id=? AND user_id=?",(group_id,int(target.id)))
                action_row=cursor.fetchone()
                if not action_row: continue
                action=action_row[0]
                if action=="ban":
                    bot.unban_chat_member(group_id,int(target.id),only_if_banned=True)
                    moderation_remove(group_id,int(target.id),"banned")
                elif action=="restrict":
                    perms=telebot.types.ChatPermissions(can_send_messages=True,can_send_audios=True,can_send_documents=True,can_send_photos=True,can_send_videos=True,can_send_video_notes=True,can_send_voice_notes=True,can_send_polls=True,can_send_other_messages=True,can_add_web_page_previews=True,can_invite_users=True)
                    bot.restrict_chat_member(group_id,int(target.id),permissions=perms)
                    moderation_remove(group_id,int(target.id),"restricted")
                cursor.execute("DELETE FROM global_ban_actions WHERE chat_id=? AND user_id=?",(group_id,int(target.id))); conn.commit()
                restored+=1
            except Exception as e:
                print(f"[GLOBAL UNBAN PRIVATE ERROR] group={group_id} user={target.id}: {e}",flush=True)
        bot.reply_to(message, f"• تم فك الحظر العام عن {get_mention(target)}\n• القروبات التي تمت محاولة فك الحظر فيها: {restored}", parse_mode="HTML")
        return
    chat_id = message.chat.id
    rank = get_rank(message.from_user.id, chat_id)
    if rank != "Owner" and message.from_user.id not in OWNER_IDS:
        deny_rank(message, "Owner")
        return
    target_text = message.text[len("فك القيود"):].strip() if message.text else ""
    target = resolve_target_user(message, target_text)
    if not target:
        bot.reply_to(message, "رد على المستخدم بامر فك القيود")
        return
    target_id = target.id
    target_mention = get_mention(target)
    released = []
    member = None
    try:
        member = bot.get_chat_member(chat_id, target_id)
    except Exception:
        member = None
    try:
        if member is not None and member.status in ["kicked", "banned"]:
            bot.unban_chat_member(chat_id, target_id)
            moderation_remove(chat_id, target_id, "banned")
            released.append("الحظر")
    except Exception:
        pass
    try:
        member = bot.get_chat_member(chat_id, target_id)
        if member.status == "restricted" and not member.can_send_messages:
            perms = telebot.types.ChatPermissions(
                can_send_messages=True,
                can_send_audios=True,
                can_send_documents=True,
                can_send_photos=True,
                can_send_videos=True,
                can_send_video_notes=True,
                can_send_voice_notes=True,
                can_send_polls=True,
                can_send_other_messages=True,
                can_add_web_page_previews=True,
                can_invite_users=True
            )
            bot.restrict_chat_member(chat_id, target_id, permissions=perms)
            moderation_remove(chat_id, target_id, "restricted")
            released.append("التقييد")
    except Exception:
        pass
    muted = muted_users.get(chat_id, {})
    if target_id in muted:
        muted.pop(target_id, None)
        if not muted:
            muted_users.pop(chat_id, None)
        cursor.execute("DELETE FROM temp_mutes WHERE chat_id=? AND user_id=?", (chat_id, target_id))
        conn.commit()
        released.append("الكتم")
    else:
        # حتى لو أُعيد تشغيل البوت وكان الكتم محفوظاً في قاعدة البيانات فقط.
        cursor.execute("SELECT 1 FROM temp_mutes WHERE chat_id=? AND user_id=? AND until_time=0", (chat_id, target_id))
        if cursor.fetchone():
            cursor.execute("DELETE FROM temp_mutes WHERE chat_id=? AND user_id=?", (chat_id, target_id))
            conn.commit()
            released.append("الكتم")
    if released:
        bot.reply_to(
            message,
            f"تم فك القيود عن {target_mention}\n({', '.join(released)})",
            parse_mode="HTML"
        )
    else:
        bot.reply_to(message, f"لا يوجد قيود على {target_mention}", parse_mode="HTML")

