# اختصارات رفع الرتب عند الرد فقط: O / O2 / H
@bot.message_handler(func=lambda message: message.text and message.reply_to_message is not None and message.text.strip().upper() in {"O", "O2", "H"})
def rank_shortcut_reply(message):
    track_message(message)
    if not is_group(message):
        return
    actor_id = message.from_user.id
    chat_id = message.chat.id
    actor_level = get_rank_level(actor_id, chat_id)
    if actor_level <= 0:
        deny_rank(message, "Helper")
        return
    reply = getattr(message, "reply_to_message", None)
    target = getattr(reply, "from_user", None) if reply else None
    if not target:
        return

    requested_rank = {"O": "Owner", "O2": "Owner²", "H": "Helper"}[message.text.strip().upper()]
    target_level = get_rank_level(target.id, chat_id)
    if target_level >= actor_level:
        rank_change_denied(message, "رفع")
        return
    if actor_level <= RANK_LEVELS.get(requested_rank, 0):
        required = required_rank_for_target(requested_rank)
        if required == "المطور":
            required = "Owner"
        bot.reply_to(
            message,
            f"• عذرا يا 「 {get_mention(message.from_user)} 」\n"
            f"• هذا الامر يخص: ← 「 {html.escape(required)} وما اعلى 」",
            parse_mode="HTML"
        )
        return

    current_rank = get_rank(target.id, chat_id)
    if requested_rank_not_higher_than_current(message, target, requested_rank, current_rank):
        return

    try:
        cursor.execute(
            "SELECT user_id FROM users WHERE user_id=? AND chat_id=?",
            (target.id, chat_id)
        )
        if cursor.fetchone():
            cursor.execute(
                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                (requested_rank, target.id, chat_id)
            )
        else:
            cursor.execute(
                "INSERT INTO users(user_id,chat_id,rank,username) VALUES(?,?,?,?)",
                (target.id, chat_id, requested_rank, getattr(target, "username", None))
            )
        conn.commit()
        bot.reply_to(
            message,
            f"• المستخدم ذا ↤︎ {get_mention(target)}\n"
            f"• تم رفعه إلى رتبة {html.escape(requested_rank)}",
            parse_mode="HTML"
        )
        add_security_log(
            chat_id, "رفع رتبة",
            f"{get_mention(message.from_user)} رفع {get_mention(target)} إلى رتبة {html.escape(requested_rank)}",
            get_mention(message.from_user)
        )
    except Exception as e:
        print(f"[RANK SHORTCUT ERROR] {e}")
        bot.reply_to(message, "• تعذر تنفيذ اختصار الرتبة.")


# =========================================================
# رفع / تنزيل الرتب
# =========================================================
@bot.message_handler(
    func=lambda message:
        message.text and message.text.startswith(("رفع ", "تنزيل "))
        and not message.text.startswith(("رفع مشرف", "تنزيل مشرف"))
)
def change_user_rank(message):
    track_message(message)
    chat_id = message.chat.id
    actor_id = message.from_user.id
    actor_level = get_rank_level(actor_id, chat_id)

    # هذا الأمر يتطلب Helper على الأقل.
    if actor_level <= 0:
        deny_rank(message, "Helper")
        return

    parts = message.text.strip().split(maxsplit=2)
    action = parts[0] if parts else ""
    input_rank = parts[1] if len(parts) > 1 else ""
    target_text = parts[2] if len(parts) > 2 else ""

    rank_mapping = {
        "owner": "Owner", "o": "Owner",
        "owner²": "Owner²", "o²": "Owner²",
        "owner2": "Owner²", "o2": "Owner²",
        "helper": "Helper", "h": "Helper"
    }

    # =========================================================
    # أهم نقطة: Reply يأخذ صاحب الرسالة مباشرة.
    # لا نعتمد على username أو قاعدة البيانات إذا كان هناك Reply.
    # =========================================================
    target = None
    reply = getattr(message, "reply_to_message", None)
    if reply is not None:
        target = getattr(reply, "from_user", None)

    # إذا لم يوجد Reply، نستخدم @username أو ID.
    if target is None:
        target = resolve_target_user(message, target_text)

    if target is None:
        # لا يوجد شخص يمكن رفعه/تنزيله.
        bot.reply_to(
            message,
            "يجب الرد على رسالة المستخدم أو كتابة @منشن أو ID المستخدم."
        )
        return

    target_mention = get_mention(target)
    # Compatibility alias: the rank replies below use `mention`.
    # Keep it defined for both رفع and تنزيل paths.
    mention = target_mention
    actor_mention = get_mention(message.from_user)
    target_current_level = get_rank_level(target.id, chat_id)

    # أولاً: لا يمكن تعديل شخص رتبته مساوية أو أعلى من رتبة المنفذ.
    if target_current_level >= actor_level:
        rank_change_denied(message, action)
        return

    # =========================================================
    # رفع
    # =========================================================
    if action == "رفع":
        target_rank = rank_mapping.get(input_rank.lower())

        if not target_rank:
            bot.reply_to(message, "الرتبة أو الاختصار غير صحيح.")
            return

        # إذا كان الشخص أصلًا على رتبة مساوية أو أعلى من الرتبة المطلوبة،
        # لا ننزله بصمت؛ نثبت رتبته الحالية ونوضح السبب.
        current_target_rank = get_rank(target.id, chat_id)
        if requested_rank_not_higher_than_current(
            message, target, target_rank, current_target_rank
        ):
            return

        target_level = RANK_LEVELS.get(target_rank, 0)

        # لا يستطيع رفع الشخص إلى رتبة مساوية أو أعلى من رتبته.
        if actor_level <= target_level:
            required = required_rank_for_target(target_rank)
            if required == "المطور":
                required = "Owner"
            bot.reply_to(
                message,
                f"• عذرا يا 「 {get_mention(message.from_user)} 」\n"
                f"• هذا الامر يخص: ← 「 {html.escape(required)} وما اعلى 」",
                parse_mode="HTML"
            )
            return

        try:
            cursor.execute(
                "SELECT user_id FROM users WHERE user_id=? AND chat_id=?",
                (target.id, chat_id)
            )

            if cursor.fetchone():
                cursor.execute(
                    "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                    (target_rank, target.id, chat_id)
                )
            else:
                cursor.execute(
                    "INSERT INTO users(user_id,chat_id,rank,username) VALUES(?,?,?,?)",
                    (
                        target.id,
                        chat_id,
                        target_rank,
                        getattr(target, "username", None)
                    )
                )

            conn.commit()

            # تحقق فعلي بعد الحفظ.
            saved_rank = get_rank(target.id, chat_id)
            if saved_rank != target_rank:
                raise RuntimeError("تعذر حفظ الرتبة")

            bot.reply_to(
                message,
                f"• المستخدم ذا ↤︎ {mention}\n"
                f"• تم رفعه إلى رتبة {html.escape(target_rank)}",
                parse_mode="HTML"
            )
            add_security_log(
                chat_id, "رفع رتبة",
                f"{actor_mention} رفع {mention} إلى رتبة {html.escape(target_rank)}",
                actor_mention
            )

        except Exception as e:
            print(f"[RANK PROMOTE ERROR] {e}")
            bot.reply_to(
                message,
                f"• تعذر رفع: 「 {mention} 」 ↤︎ 「 {html.escape(target_rank)} 」",
                parse_mode="HTML"
            )
        return

    # =========================================================
    # تنزيل
    # =========================================================
    current_target_rank = get_rank(target.id, chat_id)

    if current_target_rank == "Member":
        bot.reply_to(
            message,
            f"• المستخدم ذا ↤︎「 {mention} 」\n"
            f"• تم تنزيله إلى رتبة Member",
            parse_mode="HTML"
        )
        return

    try:
        cursor.execute(
            "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
            ("Member", target.id, chat_id)
        )
        conn.commit()

        bot.reply_to(
            message,
            f"• المستخدم ذا ↤︎「 {mention} 」\n"
            f"• تم تنزيله إلى رتبة Member",
            parse_mode="HTML"
        )
    except Exception as e:
        print(f"[RANK DEMOTE ERROR] {e}")
        bot.reply_to(
            message,
            f"• ماقدرت انزل : ↤︎ 「 {mention} 」\n"
            "• السبب: البوت لا يملك صلاحية تعديل المشرفين",
            parse_mode="HTML"
        )


def get_bot_admin_rights(chat_id):
    """Return the bot's current Telegram administrator rights in this chat."""
    try:
        bot_id = bot.get_me().id
        member = bot.get_chat_member(chat_id, bot_id)
        if getattr(member, "status", None) not in ("administrator", "creator"):
            return None
        return {
            "info": bool(getattr(member, "can_change_info", False)),
            "pin": bool(getattr(member, "can_pin_messages", False)),
            "ban": bool(getattr(member, "can_restrict_members", False)),
            "invite": bool(getattr(member, "can_invite_users", False)),
            "del": bool(getattr(member, "can_delete_messages", False)),
            "call": bool(getattr(member, "can_manage_video_chats", False)),
            "add": bool(getattr(member, "can_promote_members", False)),
        }
    except Exception as e:
        print(f"[BOT RIGHTS ERROR] {e}")
        return None


def save_bot_promoted_admin(chat_id, user_id, promoted_by=0):
    try:
        cursor.execute(
            "INSERT OR REPLACE INTO bot_promoted_admins (chat_id, user_id, promoted_by) VALUES (?, ?, ?)",
            (chat_id, user_id, promoted_by)
        )
        conn.commit()
    except Exception as e:
        print(f"[SAVE BOT PROMOTED ERROR] {e}")

def was_bot_promoted_admin(chat_id, user_id):
    try:
        cursor.execute(
            "SELECT 1 FROM bot_promoted_admins WHERE chat_id=? AND user_id=?",
            (chat_id, user_id)
        )
        return cursor.fetchone() is not None
    except Exception as e:
        print(f"[CHECK BOT PROMOTED ERROR] {e}")
        return False


def remove_bot_promoted_admin(chat_id, user_id):
    try:
        cursor.execute(
            "DELETE FROM bot_promoted_admins WHERE chat_id=? AND user_id=?",
            (chat_id, user_id)
        )
        conn.commit()
    except Exception as e:
        print(f"[REMOVE BOT PROMOTED ERROR] {e}")


def apply_admin_permissions(chat_id, target_id, requested, actor_is_dev=False, promoted_by=0):
    """Promote/update an admin while never asking Telegram for a right the bot lacks."""
    bot_rights = get_bot_admin_rights(chat_id)
    if bot_rights is None:
        return False, "ما قدرت أتحقق من صلاحيات البوت في القروب، تأكد إنه مشرف."

    requested = requested or {}
    effective = {}
    for key in ["info", "pin", "ban", "invite", "del", "call", "add", "topics"]:
        want = bool(requested.get(key, False))
        effective[key] = want and bool(bot_rights.get(key, False))

    # Telegram promotion needs the bot to be able to promote admins.
    if effective["add"] and not bot_rights["add"]:
        return False, "البوت ما عنده صلاحية إضافة مشرفين، عطه الصلاحية المطلوبة أول."

    try:
        bot.promote_chat_member(
            chat_id,
            target_id,
            can_change_info=effective["info"],
            can_pin_messages=effective["pin"],
            can_restrict_members=effective["ban"],
            can_invite_users=effective["invite"],
            can_delete_messages=effective["del"],
            can_manage_video_chats=effective["call"],
            can_promote_members=effective["add"],
            can_manage_topics=effective["topics"]
        )
        save_bot_promoted_admin(chat_id, target_id, promoted_by)

        # إذا تمت الترقية بواسطة أمر البوت، حدث chat_member قد يصل باسم البوت
        # وبالتالي لا يمكن الاعتماد عليه وحده للتنبيه. أرسل التنبيه هنا مباشرة.
        if promoted_by:
            try:
                notify_admin_promotion_direct(chat_id, target_id, promoted_by)
            except Exception as alert_error:
                print(f"[DIRECT PROMOTION ALERT ERROR] {alert_error}")

        return True, None
    except Exception as e:
        print(f"[PROMOTE ERROR] {e}")
        return False, str(e)


def get_perms_markup(target_id, chat_id):
    if chat_id not in admin_permissions:
        admin_permissions[chat_id] = {}
    if target_id not in admin_permissions[chat_id]:
        admin_permissions[chat_id][target_id] = {
            "info": False, "pin": False, "ban": False,
            "invite": False, "del": False, "call": False, "add": False, "topics": False
        }
        save_json_setting(chat_id, "admin_permissions", {
            str(tid): perms for tid, perms in admin_permissions[chat_id].items()
        })
    admin_permissions[chat_id][target_id].setdefault("topics", False)
    p = admin_permissions[chat_id][target_id]
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    def get_text(label, key):
        status = "نعم" if p[key] else "لا"
        return f"{label} - {status}"
    markup.add(
        telebot.types.InlineKeyboardButton(
            get_text("تغيير معلومات المجموعة", "info"),
            callback_data=f"toggle:{target_id}:info"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("تثبيت الرسائل", "pin"),
            callback_data=f"toggle:{target_id}:pin"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("حظر المستخدمين", "ban"),
            callback_data=f"toggle:{target_id}:ban"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("دعوة المستخدمين", "invite"),
            callback_data=f"toggle:{target_id}:invite"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("مسح الرسائل", "del"),
            callback_data=f"toggle:{target_id}:del"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("ادارة المكالمات", "call"),
            callback_data=f"toggle:{target_id}:call"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("اضافة مشرفين", "add"),
            callback_data=f"toggle:{target_id}:add"
        ),
        telebot.types.InlineKeyboardButton(
            get_text("إدارة المواضيع", "topics"),
            callback_data=f"toggle:{target_id}:topics"
        ),
        telebot.types.InlineKeyboardButton(
            "جميع الصلاحيات", callback_data=f"allperms:{target_id}"
        ),
        telebot.types.InlineKeyboardButton(
            "اخفاء الامر", callback_data="hide_msg", style="danger"
        )
    )
    return markup

# =========================================================
# إدارة مشرفي تيليجرام
# =========================================================
# إشراف Telegram يُقرأ مباشرة من Telegram، وليس من ranks.db.
# لذلك "تنزيل مشرف" يعمل حتى لو كان الشخص رُفع من إعدادات القروب
# أو قبل إعادة تشغيل البوت.

def get_telegram_admin(chat_id, user_id):
    try:
        member = bot.get_chat_member(chat_id, user_id)
        if getattr(member, "status", None) in ("administrator", "creator"):
            return member
    except Exception as e:
        print(f"[ADMIN READ ERROR] {e}")
    return None


def get_telegram_admins(chat_id):
    try:
        return bot.get_chat_administrators(chat_id)
    except Exception as e:
        print(f"[ADMINS READ ERROR] {e}")
        return []


def telegram_admin_rights(member):
    return {
        "info": bool(getattr(member, "can_change_info", False)),
        "pin": bool(getattr(member, "can_pin_messages", False)),
        "ban": bool(getattr(member, "can_restrict_members", False)),
        "invite": bool(getattr(member, "can_invite_users", False)),
        "del": bool(getattr(member, "can_delete_messages", False)),
        "call": bool(getattr(member, "can_manage_video_chats", False)),
        "add": bool(getattr(member, "can_promote_members", False)),
        "topics": bool(getattr(member, "can_manage_topics", False)),
    }


def sync_target_admin_permissions(chat_id, target_id):
    member = get_telegram_admin(chat_id, target_id)
    if not member:
        return False
    admin_permissions.setdefault(chat_id, {})
    admin_permissions[chat_id][target_id] = telegram_admin_rights(member)
    save_json_setting(chat_id, "admin_permissions", {
        str(tid): perms for tid, perms in admin_permissions[chat_id].items()
    })
    return True


def demote_telegram_admin(chat_id, target_id):
    member = get_telegram_admin(chat_id, target_id)
    if not member:
        return False, "المستخدم هذا مو مشرف حاليًا في القروب."
    if getattr(member, "status", None) == "creator":
        return False, "ما تقدر تنزّل مالك القروب من الإشراف."

    rights = get_bot_admin_rights(chat_id)
    if not rights or not rights.get("add", False):
        return False, "البوت ما عنده صلاحية تعديل المشرفين، عطه صلاحية إضافة المشرفين أول."

    try:
        bot.promote_chat_member(
            chat_id, target_id,
            can_change_info=False,
            can_post_messages=False,
            can_edit_messages=False,
            can_delete_messages=False,
            can_invite_users=False,
            can_restrict_members=False,
            can_pin_messages=False,
            can_promote_members=False,
            can_manage_video_chats=False,
            can_manage_topics=False,
            can_manage_chat=False
        )
        return True, None
    except Exception as e:
        print(f"[DEMOTE ADMIN ERROR] {e}")
        return False, str(e)


@bot.message_handler(
    func=lambda message:
        message.text == "رفع مشرف"
        or (message.text and message.text.startswith("رفع مشرف "))
)
def promote_user_command(message):
    track_message(message)
    if not is_group(message):
        return
    chat_id = message.chat.id

    # عند تفعيل هذا الخيار يتصرف أمر «رفع مشرف» كأنه غير موجود في القروب.
    if bool(load_json_setting(chat_id, "hide_promote_admin_command", False)):
        return

    if not can_use_locked_command(message.from_user.id, chat_id, "رفع مشرف"):
        locked_command_denied(message, "رفع مشرف")
        return

    target_text = message.text[len("رفع مشرف"):].strip()
    # يدعم: "رفع مشرف @user" و "رفع مشرف ل @user".
    if target_text.startswith("ل "):
        target_text = target_text[2:].strip()
    target = None
    if getattr(message, "reply_to_message", None) is not None:
        target = getattr(message.reply_to_message, "from_user", None)
    if target is None:
        # إذا اختار المستخدم شخصاً من قائمة المنشن في تيليجرام، قد يصل
        # كـ text_mention وفيه كائن المستخدم ومعرّفه حتى لو لم يكن في الكاش.
        try:
            for entity in (getattr(message, "entities", None) or []):
                if getattr(entity, "type", "") == "text_mention":
                    entity_user = getattr(entity, "user", None)
                    if entity_user and getattr(entity, "offset", 0) >= len("رفع مشرف"):
                        target = entity_user
                        break
        except Exception as entity_error:
            print(f"[PROMOTE TEXT MENTION ERROR] {entity_error}", flush=True)
    if target is None:
        target = resolve_target_user(message, target_text)

    if not target or not getattr(target, "id", None):
        bot.reply_to(
            message,
            "• ما قدرت أحدد العضو من المنشن.\n"
            "• جرّب تختاره من قائمة المنشن في تيليجرام، أو استخدم آيدي العضو.\n"
            "• مثال: رفع مشرف 123456789"
        )
        return
    try:
        target_member = bot.get_chat_member(chat_id, target.id)
    except Exception:
        target_member = None

    if target_member and getattr(target_member, "status", None) == "creator":
        bot.reply_to(message, "• مالك القروب لا يحتاج إلى رفع مشرف.")
        return

    rights = get_bot_admin_rights(chat_id)
    if not rights or not rights.get("add", False):
        bot.reply_to(
            message,
            f"• ماقدرت ارفع : ↤︎ 「 {get_mention(target)} 」\n"
            "• لازم إعطاء البوت صلاحية إضافة مشرفين أولًا.",
            parse_mode="HTML"
        )
        return

    # إذا كان مشرفًا أصلًا، اقرأ صلاحياته الحقيقية من Telegram.
    if target_member and getattr(target_member, "status", None) == "administrator":
        sync_target_admin_permissions(chat_id, target.id)
    else:
        admin_permissions.setdefault(chat_id, {})
        admin_permissions[chat_id].setdefault(target.id, {
            "info": False, "pin": False, "ban": False,
            "invite": False, "del": False, "call": False,
            "add": False, "topics": False
        })

    bot.reply_to(
        message,
        f"صلاحيات المستخدم - {get_mention(target)}",
        reply_markup=get_perms_markup(target.id, chat_id),
        parse_mode="HTML"
    )


@bot.message_handler(
    func=lambda message:
        message.text == "تنزيل مشرف"
        or (message.text and message.text.startswith("تنزيل مشرف "))
)
def demote_user_command(message):
    track_message(message)
    if not is_group(message):
        return
    chat_id = message.chat.id

    if not can_use_locked_command(message.from_user.id, chat_id, "تنزيل مشرف"):
        locked_command_denied(message, "تنزيل مشرف")
        return

    target_text = message.text[len("تنزيل مشرف"):].strip()
    # يدعم: "تنزيل مشرف @user" و "تنزيل مشرف ل @user".
    if target_text.startswith("ل "):
        target_text = target_text[2:].strip()
    target = None

    if getattr(message, "reply_to_message", None) is not None:
        target = getattr(message.reply_to_message, "from_user", None)
    if target is None:
        target = resolve_target_user(message, target_text)

    if not target:
        bot.reply_to(
            message,
            "يجب الرد على رسالة المستخدم أو كتابة @منشن أو ID المستخدم."
        )
        return

    # أهم إصلاح: قراءة المشرف الحالي من Telegram مباشرة.
    admin_member = get_telegram_admin(chat_id, target.id)
    if not admin_member:
        bot.reply_to(
            message,
            f"• المستخدم ذا ↤︎ 「 {get_mention(target)} 」\n"
            "• ليس مشرفًا حاليًا في القروب.",
            parse_mode="HTML"
        )
        return

    if getattr(admin_member, "status", None) == "creator":
        bot.reply_to(message, "• لا يمكن تنزيل مالك القروب من الإشراف.")
        return

    ok, err = demote_telegram_admin(chat_id, target.id)
    if not ok:
        bot.reply_to(
            message,
            f"• ماقدرت أنزل : ↤︎ 「 {get_mention(target)} 」\n"
            "",
            parse_mode="HTML"
        )
        return

    try:
        cursor.execute(
            "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
            ("Member", target.id, chat_id)
        )
        conn.commit()
    except Exception as e:
        print(f"[DEMOTE RANK SYNC ERROR] {e}")

    remove_bot_promoted_admin(chat_id, target.id)

    try:
        if chat_id in admin_permissions:
            admin_permissions[chat_id].pop(target.id, None)
            save_json_setting(chat_id, "admin_permissions", {
                str(tid): perms for tid, perms in admin_permissions[chat_id].items()
            })
    except Exception as e:
        print(f"[ADMIN PERMS CLEAN ERROR] {e}")

    bot.reply_to(
        message,
        f"• تم تنزيل : ↤︎ 「 {get_mention(target)} 」\n• 「من المشرفين」",
        parse_mode="HTML"
    )
    add_security_log(
        chat_id, "تنزيل مشرف",
        f"{get_mention(message.from_user)} نزل {get_mention(target)} من المشرفين",
        get_mention(message.from_user)
    )


@bot.message_handler(content_types=["new_chat_title", "new_chat_photo"])
def handle_group_info_changes(message):
    chat_id = message.chat.id
    actor = message.from_user
    if actor and is_full_protection_exempt(actor.id, chat_id):
        return
    if not advanced_protection_enabled(chat_id, "info"):
        return
    # إذا لم تكن المعلومة الأصلية محفوظة، نحفظ العنوان الحالي كمرجع أولي.
    ensure_original_group_title(chat_id, message.chat.title)
    try:
        me = bot.get_me()
        if actor and actor.id != me.id:
            actor_rank = get_rank(actor.id, chat_id)
            if actor_rank not in ["Owner"] and actor.id not in OWNER_IDS:
                original_title = get_original_group_title(chat_id)
                try:
                    safe_delete_message(chat_id, message.message_id)
                except Exception:
                    pass

                if message.content_type == "new_chat_title" and original_title:
                    try:
                        bot.set_chat_title(chat_id, original_title)
                    except Exception as e:
                        print(f"تعذر إرجاع اسم المجموعة الأصلي: {e}")
                elif message.content_type == "new_chat_photo":
                    try:
                        bot.delete_chat_photo(chat_id)
                    except Exception:
                        pass

                try:
                    demoted, demote_error = demote_telegram_admin(chat_id, actor.id)
                except Exception as e:
                    demoted, demote_error = False, str(e)
                if demoted:
                    cursor.execute(
                        "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                        ("Member", actor.id, chat_id)
                    )
                    conn.commit()
                elif demote_error:
                    print(f"[INFO DEMOTE FAILED] {demote_error}", flush=True)

                selected_penalty = load_penalties(chat_id).get("info")
                penalty_ok = protection_penalty(chat_id, actor, "info")
                demotion_text = "تم تنزيله من المشرفين" if demoted else "لم يتم تنزيله من المشرفين"
                penalty_text = {
                    "ban": "تم حظره" if penalty_ok else "لم يتم حظره",
                    "restrict": "تم تقييده" if penalty_ok else "لم يتقيد",
                    "mute": "تم كتمه" if penalty_ok else "لم يتم كتمه",
                }.get(selected_penalty, "لم يتم تطبيق العقوبة")
                penalty_action_text = f"{demotion_text} و{penalty_text}"

                mention = get_mention(actor)
                all_devs_text = get_all_devs_text(chat_id)
                restored_text = "تم إرجاع اسم المجموعة الأصلي." if message.content_type == "new_chat_title" and original_title else "تم رفض تغيير معلومات المجموعة."
                info_change_type = (
                    "قام يتغير اسم القروب"
                    if message.content_type == "new_chat_title"
                    else "قام بتغير صورة القروب"
                )
                info_alert_text = (
                    "• الحق القروب تغيرت معلوماته !!!\n"
                    f"• اسم القروب: {_security_group_link(message.chat)}\n"
                    f"• الوصخ اللي قاعد يغير: {mention}\n"
                    f"•{info_change_type}\n"
                    f"• {penalty_action_text}"
                )
                add_security_log(
                    chat_id,
                    "تغيير معلومات القروب",
                    f"{info_change_type} — {penalty_action_text}",
                    mention
                )
                _send_private_security_alert_with_same_buttons(message.chat, actor, info_alert_text)

                warning_msg = (
                    "<b>تحذير أمني</b>\n"
                    f"قام الMember {mention} بتغيير معلومات المجموعة بدون إذن.\n"
                    f"{restored_text}\n"
                    f"{penalty_action_text}.\n\n"
                    f"<b>الإداريون المعنيون:</b> {all_devs_text}"
                )
                send_advanced_warning(chat_id, warning_msg)
    except Exception as e:
        print(f"خطأ في حماية معلومات المجموعة: {e}")

def _extract_new_chat_description(message):
    """استخراج وصف القروب الجديد حتى مع اختلاف نسخة pyTelegramBotAPI."""
    value = getattr(message, "new_chat_description", None)
    if value is not None:
        return str(value)
    try:
        data = message.to_dict() if hasattr(message, "to_dict") else {}
        if isinstance(data, dict) and "new_chat_description" in data:
            value = data.get("new_chat_description")
            return "" if value is None else str(value)
    except Exception:
        pass
    try:
        raw = getattr(message, "json", None)
        if isinstance(raw, str):
            data = json.loads(raw)
            if isinstance(data, dict) and "new_chat_description" in data:
                value = data.get("new_chat_description")
                return "" if value is None else str(value)
    except Exception:
        pass
    return None


def _restore_group_description(chat_id, description):
    """إرجاع الوصف باستخدام المكتبة ثم Bot API مباشرة كمسار احتياطي."""
    description = description or ""
    try:
        bot.set_chat_description(chat_id, description)
        return True
    except Exception as first_error:
        try:
            response = requests.post(
                f"https://api.telegram.org/bot{TOKEN}/setChatDescription",
                json={"chat_id": int(chat_id), "description": description},
                timeout=20
            )
            result = response.json()
            if result.get("ok"):
                return True
            print(f"[DESCRIPTION RESTORE API ERROR] {result}", flush=True)
        except Exception as second_error:
            print(f"[DESCRIPTION RESTORE FALLBACK ERROR] {second_error}", flush=True)
        print(f"[DESCRIPTION RESTORE ERROR] {first_error}", flush=True)
    return False


def _send_description_warning_always(chat_id, text):
    """يرسل إنذار حماية الوصف دون أن يمنعه إعداد إخفاء التنبيهات."""
    try:
        bot.send_message(chat_id, text, parse_mode="HTML")
        add_security_log(chat_id, "حماية تغيير وصف القروب", text)
        return True
    except Exception as e:
        print(f"[DESCRIPTION WARNING ERROR] chat={chat_id}: {e}", flush=True)
        try:
            bot.send_message(chat_id, html.unescape(re.sub(r"<[^>]+>", "", text)))
            return True
        except Exception as fallback_error:
            print(f"[DESCRIPTION WARNING FALLBACK ERROR] chat={chat_id}: {fallback_error}", flush=True)
            return False


def handle_group_description_changes(message, detected_description=None):
    """حماية تغيير وصف القروب، مع تمرير الوصف مباشرة من Update الخام عند توفره."""
    chat_id = message.chat.id
    actor = getattr(message, "from_user", None)
    if actor and is_full_protection_exempt(actor.id, chat_id):
        return
    if not advanced_protection_enabled(chat_id, "description"):
        return
    try:
        setattr(message, "_description_protection_handled", True)
        # Telegram قد يرسل وصفاً فارغاً عند حذف البايو، لذلك الفراغ نفسه تغيير صالح يجب حمايته.
        new_description = detected_description
        if new_description is None:
            new_description = _extract_new_chat_description(message)
        if new_description is None:
            print(f"[DESCRIPTION PROTECTION] وصل معالج التغيير بلا قيمة وصف قابلة للقراءة في القروب {chat_id}", flush=True)
            return
        new_description = str(new_description)

        me = bot.get_me()
        if actor and actor.id == me.id:
            return
        actor_id = getattr(actor, "id", None) if actor else None

        # لا نستثني OWNER_IDS أو رتبة Owner من فحص الوصف؛ وإلا قد يغيّر
        # مالك البوت الوصف أثناء الاختبار دون إنذار أو استعادة. الاستثناء الوحيد هو البوت نفسه أعلاه.

        # لا نعتبر تغيير العضو مرجعاً شرعياً إذا لم يكن هناك مرجع محفوظ.
        # المرجع يُحفظ عند تفعيل الحماية/تفعيل الكل، لذلك عدم وجوده هنا يعني
        # أن البوت لا يملك وصفاً سابقاً موثوقاً يمكنه إرجاعه إليه.
        original_description = get_original_group_description(chat_id)
        if original_description is None:
            # محاولة أخيرة لجلب الوصف السابق من إعدادات القروب لا تنجح بعد التغيير،
            # لذلك لا نعتمد وصف العضو كمرجع ولا نتركه يمر بصمت.
            print(f"[DESCRIPTION PROTECTION] لا يوجد وصف أصلي محفوظ للقروب {chat_id}; تعذر الاسترجاع بأمان. تأكد أن البوت مشرف ويملك صلاحية تغيير المعلومات.", flush=True)
            _send_description_warning_always(
                chat_id,
                "• تنبيه أمني: حاول عضو تغيير وصف القروب، لكن لا يوجد وصف سابق محفوظ لاستعادته. "
                "لم يتم اعتماد الوصف الجديد كمرجع. أعد تفعيل الحماية بعد التأكد من صلاحيات البوت."
            )
            return
        # إذا كان الوصف الحالي هو الوصف الشرعي فلا توجد مخالفة.
        if new_description == original_description:
            return

        restored = _restore_group_description(chat_id, original_description)
        if actor is None:
            warning_msg = (
                "• تنبيه أمني\n"
                "تم رصد محاولة تغيير وصف القروب، لكن تعذر تحديد صاحب التغيير من تحديث تيليجرام.\n"
                f"• الإجراء: {'تم إرجاع وصف القروب' if restored else 'تعذر إرجاع وصف القروب'}"
            )
            _send_description_warning_always(chat_id, warning_msg)
            add_security_log(chat_id, "تغيير وصف القروب", "تعذر تحديد صاحب التغيير")
            return

        penalties = load_penalties(chat_id)
        selected_penalty = penalties.get("description") or "restrict"
        if penalties.get("description") != selected_penalty:
            penalties["description"] = selected_penalty
            save_json_setting(chat_id, "protection_penalties", penalties)

        try:
            demoted, demote_error = demote_telegram_admin(chat_id, actor.id)
        except Exception as e:
            demoted, demote_error = False, str(e)
        if demoted:
            cursor.execute(
                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                ("Member", actor.id, chat_id)
            )
            conn.commit()
        elif demote_error:
            print(f"[DESCRIPTION DEMOTE FAILED] {demote_error}", flush=True)

        penalty_ok = protection_penalty(chat_id, actor, "description")
        demotion_text = "تم تنزيله من المشرفين" if demoted else "لم يتم تنزيله من المشرفين"
        penalty_text = {
            "ban": "تم حظره" if penalty_ok else "لم يتم حظره",
            "restrict": "تم تقييده" if penalty_ok else "لم يتقيد",
            "mute": "تم كتمه" if penalty_ok else "لم يتم كتمه",
        }.get(selected_penalty, "لم يتم تطبيق العقوبة")
        penalty_action_text = f"{demotion_text} و{penalty_text}"

        mention = get_mention(actor)
        all_devs_text = get_all_devs_text(chat_id)
        warning_msg = (
            "• تنبيه أمني\n"
            "تم رصد تغيير وصف القروب وإرجاع الوصف السابق.\n"
            f"• الشخص اللي غيّر الوصف: {mention}\n"
            f"• الإجراء: {'تم إرجاع وصف القروب' if restored else 'تعذر إرجاع وصف القروب'}\n\n"
            f"منشن الأدارة : {all_devs_text}"
        )
        _send_description_warning_always(chat_id, warning_msg)

        alert_text = (
            '• الحق القروب تغيرت معلوماته !!! <tg-emoji emoji-id="4915853119839011973">⚠️</tg-emoji>\n'
            f"• اسم القروب: {_security_group_link(message.chat)}\n"
            f"• الوصخ اللي قاعد يغير: {mention}\n"
            "•قام بتغيير بايو القروب\n"
            f"• {penalty_action_text}"
        )
        add_security_log(
            chat_id,
            "تغيير وصف القروب",
            f"تم تغيير الوصف — {penalty_action_text}",
            mention
        )
        _send_private_security_alert_description(message.chat, actor, alert_text)
    except Exception as e:
        print(f"خطأ في حماية تغيير وصف القروب: {e}", flush=True)


@bot.message_handler(content_types=["new_chat_description"])
def _new_chat_description_service_handler(message):
    """مسار احتياطي مباشر لخدمة تغيير وصف القروب إذا لم يلتقطها فحص Update."""
    try:
        if getattr(message, "chat", None) and getattr(message.chat, "type", None) in ("group", "supergroup"):
            if not getattr(message, "_description_protection_handled", False):
                handle_group_description_changes(message)
    except Exception as e:
        print(f"[DESCRIPTION SERVICE HANDLER ERROR] {e}", flush=True)

# =========================================================
# تنبيهات الحماية الخاصة لأصحاب الرتب
# =========================================================
SECURITY_ALERT_RANKS = {"Helper", "Owner²", "Owner"}

def _security_group_link(chat):
    # رابط صالح للاستخدام في الخاص: رابط عام أو رابط دعوة حقيقي.
    try:
        return get_group_link(chat)
    except Exception:
        title = html.escape(getattr(chat, "title", None) or "القروب", quote=True)
        return title

def _security_user_url(user):
    username = getattr(user, "username", None)
    return f"https://t.me/{username}" if username else f"tg://user?id={user.id}"

def _security_alert_recipients(chat_id):
    ids = set(OWNER_IDS)
    try:
        cursor.execute(
            'SELECT user_id FROM users WHERE chat_id=? AND rank IN ("Helper","Owner²","Owner")',
            (chat_id,)
        )
        ids.update(row[0] for row in cursor.fetchall())
    except Exception as e:
        print(f"[SECURITY RECIPIENTS ERROR] {e}")
    return ids

def send_private_security_alert(chat, actor, text):
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    name = html.escape(actor.first_name or "المستخدم")
    markup.row(telebot.types.InlineKeyboardButton(
        name, url=_security_user_url(actor)
    ))
    group_url = get_reliable_group_url(chat)
    if group_url:
        markup.row(telebot.types.InlineKeyboardButton(
            "رابط القروب", url=group_url, style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))

    for user_id in _security_alert_recipients(chat.id):
        try:
            if user_id not in OWNER_IDS and get_rank(user_id, chat.id) not in SECURITY_ALERT_RANKS:
                continue
            try:
                bot.send_message(
                    user_id, text, reply_markup=markup, parse_mode="HTML"
                )
            except Exception:
                # إذا فشل HTML، نرسل نفس التنبيه كنص عادي بدون أكواد HTML
                # وبدون إظهار أي Exception للمستخدم.
                plain_text = re.sub(r"<[^>]+>", "", text)
                plain_text = html.unescape(plain_text)
                bot.send_message(user_id, plain_text, reply_markup=markup)
        except Exception as e:
            # المستخدم لم يبدأ محادثة مع البوت: Telegram يرجع 403، وهذا ليس عطلاً في الحماية.
            # لا نعيد المحاولة ولا نطبع الخطأ حتى لا يتكرر في اللوج.
            if "bot can't initiate conversation with a user" in str(e).lower():
                continue
            print(f"[PRIVATE SECURITY ALERT ERROR] {user_id}: {e}")

def _get_ban_tracker():
    # ضمان وجود المتتبع حتى لو تم تشغيل جزء من السورس عبر exec أو إعادة تحميله.
    tracker = globals().get("ban_tracker")
    if not isinstance(tracker, dict):
        tracker = {}
        globals()["ban_tracker"] = tracker
    return tracker


def _security_warning_markup(chat, user):
    """نفس أزرار تحذير رفع المشرفين: القروب ثم الشخص، بنفس النمط والإيموجي."""
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    group_url = get_reliable_group_url(chat)
    if group_url:
        group_name = html.escape(getattr(chat, "title", None) or "القروب", quote=True)
        markup.row(telebot.types.InlineKeyboardButton(
            group_name, url=group_url, style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))
    if user:
        user_name = html.escape(
            getattr(user, "first_name", None) or getattr(user, "username", None) or "المستخدم",
            quote=True
        )
        markup.row(telebot.types.InlineKeyboardButton(
            user_name, url=_security_user_url(user), style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))
    return markup


def _send_private_security_alert_description(chat, actor, text):
    """تنبيه خاص لحماية الوصف: زر الشخص ثم زر القروب، كلاهما أزرق وبنفس إيموجي الحماية."""
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    if actor:
        user_name = html.escape(
            getattr(actor, "first_name", None) or getattr(actor, "username", None) or "المستخدم",
            quote=True
        )
        markup.row(telebot.types.InlineKeyboardButton(
            user_name, url=_security_user_url(actor), style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))
    group_url = get_reliable_group_url(chat)
    if group_url:
        group_name = html.escape(getattr(chat, "title", None) or "القروب", quote=True)
        markup.row(telebot.types.InlineKeyboardButton(
            group_name, url=group_url, style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))
    for user_id in _security_alert_recipients(chat.id):
        try:
            bot.send_message(user_id, text, reply_markup=markup, parse_mode="HTML")
        except Exception as e:
            try:
                plain = html.unescape(re.sub(r"<[^>]+>", "", text))
                bot.send_message(user_id, plain, reply_markup=markup)
            except Exception as e2:
                if "bot can't initiate conversation with a user" in str(e).lower() or "bot can't initiate conversation with a user" in str(e2).lower():
                    continue
                print(f"[DESCRIPTION PRIVATE ALERT ERROR] {user_id}: {e} | fallback: {e2}")

def _send_private_security_alert_with_same_buttons(chat, actor, text):
    markup = _security_warning_markup(chat, actor)
    for user_id in _security_alert_recipients(chat.id):
        try:
            bot.send_message(user_id, text, reply_markup=markup, parse_mode="HTML")
        except Exception as e:
            try:
                plain = re.sub(r"<[^>]+>", "", text)
                plain = html.unescape(plain)
                bot.send_message(user_id, plain, reply_markup=markup)
            except Exception as e2:
                # Telegram يمنع البوت من بدء محادثة خاصة مع مستخدم لم يضغط /start.
                # تجاهل الحالة بصمت، ولا تعتبرها خطأ في نظام الحماية.
                err1 = str(e).lower()
                err2 = str(e2).lower()
                if "bot can't initiate conversation with a user" in err1 or "bot can't initiate conversation with a user" in err2:
                    continue
                print(f"[PRIVATE SECURITY ALERT ERROR] {user_id}: {e} | fallback: {e2}")


@bot.chat_member_handler(func=lambda event: True)
def track_admin_actions(event):
    try:
        handle_advanced_added_user_from_chat_member(event)
    except Exception as e:
        print(f"[USERS PROTECTION EVENT ERROR] {e}")
    try:
        chat = getattr(event, "chat", None)
        actor = getattr(event, "from_user", None)
        old_member = getattr(event, "old_chat_member", None)
        new_member = getattr(event, "new_chat_member", None)
        old_status = getattr(old_member, "status", "")
        new_status = getattr(new_member, "status", "")
        target = getattr(new_member, "user", None)
        if chat and actor and target and target.id != getattr(bot.get_me(), "id", None):
            actor_m = get_mention(actor)
            target_m = get_mention(target)
            if old_status != "administrator" and new_status == "administrator":
                add_security_log(chat.id, "رفع مشرف", f"{actor_m} رفع {target_m} إلى المشرفين", actor_m)
            elif old_status == "administrator" and new_status == "member":
                add_security_log(chat.id, "تنزيل مشرف", f"{actor_m} نزل {target_m} من المشرفين", actor_m)
            elif new_status in ("kicked", "banned") and old_status not in ("kicked", "banned"):
                add_security_log(chat.id, "حظر عضو", f"{actor_m} حظر {target_m}", actor_m)
            elif new_status == "left" and old_status not in ("left", "kicked", "banned"):
                add_security_log(chat.id, "خروج عضو", f"{target_m} خرج من القروب", actor_m)
    except Exception as e:
        print(f"[SECURITY AUDIT MEMBER ERROR] {e}", flush=True)

    # تنبيه إعطاء الحظر يُرسل فقط عند تحقق مخالفة الحماية.

    chat_id = event.chat.id
    actor = event.from_user
    try:
        bot_id = bot.get_me().id
    except Exception:
        bot_id = None
    # حماية إعطاء صلاحية الحظر يجب أن تعمل فقط عند منح الصلاحية فعليًا.
    # Telegram قد يرسل ChatMemberUpdated عند تغيير لقب المشرف (custom_title)
    # مع بقاء الحالة والصلاحيات كما هي؛ لذلك لا نعتبر كل تحديث للمشرف "مخالفة".
    old_member = getattr(event, "old_chat_member", None)
    new_member = getattr(event, "new_chat_member", None)
    old_status = getattr(old_member, "status", None)
    new_status = getattr(new_member, "status", None)
    old_ban_permission = bool(getattr(old_member, "can_restrict_members", False))
    new_ban_permission = bool(getattr(new_member, "can_restrict_members", False))

    # تغيير اللقب/البيانات أو أي تحديث آخر لمشرف يملك صلاحية الحظر مسبقًا
    # لا يدخل في الحماية. المخالفة فقط عند ترقية عضو إلى مشرف أو عند منح
    # صلاحية الحظر لمشرف لم تكن لديه.
    actual_admin_promotion = (
        new_status == "administrator"
        and (
            old_status != "administrator"
            or (not old_ban_permission and new_ban_permission)
        )
    )

    if (
        advanced_protection_enabled(chat_id, "promote")
        and new_member is not None
        and actual_admin_promotion
    ):
        if actor and actor.id != bot_id:
            actor_rank = get_rank(actor.id, chat_id)
            if actor_rank not in ["Owner", "Developer"] and actor.id not in OWNER_IDS:
                # حماية رفع المشرفين: المخالفة هنا فقط عندما انتقلت صلاحية الحظر
                # من غير موجودة إلى موجودة، وليس عند تعديل لقب المشرف.
                has_ban_permission = new_ban_permission
                if has_ban_permission:
                    target_user = new_member.user
                    try:
                        actor_demoted = False
                        target_demoted = False
                        actor_restricted = False
                        target_restricted = False

                        # تنزيل صلاحيات من أعطى الحظر
                        try:
                            bot.promote_chat_member(
                                chat_id, actor.id,
                                can_change_info=False, can_delete_messages=False,
                                can_invite_users=False, can_restrict_members=False,
                                can_pin_messages=False, can_promote_members=False,
                                can_manage_video_chats=False, can_manage_chat=False
                            )
                            actor_demoted = True
                            cursor.execute(
                                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                                ("Member", actor.id, chat_id)
                            )
                        except Exception as demote_error:
                            print(f"[SECURITY DEMOTE ACTOR ERROR] {demote_error}")

                        # تنزيل صلاحيات من نال الحظر
                        try:
                            bot.promote_chat_member(
                                chat_id, target_user.id,
                                can_change_info=False, can_delete_messages=False,
                                can_invite_users=False, can_restrict_members=False,
                                can_pin_messages=False, can_promote_members=False,
                                can_manage_video_chats=False, can_manage_chat=False
                            )
                            target_demoted = True
                            cursor.execute(
                                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                                ("Member", target_user.id, chat_id)
                            )
                        except Exception as demote_error:
                            print(f"[SECURITY DEMOTE TARGET ERROR] {demote_error}")

                        conn.commit()
                        perms = telebot.types.ChatPermissions(can_send_messages=False)

                        try:
                            bot.restrict_chat_member(chat_id, actor.id, permissions=perms)
                            moderation_add(chat_id, actor.id, "restricted")
                            actor_restricted = True
                        except Exception as restrict_error:
                            print(f"[SECURITY RESTRICT ACTOR ERROR] {restrict_error}")

                        try:
                            bot.restrict_chat_member(chat_id, target_user.id, permissions=perms)
                            moderation_add(chat_id, target_user.id, "restricted")
                            target_restricted = True
                        except Exception as restrict_error:
                            print(f"[SECURITY RESTRICT TARGET ERROR] {restrict_error}")

                        actor_mention = get_mention(actor)
                        target_mention = get_mention(target_user)
                        all_devs_text = get_all_devs_text(chat_id)
                        all_handled = actor_demoted and target_demoted and actor_restricted and target_restricted

                        if all_handled:
                            warning_msg = (
                                "<b>تحذير أمني خطير (رصد مباشر)</b>\n"
                                f"الMember {actor_mention} قام بإعطاء {target_mention} صلاحية الحظر.\n\n"
                                "<b>تم التعامل مع المخالفة بنجاح:</b>\n"
                                "• تم تنزيل الطرفين من المشرفين.\n"
                                "• تم تقييد الطرفين.\n\n"
                                f"<b>الإداريون المعنيون:</b> {all_devs_text}"
                            )
                        else:
                            failed = []
                            if not actor_demoted: failed.append("تنزيل الشخص الذي أعطى الصلاحية")
                            if not target_demoted: failed.append("تنزيل الشخص الذي نال الصلاحية")
                            if not actor_restricted: failed.append("تقييد الشخص الذي أعطى الصلاحية")
                            if not target_restricted: failed.append("تقييد الشخص الذي نال الصلاحية")
                            warning_msg = (
                                "<b>تحذير أمني خطير (رصد مباشر)</b>\n"
                                f"الMember {actor_mention} قام بإعطاء {target_mention} صلاحية الحظر.\n\n"
                                "<b>تم التعامل مع المخالفة جزئيًا:</b>\n"
                                f"• تعذر تنفيذ: {html.escape('، '.join(failed))}\n\n"
                                f"<b>الإداريون المعنيون:</b> {all_devs_text}"
                            )
                        send_advanced_warning(chat_id, warning_msg)

                        # تنبيه الخاص لا يفشل عمل الحماية إذا كان أحد الـ Owner قد حظر البوت.
                        try:
                            group_name = bot.get_chat(chat_id).title or "القروب"
                            private_warning = (
                                "• تم رصد محاولة إعطاء حظر\n"
                                f"• اسم القروب : {html.escape(group_name)}\n"
                                f"• الشخص الذي أعطى الصلاحية : {actor_mention}\n"
                                f"• الشخص الذي نالها : {target_mention}\n\n"
                                + ("• تم التعامل مع الوضع وتقييد الاثنين" if all_handled else "• تم تنفيذ الحماية جزئيًا")
                            )
                            promotion_markup = _security_warning_markup(event.chat, actor)
                            for owner_id in OWNER_IDS:
                                try:
                                    bot.send_message(owner_id, private_warning, reply_markup=promotion_markup, parse_mode="HTML")
                                except Exception as alert_error:
                                    # 403 = المستخدم حظر البوت؛ لا داعي لطباعة الخطأ وإزعاج سجل التشغيل.
                                    if "403" not in str(alert_error) and "blocked by the user" not in str(alert_error).lower():
                                        print(f"خطأ في إرسال تنبيه إعطاء الحظر للخاص: {alert_error}")
                        except Exception as alert_error:
                            if "403" not in str(alert_error) and "blocked by the user" not in str(alert_error).lower():
                                print(f"خطأ في تنبيه الخاص لحماية إعطاء الحظر: {alert_error}")


                    except Exception as e:
                        print(f"خطأ في رصد الترقية: {e}")
    # حماية الحظر المتكرر: نرصد فقط انتقال العضو فعليًا إلى kicked/banned
    # حتى لا نحسب تحديثات العضوية الأخرى كعمليات حظر.
    old_member = getattr(event, "old_chat_member", None)
    new_member = getattr(event, "new_chat_member", None)
    old_status = getattr(old_member, "status", None)
    new_status = getattr(new_member, "status", None)
    is_real_ban_event = (
        new_member is not None
        and new_status in ("kicked", "banned")
        and old_status not in ("kicked", "banned")
    )
    if advanced_protection_enabled(chat_id, "ban") and is_real_ban_event:
        if actor and actor.id != bot_id:
            actor_rank = get_rank(actor.id, chat_id)
            if actor_rank not in ["Owner", "Developer"] and actor.id not in OWNER_IDS:
                banned_user = getattr(new_member, "user", None)
                if banned_user:
                    current_time = time.time()
                    key = (chat_id, actor.id)
                    tracker = _get_ban_tracker()
                    records = tracker.setdefault(key, [])
                    records[:] = [
                        item for item in records
                        if current_time - item["time"] < 60
                    ]
                    # كل حظر فعلي = عملية واحدة، والحد هو أكثر من 3 حظرات خلال دقيقة.
                    records.append({"time": current_time, "user": banned_user})
                    if len(records) > 3:
                        try:
                            demoted = False
                            restricted = False
                            unbanned_mentions = []
                            unban_success_count = 0
                            bot.promote_chat_member(
                                chat_id, actor.id,
                                can_change_info=False,
                                can_delete_messages=False,
                                can_invite_users=False,
                                can_restrict_members=False,
                                can_pin_messages=False,
                                can_promote_members=False,
                                can_manage_video_chats=False,
                                can_manage_chat=False
                            )
                            demoted = True
                            cursor.execute(
                                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                                ("Member", actor.id, chat_id)
                            )
                            conn.commit()
                            perms = telebot.types.ChatPermissions(can_send_messages=False)
                            try:
                                bot.restrict_chat_member(chat_id, actor.id, permissions=perms)
                                moderation_add(chat_id, actor.id, "restricted")
                                restricted = True
                            except Exception:
                                restricted = False
                            for record in records:
                                b_user = record["user"]
                                unbanned_mentions.append(get_mention(b_user))
                                try:
                                    bot.unban_chat_member(chat_id, b_user.id)
                                    unban_success_count += 1
                                except Exception:
                                    pass
                            tracker[key] = []
                            actor_mention = get_mention(actor)
                            banned_list_text = ", ".join(unbanned_mentions)
                            all_devs_text = get_all_devs_text(chat_id)
                            action_lines = [
                                f"• {'تم تنزيله' if demoted else 'لم يتم تنزيله'} من المشرفين",
                                f"• {'تم تقييده' if restricted else 'لم يتقيد'}",
                                f"• {'تم فك الحظر عن جميع المستخدمين' if unban_success_count == len(records) else f'تم فك الحظر عن {unban_success_count} من {len(records)} مستخدمين'}"
                            ]
                            warning_msg = (
                                "<b>تحذير أمني خطير (تخطي الحد المسموح للحظر)</b>\n"
                                f"الMember {actor_mention} قام بحظر أكثر من 3 أعضاء في أقل من دقيقة!\n\n"
                                "<b>نتيجة الإجراء:</b>\n"
                                + "\n".join(action_lines) + "\n"
                                + f"• المستخدمون: ({banned_list_text})\n\n"
                                + f"<b>الإداريون المعنيون:</b> {all_devs_text}"
                            )
                            # رسالة القروب: التحذير الأمني الرسمي فقط.
                            try:
                                send_advanced_warning(chat_id, warning_msg)
                            except Exception as alert_error:
                                print(f"خطأ في إرسال تحذير الحظر المتكرر داخل القروب: {alert_error}")

                            # هذه الرسالة خاصة فقط للـ Owner/المطور.
                            ban_alert_text = (
                                "• الحق القروب قاعد يتفلش !!!\n"
                                f"• اسم القروب: {html.escape(getattr(event.chat, 'title', None) or 'القروب')}\n"
                                f"• الوصخ اللي قاعد يفلش: {get_mention(actor)}\n"
                                "•قام بطرد أكثر من 3 أعضاء في أقل من دقيقة\n"
                                f"• {'تم تنزيله' if demoted else 'لم يتم تنزيله'} من المشرفين\n"
                                f"• {'تم تقييده' if restricted else 'لم يتقيد'}"
                            )
                            try:
                                _send_private_security_alert_with_same_buttons(event.chat, actor, ban_alert_text)
                            except Exception as alert_error:
                                print(f"خطأ في إرسال تنبيه الحظر المتكرر للخاص: {alert_error}")

                        except Exception as e:
                            print(f"خطأ في معالجة تكرار الحظر: {e}")

@bot.callback_query_handler(func=lambda call: call.data.startswith("toggle:") or call.data == "hide_msg")
def callback_perms_handler(call):
    chat_id = call.message.chat.id
    actor = call.from_user
    if call.data == "hide_msg":
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    data = call.data.split(":")
    target_id = int(data[1])
    key = data[2]
    if chat_id not in admin_permissions or target_id not in admin_permissions[chat_id]:
        get_perms_markup(target_id, chat_id)
    current_state = admin_permissions[chat_id][target_id][key]
    new_state = not current_state
    actor_rank = get_rank(actor.id, chat_id)
    if actor_rank not in ["Owner"] and actor.id not in OWNER_IDS and key == "ban" and new_state is True:
        try:
            bot.promote_chat_member(
                chat_id, actor.id,
                can_change_info=False,
                can_delete_messages=False,
                can_invite_users=False,
                can_restrict_members=False,
                can_pin_messages=False,
                can_promote_members=False,
                can_manage_video_chats=False,
                can_manage_chat=False
            )
            actor_demoted = False
            target_demoted = False
            actor_restricted = False
            target_restricted = False
            cursor.execute(
                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                ("Member", actor.id, chat_id)
            )
            actor_demoted = True
            bot.promote_chat_member(
                chat_id, target_id,
                can_change_info=False,
                can_delete_messages=False,
                can_invite_users=False,
                can_restrict_members=False,
                can_pin_messages=False,
                can_promote_members=False,
                can_manage_video_chats=False,
                can_manage_chat=False
            )
            target_demoted = True
            cursor.execute(
                "UPDATE users SET rank=? WHERE user_id=? AND chat_id=?",
                ("Member", target_id, chat_id)
            )
            conn.commit()
            perms = telebot.types.ChatPermissions(can_send_messages=False)
            try:
                bot.restrict_chat_member(chat_id, actor.id, permissions=perms)
                moderation_add(chat_id, actor.id, "restricted")
                actor_restricted = True
            except Exception:
                pass
            try:
                bot.restrict_chat_member(chat_id, target_id, permissions=perms)
                moderation_add(chat_id, target_id, "restricted")
                target_restricted = True
            except Exception:
                pass
            try:
                safe_delete_message(chat_id, call.message.message_id)
            except Exception:
                pass
            actor_mention = get_mention(actor)
            all_devs_text = get_all_devs_text(chat_id)
            warning_msg = (
                "<b>تحذير أمني خطير (عبر أزرار البوت)</b>\n"
                f"الMember {actor_mention} حاول منح صلاحية الحظر عبر لوحة التحكم.\n\n"
                "<b>نتيجة الإجراء:</b>\n"
                f"• {'تم تنزيله' if actor_demoted else 'لم يتم تنزيله'} من المشرفين.\n"
                f"• {'تم تقييده' if actor_restricted else 'لم يتقيد'}.\n"
                f"• {'تم تنزيله' if target_demoted else 'لم يتم تنزيله'} من المشرفين للمستخدم المستهدف.\n"
                f"• {'تم تقييده' if target_restricted else 'لم يتقيد'} للمستخدم المستهدف.\n\n"
                f"<b>الإداريون المعنيون:</b> {all_devs_text}"
            )
            send_advanced_warning(chat_id, warning_msg)
            bot.answer_callback_query(call.id, "تم رصد المخالفة ومعاقبتك!", show_alert=True)
            return
        except Exception as e:
            print(f"خطأ في معالجة أزرار الصلاحيات: {e}")
    admin_permissions[chat_id][target_id][key] = new_state
    save_json_setting(chat_id, "admin_permissions", {
        str(tid): perms for tid, perms in admin_permissions[chat_id].items()
    })
    p = admin_permissions[chat_id][target_id]
    ok, err = apply_admin_permissions(
        chat_id,
        target_id,
        p,
        actor_is_dev=(actor_rank == "Owner" or actor.id in OWNER_IDS),
        promoted_by=actor.id
    )
    if not ok:
        # Do not leave the UI saying that a permission is active when Telegram rejected it.
        admin_permissions[chat_id][target_id][key] = current_state
        save_json_setting(chat_id, "admin_permissions", {
            str(tid): perms for tid, perms in admin_permissions[chat_id].items()
        })
        bot.answer_callback_query(call.id, err or "ما قدرت أطبّق الصلاحيات، تأكد من صلاحيات البوت وحاول مرة ثانية.", show_alert=True)
    else:
        bot.answer_callback_query(call.id, "تم التحديث")
    markup = get_perms_markup(target_id, chat_id)
    try:
        bot.edit_message_reply_markup(chat_id, call.message.message_id, reply_markup=markup)
    except Exception:
        pass

CLEAN_TYPES = {
    "photo": "صور",
    "video": "فيديوهات",
    "animation": "صور متحركة",
    "voice": "تسجيلات صوتية",
    "audio": "صوتيات",
    "document": "ملفات",
    "sticker": "ملصقات",
    "video_note": "رسائل فيديو دائرية",
    "location": "مواقع",
    "venue": "أماكن",
    "poll": "استطلاعات",
    "dice": "ألعاب",
    "links": "روابط",
}

def cleaning_options_markup(chat_id):
    settings = cleaning_pending.get(chat_id, {})
    def btn(key, label):
        enabled = bool(settings.get(key))
        return _styled_button(
            f"{label} - {'نعم' if enabled else 'لا'}",
            f"cleanopt:{key}",
            "success" if enabled else "danger"
        )
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
    markup.row(btn("photo", "صور"), btn("video", "فيديوهات"))
    markup.row(btn("animation", "صور متحركة"), btn("voice", "تسجيلات صوتية"))
    markup.row(btn("audio", "صوتيات"), btn("document", "ملفات"))
    markup.row(btn("sticker", "ملصقات"), btn("video_note", "رسائل فيديو دائرية"))
    markup.row(btn("location", "مواقع"), btn("venue", "أماكن"))
    markup.row(btn("poll", "استطلاعات"), btn("dice", "ألعاب"))
    markup.row(btn("links", "روابط"))
    markup.row(_styled_button("تحديد الكل", "cleanopt:all", "success"))
    markup.row(
        _styled_button("تفعيل", "cleanopt:save", "success"),
        _styled_button("الغاء", "cleanopt:cancel", "danger")
    )
    markup.row(_back_button())
    markup.row(commands_close_button("owner_cmd:close"))
    return markup

def cleaning_disable_result_markup():
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    markup.row(_back_button())
    markup.row(commands_close_button("owner_cmd:close"))
    return markup

@bot.message_handler(func=lambda message: message.text == "تفعيل التنظيف")
def activate_cleaning(message):
    track_message(message)
    chat_id = message.chat.id
    if not can_use_locked_command(message.from_user.id, chat_id, "تفعيل التنظيف"):
        developer_only_reply(message)
        return
    if message.from_user.id not in OWNER_IDS:
        developer_only_reply(message)
        return
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
    btns = [
        ("20 ثانية", "clean:20"),
        ("30 ثانية", "clean:30"),
        ("1 دقيقة", "clean:60"),
        ("2 دقيقة", "clean:120"),
        ("5 دقائق", "clean:300"),
        ("تعطيل", "clean:0"),
    ]
    for text_btn, data in btns:
        markup.add(telebot.types.InlineKeyboardButton(text_btn, callback_data=data))
    bot.reply_to(message, "اختر توقيت حذف الوسائط:", reply_markup=markup)

@bot.callback_query_handler(func=lambda call: call.data.startswith("clean:"))
def clean_callback(call):
    chat_id = call.message.chat.id
    if call.from_user.id not in OWNER_IDS:
        # الأزرار لا تستجيب لغير المطور، بينما كتابة الأمر نفسه تبقى لها رسالة الصلاحية.
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return
    try:
        seconds = int(call.data.split(":")[1])
    except (TypeError, ValueError):
        bot.answer_callback_query(call.id)
        return
    if seconds == 0:
        cleaning_mode.pop(chat_id, None)
        cleaning_settings.pop(chat_id, None)
        cleaning_pending.pop(chat_id, None)
        delete_setting(chat_id, "cleaning")
        bot.edit_message_text("تم تعطيل التنظيف.", chat_id, call.message.message_id, reply_markup=cleaning_disable_result_markup())
        bot.answer_callback_query(call.id)
        return
    cleaning_pending[chat_id] = {
        "seconds": seconds,
        "photo": False,
        "video": False,
        "animation": False,
        "voice": False,
        "audio": False,
        "document": False,
        "sticker": False,
        "video_note": False,
        "location": False,
        "venue": False,
        "poll": False,
        "dice": False,
        "links": False,
    }
    try:
        edit_commands_message(
            bot, call, "ايش تبي تنظف:", cleaning_options_markup(chat_id)
        )
    except Exception:
        bot.send_message(chat_id, "ايش تبي تنظف:", reply_markup=cleaning_options_markup(chat_id))
    bot.answer_callback_query(call.id)

@bot.callback_query_handler(func=lambda call: call.data.startswith("cleanopt:"))
def clean_options_callback(call):
    chat_id = call.message.chat.id
    if call.from_user.id not in OWNER_IDS:
        # الأزرار لا تستجيب لغير المطور، بينما كتابة الأمر نفسه تبقى لها رسالة الصلاحية.
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return
    if chat_id not in cleaning_pending:
        bot.answer_callback_query(call.id, "انتهت جلسة إعداد التنظيف، اكتب تفعيل التنظيف من جديد.", show_alert=True)
        return
    action = call.data.split(":", 1)[1]
    settings = cleaning_pending[chat_id]
    if action in CLEAN_TYPES:
        settings[action] = not settings.get(action, False)
        bot.edit_message_reply_markup(chat_id, call.message.message_id, reply_markup=cleaning_options_markup(chat_id))
        bot.answer_callback_query(call.id)
        return
    if action == "all":
        for key in CLEAN_TYPES:
            settings[key] = True
        bot.edit_message_reply_markup(chat_id, call.message.message_id, reply_markup=cleaning_options_markup(chat_id))
        bot.answer_callback_query(call.id, "تم تحديد الكل")
        return
    if action == "save":
        pending = cleaning_pending.get(chat_id)
        if not pending:
            safe_answer_callback(call, "انتهت جلسة إعداد التنظيف، اكتب تفعيل التنظيف من جديد.")
            return
        seconds = int(pending.get("seconds", 0) or 0)
        if seconds <= 0:
            cleaning_pending.pop(chat_id, None)
            safe_answer_callback(call, "اختر مدة صحيحة أولاً.")
            return
        cleaning_mode[chat_id] = seconds
        cleaning_settings[chat_id] = {key: bool(pending.get(key, False)) for key in CLEAN_TYPES}
        cleaning_pending.pop(chat_id, None)
        save_json_setting(chat_id, "cleaning", {
            "mode": seconds,
            "settings": cleaning_settings[chat_id],
        })
        edit_commands_message(
            bot, call,
            "• تم تفعيل التنظيف بنجاح\n"
            f"• المدة ↤︎ {seconds} ثانية\n"
            "• تم حفظ أنواع التنظيف المحددة",
            owner_back_markup()
        )
        safe_answer_callback(call, "تم حفظ التنظيف")
        return
    if action == "cancel":
        cleaning_pending.pop(chat_id, None)
        try:
            edit_commands_message(bot, call, "تم إلغاء إعداد التنظيف.", owner_back_markup())
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if action == "save":
        seconds = settings["seconds"]
        selected = {key: bool(settings.get(key, False)) for key in CLEAN_TYPES}
        if not any(selected.values()):
            bot.answer_callback_query(call.id, "حدد نوع واحد على الأقل.", show_alert=True)
            return
        cleaning_mode[chat_id] = seconds
        cleaning_settings[chat_id] = selected
        save_json_setting(chat_id, "cleaning", {"mode": seconds, "settings": selected})
        cleaning_pending.pop(chat_id, None)
        edit_commands_message(bot, call, f"تم تفعيل الحذف بعد {seconds} ثانية", owner_back_markup())
        bot.answer_callback_query(call.id, "تم")
        return

def contains_link(text):
    if not text:
        return False
    text = text.lower()
    if re.search(r"(https?://|www\.)", text):
        return True
    if re.search(r"(t\.me/|telegram\.me/)", text):
        return True
    if re.search(r"\b[a-z0-9-]+\.(com|net|org|info|biz|io|me|co|xyz|site|online|shop|store|pro)\b", text):
        return True
    return False

def user_can_send_links(user_id, chat_id):
    if user_id in OWNER_IDS:
        return True
    if get_rank(user_id, chat_id) == "Owner":
        return True
    return False

def protection_action_text(action, mention, reason):
    return (
        f"• {action} 「 {mention} 」\n"
        f"• السبب: {reason}"
    )


