def protection_warning_enabled(chat_id):
    return not bool(load_json_setting(chat_id, "hide_protection_warnings", False))

def advanced_warning_enabled(chat_id):
    return not bool(load_json_setting(chat_id, "hide_advanced_warnings", False))

def rank_messages_enabled(chat_id):
    return not bool(load_json_setting(chat_id, "hide_rank_messages", False))

def developer_messages_enabled(chat_id):
    return not bool(load_json_setting(chat_id, "hide_developer_messages", False))


def top_commands_hidden(chat_id):
    """إذا فُعّل «اخفاء رسالة التوب» تختفي كل أوامر التوب والتفاعل المرتبطة به من القروب."""
    return bool(load_json_setting(chat_id, "hide_top_messages", False))

def add_security_log(chat_id, event_type, details, actor=""):
    """يسجل الحدث الأمني فور وقوعه مع حماية من أخطاء قاعدة البيانات."""
    try:
        if chat_id is None:
            return False
        cursor.execute(
            "INSERT INTO security_logs(chat_id,event_type,details,actor,created_at) VALUES(?,?,?,?,?)",
            (int(chat_id), str(event_type or "حدث"), str(details or ""), str(actor or ""), int(time.time()))
        )
        conn.commit()
        return True
    except Exception as e:
        print(f"[SECURITY LOG ERROR] {e}", flush=True)
        return False

def _security_log_text(row):
    _id, event_type, details, actor, created_at = row
    try: stamp=datetime.fromtimestamp(int(created_at)).strftime("%Y-%m-%d %H:%M")
    except Exception: stamp="غير معروف"
    def clean_mention(value):
        value=str(value or "")
        value=value.replace("&lt;a href=", "<a href=").replace("&gt;", ">").replace("&lt;/a&gt;", "</a>")
        return value
    event_type=html.escape(str(event_type or ""))
    details=clean_mention(details)
    actor=clean_mention(actor)
    actor_line=f"\n• بواسطة: {actor}" if actor else ""
    return f"• {event_type}\n• {details}{actor_line}\n• الوقت: {stamp}"

def _security_log_markup(chat_id, offset=0):
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
    markup.row(telebot.types.InlineKeyboardButton("التالي", callback_data=f"securitylog:next:{int(chat_id)}:{int(offset)}"), telebot.types.InlineKeyboardButton("مسح السجل", callback_data=f"securitylog:clear:{int(chat_id)}", icon_custom_emoji_id="6007942490076745785"))
    markup.row(telebot.types.InlineKeyboardButton("إغلاق", callback_data="securitylog:close", style="danger", icon_custom_emoji_id=COMMANDS_CLOSE_ICON_ID))
    return markup

def _send_security_log(chat_id, offset=0, message_id=None):
    try:
        rows = cursor.execute("SELECT id,event_type,details,actor,created_at FROM security_logs WHERE chat_id=? ORDER BY id DESC LIMIT 3 OFFSET ?", (int(chat_id), int(offset))).fetchall()
    except Exception as e:
        print(f"[SECURITY LOG READ ERROR] {e}")
        rows = []
    if rows:
        body = "\n\n━━━━━━━━━━━\n\n".join(_security_log_text(row) for row in rows)
        caption = f"• السجل الأمني\n━━━━━━━━━━━\n\n{body}"
    else:
        caption = "• السجل الأمني\n━━━━━━━━━━━\n• لا توجد أحداث أمنية مسجلة في هذا القروب"
    markup = _security_log_markup(chat_id, offset)
    try:
        if message_id:
            bot.edit_message_caption(caption=caption, chat_id=chat_id, message_id=message_id, parse_mode="HTML", reply_markup=markup)
        else:
            bot.send_photo(chat_id, io.BytesIO(RAD_PAUSED_IMAGE), caption=caption, parse_mode="HTML", reply_markup=markup)
    except Exception:
        try: bot.send_message(chat_id, caption, parse_mode="HTML", reply_markup=markup)
        except Exception: pass

@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and m.text.strip() == "سجل", content_types=["text"])
def security_log_command(message):
    if getattr(message.chat, "type", None) not in ["group", "supergroup"]:
        return
    if not (message.from_user and (message.from_user.id in OWNER_IDS or get_rank(message.from_user.id, message.chat.id) in ["Developer", "Owner", "Owner²", "Helper"])):
        return
    add_security_log(message.chat.id, "عرض السجل", f"تم فتح السجل بواسطة {get_mention(message.from_user)}", get_mention(message.from_user))
    _send_security_log(message.chat.id)

@bot.callback_query_handler(func=lambda c: str(getattr(c, "data", "")).startswith("securitylog:"))
def security_log_callback(call):
    if RAD_STOPPED:
        return
    try:
        uid = int(call.from_user.id)
        if uid not in OWNER_IDS and get_rank(uid, call.message.chat.id) not in ["Developer", "Owner", "Owner²", "Helper"]:
            bot.answer_callback_query(call.id, "غير مصرح")
            return
    except Exception:
        return
    data = str(call.data).split(":")
    try:
        action = data[1]
        chat_id = int(data[2]) if len(data) > 2 and data[2] else int(call.message.chat.id)
    except Exception:
        return
    if action == "close":
        try: bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception: pass
        return
    if action == "clear":
        try:
            cursor.execute("DELETE FROM security_logs WHERE chat_id=?", (chat_id,)); conn.commit()
            bot.answer_callback_query(call.id, "تم مسح السجل")
            _send_security_log(chat_id, 0, call.message.message_id)
        except Exception: pass
        return
    if action == "next":
        try: offset = int(data[3]) + 3
        except Exception: offset = 3
        _send_security_log(chat_id, offset, call.message.message_id)

WARNING_SPAM_COUNTS = defaultdict(dict)
WARNING_SPAM_LOCK = threading.RLock()
WARNING_SPAM_BURST_SECONDS = 10
WARNING_SPAM_ROUND_SECONDS = 30
WARNING_SPAM_REQUIRED_WARNINGS = 3
WARNING_SPAM_REQUIRED_ROUNDS = 3


def _warning_spam_markup(chat_id, user_id):
    kb = telebot.types.InlineKeyboardMarkup(row_width=1)
    kb.row(_styled_button("• الغاء الإنذار", f"warning_spam:clear:{int(chat_id)}:{int(user_id)}", "success"))
    kb.row(commands_close_button(f"warning_spam:close:{int(chat_id)}:{int(user_id)}"))
    return kb


def _warning_spam_restricted_markup(chat_id, user_id):
    kb = telebot.types.InlineKeyboardMarkup(row_width=2)
    kb.row(
        _styled_button("• فك التقييد", f"warning_spam:unrestrict:{int(chat_id)}:{int(user_id)}", "success"),
        _styled_button("اغلاق", f"warning_spam:close:{int(chat_id)}:{int(user_id)}", "danger")
    )
    return kb


def _restore_chat_permissions():
    return telebot.types.ChatPermissions(
        can_send_messages=True, can_send_audios=True, can_send_documents=True,
        can_send_photos=True, can_send_videos=True, can_send_video_notes=True,
        can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True,
        can_add_web_page_previews=True, can_invite_users=True
    )


def _warning_spam_record(chat_id, text):
    """كل 3 تحذيرات لنفس العضو خلال 10 ثوانٍ = إنذار واحد؛ 3 إنذارات خلال 30 ثانية = تقييد."""
    try:
        if not advanced_protection_enabled(chat_id, "warning_spam"):
            return
        source_text = str(text or "")
        match = re.search(r"tg://user\?id=(\d+)", source_text)
        if not match:
            return
        user_id = int(match.group(1))
        now = time.time()

        with WARNING_SPAM_LOCK:
            chat_data = WARNING_SPAM_COUNTS.setdefault(int(chat_id), {})
            data = chat_data.get(user_id)
            if not isinstance(data, dict):
                data = {"burst_count": 0, "burst_started": now, "last_warning": 0.0,
                        "rounds": 0, "round_started": now}
            # لا يُحتسب التحذير إذا كان الفاصل عن التحذير السابق أكثر من 10 ثوانٍ.
            if data.get("last_warning", 0.0) and now - float(data["last_warning"]) > WARNING_SPAM_BURST_SECONDS:
                data["burst_count"] = 0
                data["burst_started"] = now
            # الإنذارات المتراكمة تنتهي إذا تجاوزت أول جولة 30 ثانية.
            if data.get("rounds", 0) and now - float(data.get("round_started", now)) > WARNING_SPAM_ROUND_SECONDS:
                data["rounds"] = 0
                data["round_started"] = now
            if not data.get("burst_count"):
                data["burst_started"] = now
            data["burst_count"] = int(data.get("burst_count", 0)) + 1
            data["last_warning"] = now

            if data["burst_count"] < WARNING_SPAM_REQUIRED_WARNINGS:
                chat_data[user_id] = data
                return

            # اكتملت 3 تحذيرات متتابعة خلال 10 ثوانٍ: سجّل جولة إنذار واحدة.
            data["burst_count"] = 0
            if not data.get("rounds"):
                data["round_started"] = now
            data["rounds"] = int(data.get("rounds", 0)) + 1
            count = min(data["rounds"], WARNING_SPAM_REQUIRED_ROUNDS)
            chat_data[user_id] = data

        try:
            member = bot.get_chat_member(chat_id, user_id)
            mention = get_mention(member.user)
        except Exception:
            mention = f'<a href="tg://user?id={user_id}">المستخدم</a>'

        if count >= WARNING_SPAM_REQUIRED_ROUNDS:
            try:
                # تقييد كامل من صلاحيات القروب، وليس مجرد تسجيل حالة داخل السورس.
                bot.restrict_chat_member(
                    int(chat_id), int(user_id),
                    permissions=telebot.types.ChatPermissions(
                        can_send_messages=False,
                        can_send_audios=False,
                        can_send_documents=False,
                        can_send_photos=False,
                        can_send_videos=False,
                        can_send_video_notes=False,
                        can_send_voice_notes=False,
                        can_send_polls=False,
                        can_send_other_messages=False,
                        can_add_web_page_previews=False
                    )
                )
                bot.send_message(chat_id, f"• تم تقييد ↤︎ {mention}\n• بسبب إنذاراته", parse_mode="HTML", reply_markup=_warning_spam_restricted_markup(chat_id, user_id))
            except Exception as e:
                print(f"[WARNING SPAM RESTRICT ERROR] {e}", flush=True)
            with WARNING_SPAM_LOCK:
                WARNING_SPAM_COUNTS.setdefault(int(chat_id), {}).pop(user_id, None)
            return

        bot.send_message(
            chat_id,
            f"• تحذير تكرار الإنذارات\n• الورع اللي قاعد يخالف: {mention}\n• تم إعطاؤه انذار ({count}/3)",
            parse_mode="HTML",
            reply_markup=_warning_spam_markup(chat_id, user_id)
        )
    except Exception as e:
        print(f"[WARNING SPAM ERROR] {e}", flush=True)


@bot.callback_query_handler(func=lambda c: str(getattr(c, "data", "")).startswith("warning_spam:"))
def warning_spam_callback(call):
    try:
        parts = call.data.split(":")
        action, chat_id, user_id = parts[1], int(parts[2]), int(parts[3])
        uid = int(call.from_user.id)
        if uid not in OWNER_IDS and get_rank_level(uid, chat_id) < RANK_LEVELS["Owner"]:
            bot.answer_callback_query(call.id, "• هذا الامر يخص ↤︎ owner وما فوق", show_alert=True)
            return
        if action == "clear":
            with WARNING_SPAM_LOCK:
                WARNING_SPAM_COUNTS.setdefault(chat_id, {}).pop(user_id, None)
            # عدّل نفس الرسالة كما طلب المستخدم، مع إزالة الأزرار بعد نجاح المسح.
            bot.edit_message_text(
                "• تم مسح الإنذارات وصارت 0",
                chat_id,
                call.message.message_id,
                reply_markup=None
            )
            bot.answer_callback_query(call.id, "تم مسح الإنذارات")
            return
        if action == "unrestrict":
            bot.restrict_chat_member(chat_id, user_id, permissions=_restore_chat_permissions())
            for status in ("restricted", "media_restricted", "restricted_media", "media"):
                moderation_remove(chat_id, user_id, status)
            with WARNING_SPAM_LOCK:
                WARNING_SPAM_COUNTS.setdefault(chat_id, {}).pop(user_id, None)
            try:
                target_member = bot.get_chat_member(chat_id, user_id)
                target_mention = get_mention(target_member.user)
            except Exception:
                target_mention = f'<a href="tg://user?id={user_id}">المستخدم</a>'
            bot.edit_message_text(
                f"• تم فك التقييد عن {target_mention}",
                chat_id, call.message.message_id, parse_mode="HTML", reply_markup=None
            )
            bot.answer_callback_query(call.id, "تم فك التقييد")
            return
        if action == "close":
            bot.delete_message(chat_id, call.message.message_id)
            bot.answer_callback_query(call.id)
            return
    except Exception as e:
        print(f"[WARNING SPAM CALLBACK ERROR] {e}", flush=True)
        try:
            bot.answer_callback_query(call.id, "تعذر تنفيذ الأمر", show_alert=True)
        except Exception:
            pass

def send_basic_warning(chat_id, text):
    # احتساب التحذير يتم حتى لو كانت إظهار رسائل التحذير العادية مخفية.
    try:
        _warning_spam_record(chat_id, text)
    except Exception as e:
        print(f"[WARNING SPAM RECORD ERROR] {e}", flush=True)
    if not protection_warning_enabled(chat_id):
        return
    try:
        bot.send_message(chat_id, text, parse_mode="HTML")
        add_security_log(chat_id, "حماية", text)
    except Exception: pass

def send_advanced_warning(chat_id, text):
    # احتساب التحذير يتم حتى لو كانت إظهار رسائل التحذير العادية مخفية.
    try:
        _warning_spam_record(chat_id, text)
    except Exception as e:
        print(f"[WARNING SPAM RECORD ERROR] {e}", flush=True)
    if not advanced_warning_enabled(chat_id):
        return
    try:
        bot.send_message(chat_id, text, parse_mode="HTML")
        add_security_log(chat_id, "حماية متقدمة", text)
    except Exception: pass

def is_basic_protection_exempt(user_id, chat_id):
    """استثناء Helper من الحماية الأساسية فقط؛ لا يشمل الحماية المتقدمة أو حماية 3."""
    try:
        if str(get_rank(int(user_id), int(chat_id))).strip().casefold() == "helper":
            return True
    except Exception:
        pass
    return is_full_protection_exempt(user_id, chat_id)

def is_full_protection_exempt(user_id, chat_id):
    """استثناء شامل ونهائي من جميع حمايات القروب الأساسية والمتقدمة.

    Dev: أي معرّف موجود في OWNER_IDS فقط.
    Owner: العضو الذي رتبته Owner في هذا القروب.
    تُستخدم هذه الدالة قبل أي إجراء حذف أو تحذير أو عقوبة للحماية.
    """
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return False
    try:
        if uid in {int(x) for x in OWNER_IDS}:
            return True
    except Exception:
        pass
    try:
        return str(get_rank(uid, int(chat_id))).strip().casefold() in {"dev", "owner"}
    except Exception:
        return False

def load_penalties(chat_id):
    if chat_id not in protection_penalties:
        saved = load_json_setting(chat_id, "protection_penalties", {})
        protection_penalties[chat_id] = saved if isinstance(saved, dict) else {}
    return protection_penalties[chat_id]

def protection_penalty(chat_id, user, key):
    if not user or is_full_protection_exempt(user.id, chat_id):
        return False
    penalty = load_penalties(chat_id).get(key)
    if penalty not in ("ban", "restrict", "mute"):
        return False
    mention = get_mention(user)
    try:
        if penalty == "ban":
            bot.ban_chat_member(chat_id, user.id)
            moderation_add(chat_id, user.id, "banned")
            action = "تم حظر"
        elif penalty == "restrict":
            perms = telebot.types.ChatPermissions(can_send_messages=False)
            bot.restrict_chat_member(chat_id, user.id, permissions=perms)
            moderation_add(chat_id, user.id, "restricted")
            action = "تم تقييد"
        else:
            muted_users.setdefault(chat_id, {})[user.id] = 0
            cursor.execute("INSERT OR REPLACE INTO temp_mutes(chat_id,user_id,until_time) VALUES(?,?,?)",
                           (chat_id, user.id, 0))
            conn.commit()
            action = "تم كتم"
        _penalty_labels = dict(BASIC_PROTECTION_LABELS)
        _penalty_labels.update(dict(PENALTY_ITEMS) if "PENALTY_ITEMS" in globals() else {})
        bot.send_message(chat_id, f"• {action} ↤︎ {mention}\n• بسبب ↤︎ {html.escape(_penalty_labels.get(key, key))}", parse_mode="HTML")
        return True
    except Exception as e:
        print(f"[PENALTY ERROR] {key}: {e}", flush=True)
        return False


# تغليف مركزي: أي عقوبة تمر عبر protection_penalty تُسجل في السجل الأمني.
_original_protection_penalty = protection_penalty
def protection_penalty(chat_id, user, key):
    try:
        result = _original_protection_penalty(chat_id, user, key)
        if user and chat_id is not None:
            action = "تم تطبيق العقوبة" if result else "لم يتم تطبيق العقوبة"
            add_security_log(chat_id, "عقوبة حماية", f"{key} — {action}", get_mention(user))
        return result
    except Exception as e:
        print(f"[PROTECTION PENALTY LOG ERROR] {e}", flush=True)
        return None

def load_general_exceptions(chat_id):
    if chat_id in general_exceptions:
        return general_exceptions[chat_id]
    saved = load_json_setting(chat_id, "general_exceptions", [])
    try: general_exceptions[chat_id] = set(int(x) for x in saved)
    except Exception: general_exceptions[chat_id] = set()
    return general_exceptions[chat_id]

def save_general_exceptions(chat_id):
    save_json_setting(chat_id, "general_exceptions", sorted(general_exceptions.get(chat_id, set())))

def is_general_exception_id(chat_id, message_id):
    """فحص استثناء الرسالة نفسها فقط. عند الشك نعتبرها مستثناة حمايةً للرسالة."""
    try:
        chat_id = int(chat_id)
        message_id = int(message_id)
        key = (chat_id, message_id)
        # المصدر الأسرع: بمجرد تنفيذ «استثناء» تصبح الرسالة محمية فوراً.
        if key in EXEMPTED_MESSAGE_KEYS or key in EXCEPTION_HARD_BLOCK:
            return True
        if key in general_exception_cancelled:
            return True
        row = cursor.execute(
            "SELECT 1 FROM general_exception_messages WHERE chat_id=? AND message_id=? LIMIT 1",
            (chat_id, message_id)
        ).fetchone()
        if row:
            return True
        if message_id in load_general_exceptions(chat_id):
            return True
        row = cursor.execute(
            "SELECT setting_value FROM chat_settings WHERE chat_id=? AND setting_key=?",
            (chat_id, "general_exceptions")
        ).fetchone()
        if row:
            saved = json.loads(row[0])
            return message_id in {int(x) for x in (saved or [])}
    except Exception as e:
        print(f"[EXCEPTION CHECK ERROR] {chat_id}/{message_id}: {e}")
        return True
    return False

def is_general_exception(message):
    """Return True when this exact message was explicitly exempted from cleaning."""
    return is_general_exception_id(message.chat.id, message.message_id)

def media_exception_name(message):
    return {"photo":"صورة","document":"ملف","sticker":"الملصق","video":"فيديو",
            "animation":"صورة متحركة","audio":"صوت","voice":"تسجيل صوتي",
            "video_note":"رسالة فيديو"}.get(getattr(message,"content_type",None),"رسالة")

def detect_custom_emoji(message):
    # الإيموجي المميز المرسل كنص يظهر كـ custom_emoji entity.
    entities = list(getattr(message, "entities", None) or []) + list(getattr(message, "caption_entities", None) or [])
    for entity in entities:
        if getattr(entity, "type", None) == "custom_emoji":
            return True
    # بعض إصدارات المكتبة قد توفر entities بشكل مختلف داخل json/message dict.
    try:
        raw = getattr(message, "json", None)
        if callable(raw):
            data = raw()
            return any(e.get("type") == "custom_emoji" for e in (data.get("entities") or []) + (data.get("caption_entities") or []))
    except Exception:
        pass
    return False

MALHAJA_SYMBOLS = set("""$_&-+) (٫"':؛~`|•√π÷×§∆£€¥﷼^°=} {%©®™✓][<>""".replace(" ", ""))

def contains_malhaja(text):
    return bool(text) and any(ch in MALHAJA_SYMBOLS for ch in text)

def detect_command_slash(message):
    text = getattr(message, "text", None) or getattr(message, "caption", None) or ""
    return text.lstrip().startswith("/")

def check_new_basic_protections(message):
    # الاستثناء يتغلب على كل حماية، بما فيها حماية الإيموجيات المميزة.
    if is_general_exception(message):
        return False
    user = getattr(message, "from_user", None)
    if not user or not is_group(message) or is_basic_protection_exempt(user.id, message.chat.id):
        return False
    chat_id = message.chat.id
    text = getattr(message, "text", None) or getattr(message, "caption", None) or ""
    # قفل القيفات: حذف ملفات GIF/Animation فقط عند تفعيل الحماية.
    if basic_protection_enabled(chat_id, "gifs"):
        is_gif = getattr(message, "content_type", None) == "animation"
        document = getattr(message, "document", None)
        mime_type = (getattr(document, "mime_type", "") or "").lower() if document else ""
        file_name = (getattr(document, "file_name", "") or "").lower() if document else ""
        if mime_type == "image/gif" or file_name.endswith(".gif"):
            is_gif = True
        if is_gif:
            try:
                safe_delete_message(chat_id, message.message_id)
            except Exception:
                pass
            send_basic_warning(chat_id, f"ممنوع أرسال صور المتحركة - يا {get_mention(user)}")
            protection_penalty(chat_id, user, "gifs")
            return True

    # رتبة Helper مستثناة من حماية منع إرسال أوامر البوت فقط،
    # ولا يعني ذلك استثناءها من بقية الحمايات.
    helper_command_exempt = False
    try:
        helper_command_exempt = get_rank(user.id, chat_id) == "Helper"
    except Exception:
        helper_command_exempt = False
    if basic_protection_enabled(chat_id, "commands") and not helper_command_exempt and detect_command_slash(message):
        try: safe_delete_message(chat_id, message.message_id)
        except Exception: pass
        send_basic_warning(chat_id, f"ممنوع ارسال الاوامر - يا {get_mention(user)}")
        protection_penalty(chat_id, user, "commands")
        return True
    if basic_protection_enabled(chat_id, "premium_emoji") and detect_custom_emoji(message):
        try: safe_delete_message(chat_id, message.message_id)
        except Exception: pass
        send_basic_warning(chat_id, f"ممنوع ايموجيات المميزة - يا {get_mention(user)}")
        protection_penalty(chat_id, user, "premium_emoji")
        return True
    if basic_protection_enabled(chat_id, "symbols") and contains_malhaja(text):
        try: safe_delete_message(chat_id, message.message_id)
        except Exception: pass
        send_basic_warning(chat_id, f"ممنوع الملحجة - يا {get_mention(user)}")
        protection_penalty(chat_id, user, "symbols")
        return True
    return False

LINKED_CHANNEL_WARNED = set()

def _linked_channel_revoke_pin(chat_id):
    """يسحب صلاحية تثبيت الرسائل من المشرفين الذين رفعهم البوت فقط."""
    affected = []
    try:
        cursor.execute("SELECT user_id FROM bot_promoted_admins WHERE chat_id=?", (int(chat_id),))
        rows = cursor.fetchall()
    except Exception as e:
        print(f"[LINKED CHANNEL PROMOTED ADMINS READ ERROR] {e}", flush=True)
        rows = []

    for row in rows:
        try:
            user_id = int(row[0])
            member = get_telegram_admin(chat_id, user_id)
            if not member or getattr(member, "status", None) == "creator":
                continue
            rights = telegram_admin_rights(member)
            if not rights.get("pin", False):
                continue
            # نحافظ على بقية صلاحيات المشرف، ونوقف التثبيت فقط.
            bot.promote_chat_member(
                chat_id, user_id,
                can_change_info=rights["info"],
                can_pin_messages=False,
                can_restrict_members=rights["ban"],
                can_invite_users=rights["invite"],
                can_delete_messages=rights["del"],
                can_manage_video_chats=rights["call"],
                can_promote_members=rights["add"],
                can_manage_topics=rights["topics"]
            )
            user = getattr(member, "user", None)
            if user:
                affected.append(get_mention(user))
        except Exception as e:
            print(f"[LINKED CHANNEL REVOKE PIN ERROR] chat={chat_id}: {e}", flush=True)
    return affected

def _check_linked_channel_warning(chat):
    """يحذر مرة واحدة إذا اكتشف Bot API قناة مرتبطة بالمجموعة."""
    try:
        if not chat or getattr(chat, "type", None) not in ("group", "supergroup"):
            return
        chat_id = int(chat.id)
        if not advanced_protection_enabled(chat_id, "channels") or chat_id in LINKED_CHANNEL_WARNED:
            return
        fresh = bot.get_chat(chat_id)
        linked_id = getattr(fresh, "linked_chat_id", None)
        if not linked_id:
            raw = fresh.to_dict() if hasattr(fresh, "to_dict") else {}
            linked_id = raw.get("linked_chat_id") if isinstance(raw, dict) else None
        if not linked_id:
            return

        # سجل التحذير قبل التنفيذ حتى لا يرسل رسائل متكررة عند حدوث خطأ جزئي.
        LINKED_CHANNEL_WARNED.add(chat_id)
        affected = _linked_channel_revoke_pin(chat_id)
        # خانة الإداريين المعنيين تعرض منشن جميع مشرفي القروب، وليس فقط من سُحبت منهم الصلاحية.
        try:
            group_admins = bot.get_chat_administrators(chat_id)
            admin_mentions = []
            seen_admin_ids = set()
            for admin_entry in group_admins:
                admin_user = getattr(admin_entry, "user", None)
                if not admin_user or getattr(admin_user, "is_bot", False):
                    continue
                admin_id = int(admin_user.id)
                if admin_id in seen_admin_ids:
                    continue
                seen_admin_ids.add(admin_id)
                admin_mentions.append(get_mention(admin_user))
            admins = "، ".join(admin_mentions) if admin_mentions else "لم يتم العثور على مشرفين"
        except Exception as e:
            print(f"[LINKED CHANNEL ADMIN MENTIONS ERROR] {e}", flush=True)
            admins = "تعذر جلب قائمة مشرفي القروب"
        warning = (
            '• تحذير : <tg-emoji emoji-id="4915853119839011973">⚠️</tg-emoji>\n'
            '• من كاشف سورس راد\n'
            '• تم الكشف عن ربط قناة في القروب\n'
            '• يرجى إزالتها لان البوت ما يقدر\n'
            '• ويرجى شيل من كل اعضاء الغير الموثوق فيهم صلاحية تثبيت الرسائل\n'
            '• وسيتم سحب من جميع الاعضاء الذين تم رفعهم من خلال البوت صلاحية تثبيت الرسائل <tg-emoji emoji-id="4918327330239152795">📌</tg-emoji>\n\n'
            'الاداريين المعنيين: ' + admins
        )
        try:
            bot.send_message(chat_id, warning, parse_mode="HTML")
        except Exception as e:
            print(f"[LINKED CHANNEL WARN] group notice failed: {e}", flush=True)

        # إشعار خاص للمسؤولين، مع زر القروب إذا توفر رابط.
        try:
            link = getattr(fresh, "invite_link", None)
            if not link:
                try: link = bot.export_chat_invite_link(chat_id)
                except Exception: link = None
            if not link and getattr(fresh, "username", None):
                link = "https://t.me/" + str(fresh.username).lstrip("@")
            private_kb = telebot.types.InlineKeyboardMarkup()
            if link:
                private_kb.add(telebot.types.InlineKeyboardButton(str(getattr(fresh, "title", "القروب"))[:60], url=link, style="primary"))
            private_text = "• تحذير يا مشرف\n• تم الكشف عن ربط قناة في القروب\n• تم سحب صلاحية التثبيت من المشرفين الذين رفعهم البوت، إن أمكن."
            cursor.execute('SELECT user_id FROM users WHERE chat_id=? AND rank IN ("Owner","Owner²","Helper")', (chat_id,))
            ids = {int(row[0]) for row in cursor.fetchall()} | {int(x) for x in OWNER_IDS}
            for uid in ids:
                try: bot.send_message(uid, private_text, reply_markup=private_kb if link else None)
                except Exception: pass
        except Exception as e:
            print(f"[LINKED CHANNEL PRIVATE NOTICE ERROR] {e}", flush=True)
    except Exception as e:
        print(f"[LINKED CHANNEL WARN ERROR] {e}", flush=True)

def check_channel_message(message):
    """يحذف رسائل القنوات ورسائل القناة المرتبطة التي تُحوّل تلقائياً للقروب."""
    if getattr(message, "_channel_protection_handled", False):
        return True
    chat = getattr(message, "chat", None)
    if not chat or getattr(chat, "type", None) not in ("group", "supergroup"):
        return False
    sender = getattr(message, "from_user", None)
    if sender and is_full_protection_exempt(sender.id, chat.id):
        return False
    if not advanced_protection_enabled(chat.id, "channels"):
        return False
    sender_chat = getattr(message, "sender_chat", None)
    automatic_forward = bool(getattr(message, "is_automatic_forward", False))
    forward_origin = getattr(message, "forward_origin", None)
    origin_type = getattr(forward_origin, "type", None) if forward_origin else None
    origin_chat = getattr(forward_origin, "chat", None) if forward_origin else None
    legacy_forward_chat = getattr(message, "forward_from_chat", None)

    # اقرأ الحقول الخام أيضاً؛ بعض إصدارات المكتبة لا تعرض كل حقول Bot API كخصائص.
    raw = {}
    try:
        raw = message.to_dict() if hasattr(message, "to_dict") else {}
        if not isinstance(raw, dict):
            raw = {}
    except Exception:
        raw = {}
    if not sender_chat and isinstance(raw.get("sender_chat"), dict):
        try:
            sender_chat = telebot.types.Chat.de_json(raw["sender_chat"])
        except Exception:
            sender_chat = None
    automatic_forward = automatic_forward or bool(raw.get("is_automatic_forward", False))
    if not legacy_forward_chat and isinstance(raw.get("forward_from_chat"), dict):
        try:
            legacy_forward_chat = telebot.types.Chat.de_json(raw["forward_from_chat"])
        except Exception:
            legacy_forward_chat = None
    if not origin_chat and isinstance(raw.get("forward_origin"), dict):
        origin_raw = raw["forward_origin"].get("chat")
        if isinstance(origin_raw, dict):
            try:
                origin_chat = telebot.types.Chat.de_json(origin_raw)
            except Exception:
                origin_chat = None
        origin_type = origin_type or raw["forward_origin"].get("type")

    sender_type = getattr(sender_chat, "type", None) if sender_chat else None
    legacy_forward_type = getattr(legacy_forward_chat, "type", None) if legacy_forward_chat else None
    is_channel_sender = sender_type == "channel"
    is_channel_forward = automatic_forward or origin_type == "channel" or legacy_forward_type == "channel"
    # حذف رسائل القناة/منشوراتها فقط؛ لا توجد أي محاولة لفك ربط القناة بالمجموعة.
    if not (is_channel_sender or is_channel_forward):
        return False

    try:
        setattr(message, "_channel_protection_handled", True)
    except Exception:
        pass

    channel = sender_chat or origin_chat or legacy_forward_chat
    username = getattr(channel, "username", None) if channel else None
    title = getattr(channel, "title", None) if channel else None
    if username:
        channel_mention = "@" + html.escape(username, quote=True)
    else:
        channel_mention = html.escape(title or "القناة", quote=True)

    # الحذف أولاً؛ ثم أرسل التنبيه المطلوب حتى لا تمر رسالة القناة لبقية المعالجات.
    deleted = False
    delete_key = (int(chat.id), int(message.message_id))
    try:
        CHANNEL_PROTECTION_DELETE_KEYS.add(delete_key)
        result = safe_delete_message(chat.id, message.message_id)
        deleted = bool(result)
    except Exception as e:
        print(f"[CHANNEL PROTECTION DELETE ERROR] chat={chat.id} message={getattr(message, 'message_id', None)}: {e}", flush=True)
    finally:
        CHANNEL_PROTECTION_DELETE_KEYS.discard(delete_key)
    warning = f"ممنوع القنوات - يا {channel_mention}"
    try:
        bot.send_message(chat.id, warning, parse_mode="HTML")
        add_security_log(chat.id, "الحماية من القنوات", warning)
    except Exception as e:
        print(f"[CHANNEL PROTECTION WARNING ERROR] chat={chat.id}: {e}", flush=True)

    # بعد إنذار رسالة القناة مباشرةً، افحص وجود قناة مربوطة بالمجموعة
    # وأرسل تحذير الربط بعدها (مرة واحدة لكل مجموعة).
    try:
        _check_linked_channel_warning(chat)
    except Exception as e:
        print(f"[LINKED CHANNEL POST-WARNING ERROR] chat={chat.id}: {e}", flush=True)

    if not deleted:
        print(f"[CHANNEL PROTECTION] لم يتم حذف رسالة القناة؛ تحقق من صلاحية Delete Messages للبوت في القروب {chat.id}", flush=True)
    return True

def check_link_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not basic_protection_enabled(message.chat.id, "links"):
        return False
    text = message.text or message.caption or ""
    if not text:
        return False
    if not contains_link(text):
        return False
    chat_id = message.chat.id
    # حماية الروابط مستقلة عن التنظيف المؤقت: إذا كانت مفعلة يتم الحذف فوراً.
    if user_can_send_links(message.from_user.id, chat_id):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(message.from_user)
    send_basic_warning(message.chat.id, f"ممنوع ارسال الروابط - يا {mention}")
    return True

# =========================================================
# حماية التنسيق
# =========================================================

FORMATTING_ENTITY_TYPES = {
    "bold",
    "italic",
    "underline",
    "strikethrough",
    "spoiler",
    "code",
    "pre",
    "text_link",
    "text_mention",
    "custom_emoji",
    # Telegram quote blocks are formatting too; block them under formatting protection.
    "blockquote",
    "expandable_blockquote",
}

def has_text_formatting(message):
    """يتحقق من وجود تنسيق تيليجرام فعلي في النص أو الوصف."""
    entities = getattr(message, "entities", None) or []
    caption_entities = getattr(message, "caption_entities", None) or []
    # بعض إصدارات pyTelegramBotAPI لا تعرض entities كخصائص؛ اقرأ بيانات Bot API الخام أيضاً.
    raw = {}
    try:
        raw = message.to_dict() if hasattr(message, "to_dict") else {}
        if not isinstance(raw, dict):
            raw = {}
    except Exception:
        raw = {}
    entities = list(entities) + list(raw.get("entities") or [])
    caption_entities = list(caption_entities) + list(raw.get("caption_entities") or [])
    for entity in entities + caption_entities:
        entity_type = getattr(entity, "type", None)
        if entity_type is None and isinstance(entity, dict):
            entity_type = entity.get("type")
        if entity_type in FORMATTING_ENTITY_TYPES:
            return True
    # احتياطاً: بعض رسائل Telegram ترجع تنسيق النص في json فقط.
    return False

def check_formatting_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not basic_protection_enabled(message.chat.id, "formatting"):
        return False
    user = getattr(message, "from_user", None)
    if not user:
        return False

    if not has_text_formatting(message):
        return False

    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass

    mention = get_mention(user)
    try:
        send_basic_warning(message.chat.id, f"ممنوع تنسيق النص - يا {mention}")
    except Exception as e:
        print(f"[FORMATTING WARNING ERROR] {e}")
    return True


def check_quote_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    # حماية الاقتباس: تمنع رسائل الاقتباس عندما تكون الحماية مفعلة.
    if not basic_protection_enabled(message.chat.id, "quote"):
        return False
    user = getattr(message, "from_user", None)
    if not user:
        return False
    entities = list(getattr(message, "entities", None) or []) + list(getattr(message, "caption_entities", None) or [])
    try:
        raw = message.to_dict() if hasattr(message, "to_dict") else {}
        if isinstance(raw, dict):
            entities += list(raw.get("entities") or []) + list(raw.get("caption_entities") or [])
    except Exception:
        pass
    def _entity_type(entity):
        value = getattr(entity, "type", None)
        if value is None and isinstance(entity, dict):
            value = entity.get("type")
        return value
    if not any(_entity_type(entity) in {"blockquote", "expandable_blockquote"} for entity in entities):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(user)
    try:
        send_basic_warning(message.chat.id, f"ممنوع الاقتباس - يا {mention}")
    except Exception as e:
        print(f"[QUOTE WARNING ERROR] {e}")
    return True


def check_K_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    # حماية الجمثون: المطور وOwner مستثنون منها مثل جميع الحمايات الأخرى.
    user = getattr(message, "from_user", None)
