    if not user or not chat or is_full_protection_exempt(user.id, chat.id):
        return False
    # تمنع أي رسالة نصية تبدأ بالنقطة إذا كانت مفعلة.
    if not basic_protection_enabled(message.chat.id, "K"):
        return False
    text = message.text or ""
    if not text.startswith("."):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(message.from_user)
    try:
        send_basic_warning(message.chat.id, f"ممنوع استخدام الجمثون- يا {mention}")
    except Exception as e:
        print(f"[JMATHON WARNING ERROR] {e}")
    return True


