# حماية اللغات الأجنبية: العربية والإنجليزية مسموحتان، وأي أبجدية/لغة أخرى ممنوعة.
def is_arabic_or_english_letter(ch):
    # العربية: نطاقات الحروف العربية الشائعة، مع السماح بالتشكيل.
    code = ord(ch)
    if (0x0600 <= code <= 0x06FF) or (0x0750 <= code <= 0x077F) or (0x08A0 <= code <= 0x08FF):
        return True
    # الإنجليزية فقط، وليس باقي اللغات التي تستخدم الحروف اللاتينية.
    if ("A" <= ch <= "Z") or ("a" <= ch <= "z"):
        return True
    return False

def contains_foreign_language(text):
    """يرصد أي حرف من لغة/أبجدية غير العربية والإنجليزية."""
    if not text:
        return False
    for ch in text:
        if ch.isalpha() and not is_arabic_or_english_letter(ch):
            return True
    return False

def contains_english_text(text):
    if not text:
        return False
    # حماية الأنجليزي: وجود حرف إنجليزي واحد فقط يكفي للحذف، حتى لو كانت
    # الرسالة مختلطة بالعربية أو الأرقام أو الرموز، مثل: "هلا H" أو "مرحبا Hi".
    value = str(text)
    return any(("A" <= ch <= "Z") or ("a" <= ch <= "z") for ch in value)

def check_english_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not basic_protection_enabled(message.chat.id, "english"):
        return False
    user = getattr(message, "from_user", None)
    if not user or is_full_protection_exempt(user.id, message.chat.id):
        return False
    text = getattr(message, "text", None) or getattr(message, "caption", None) or ""
    if not contains_english_text(text):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(user)
    warning_text = f"ممنوع كتابة بالإنجليزية - يا {mention}"
    # حماية سبام الإنذارات يجب أن تحتسب تحذيرات الإنجليزية أيضًا؛
    # هذا التحذير يُرسل مباشرة ولا يمر عبر send_basic_warning.
    try:
        _warning_spam_record(message.chat.id, warning_text)
    except Exception as e:
        print(f"[WARNING SPAM ENGLISH RECORD ERROR] {e}", flush=True)
    try:
        bot.send_message(message.chat.id, warning_text, parse_mode="HTML")
    except Exception as e:
        print(f"[ENGLISH PROTECTION WARNING ERROR] {e}")
    try:
        protection_penalty(message.chat.id, user, "english")
    except Exception:
        pass
    return True

def check_foreign_language_and_delete(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    """حماية اللغات الأجنبية: تمنع كل اللغات غير العربية والإنجليزية."""
    if not basic_protection_enabled(message.chat.id, "foreign"):
        return False
    user = getattr(message, "from_user", None)
    if not user:
        return False
    text = getattr(message, "text", None) or getattr(message, "caption", None) or ""
    if not text or not contains_foreign_language(text):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(user)
    try:
        bot.send_message(
            message.chat.id,
            f"ممنوع اللغات الأجنبية - يا {mention}",
            parse_mode="HTML"
        )
    except Exception as e:
        print(f"[FOREIGN LANGUAGE WARNING ERROR] {e}")
    return True

def is_forwarded_message(message):
    if not message:
        return False
    if any(getattr(message, key, None) for key in (
        "forward_origin", "forward_from", "forward_from_chat", "forward_sender_name", "forward_date"
    )):
        return True
    try:
        raw = message.to_dict() if hasattr(message, "to_dict") else {}
        if isinstance(raw, dict):
            if raw.get("is_automatic_forward"):
                return True
            if any(raw.get(key) for key in (
                "forward_origin", "forward_from", "forward_from_chat", "forward_sender_name", "forward_date"
            )):
                return True
    except Exception:
        pass
    return bool(getattr(message, "is_automatic_forward", False))

def delete_forwarded_message(message):
    if not is_forwarded_message(message):
        return False
    chat_id = message.chat.id
    message_id = message.message_id
    last_error = None
    for attempt in range(2):
        try:
            safe_delete_message(chat_id, message_id)
            return True
        except Exception as e:
            last_error = e
            if attempt == 0:
                time.sleep(0.2)
    print(f"[FORWARD DELETE ERROR] chat={chat_id} message={message_id}: {last_error}")
    return False

def handle_forwarded_message(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not basic_protection_enabled(message.chat.id, "forwards"):
        return False
    if not is_forwarded_message(message):
        return False
    user = getattr(message, "from_user", None)
    # الحماية تطبق على الرسائل المحوّلة حتى لو كان مرسلها صاحب رتبة؛
    # وإلا تظهر كأن زر الحماية لا يعمل أثناء الاختبار.
    deleted = delete_forwarded_message(message)
    user = getattr(message, "from_user", None)
    mention = get_mention(user) if user else "المستخدم"
    try:
        if deleted:
            warning = f"ممنوع تحويل الرسائل - يا {mention}"
        else:
            warning = (
                f"ممنوع تحويل الرسائل - يا {mention}\n"
                "تعذر حذف التحويل. تأكد أن البوت مشرف ولديه صلاحية حذف الرسائل."
            )
        bot.send_message(message.chat.id, warning, parse_mode="HTML")
    except Exception as e:
        print(f"[FORWARD WARNING ERROR] chat={message.chat.id}: {e}")
    return True

def is_user_muted(chat_id, user_id):
    if chat_id not in muted_users:
        return False
    if user_id not in muted_users[chat_id]:
        return False
    mute_until = muted_users[chat_id][user_id]
    if mute_until == 0:
        return True
    if time.time() < mute_until:
        return True
    muted_users[chat_id].pop(user_id, None)
    if not muted_users[chat_id]:
        muted_users.pop(chat_id, None)
    return False

def delete_muted_message(message):
    user = getattr(message, "from_user", None)
    if not user:
        return False
    if not is_user_muted(message.chat.id, user.id):
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    return True

def contains_phone_number(text):
    if not text:
        return False
    pattern = r'(?<!\w)(?:\+?\d[\d\s\-\(\)]{5,}\d)(?!\w)'
    return bool(re.search(pattern, text))

def handle_phone_number(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not basic_protection_enabled(message.chat.id, "phone"):
        return False
    text = message.text or message.caption or ""
    if not text:
        return False
    if not contains_phone_number(text):
        return False
    user = message.from_user
    if not user:
        return False
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    mention = get_mention(user)
    bot.send_message(
        message.chat.id,
        f"ممنوع ارقام الهواتف - يا {mention}",
        parse_mode="HTML"
    )
    return True

def check_temp_mutes():
    cursor.execute(
        "SELECT chat_id, user_id, until_time FROM temp_mutes WHERE until_time > 0 AND until_time <= ?",
        (int(time.time()),)
    )
    expired = cursor.fetchall()
    for chat_id, user_id, until_time in expired:
        cursor.execute(
            "DELETE FROM temp_mutes WHERE chat_id=? AND user_id=?",
            (chat_id, user_id)
        )
        conn.commit()
        if chat_id in muted_users and user_id in muted_users[chat_id]:
            del muted_users[chat_id][user_id]
            if not muted_users[chat_id]:
                del muted_users[chat_id]
        try:
            bot.send_message(
                chat_id,
                f"تم فك الكتم التلقائي عن المستخدم <a href='tg://user?id={user_id}'>المستخدم</a>",
                parse_mode="HTML"
            )
        except Exception:
            pass
    threading.Timer(60, check_temp_mutes).start()

load_persistent_mutes()

threading.Timer(10, check_temp_mutes).start()

@bot.message_handler(content_types=["poll"])
def poll_protection_handler(message):
    # معالج مستقل للاستفتاءات؛ يجب أن يعمل قبل أي معالج وسائط أو معالج عام.
    if _enforce_persistent_bans_on_message(message):
        return
    track_message(message)
    if not getattr(message, "poll", None):
        return
    if check_poll_and_delete(message):
        return

EXCEPTION_ON={"تفعيل استثناء عام","تفعيل استنثاء عام","تفعيل امر استثناء عام","تفعيل امر استنثاء عام","تفعيل امر استثناء","تفعيل امر استنثاء"}
EXCEPTION_OFF={"تعطيل استثناء عام","تعطيل استنثاء عام","تعطيل امر استثناء عام","تعطيل امر استنثاء عام","تعطيل امر استثناء","تعطيل امر استنثاء"}
EXCEPTION_USE={"استثناء","استثناء عام","استنثاء","استنثاء عام","استثناء العام","الاستثناء العام","استنثاء العام","الاستنثاء العام"}

def general_exception_command(message):
    if not is_group(message): return
    if message.from_user.id not in OWNER_IDS and get_rank(message.from_user.id,message.chat.id) != "Owner":
        deny_rank(message,"Owner"); return
    command = message.text.strip()
    if command in EXCEPTION_ON:
        save_json_setting(message.chat.id, "general_exception_enabled", True)
        bot.reply_to(message, "• تم تفعيل أمر الاستثناء العام")
        return
    if command in EXCEPTION_OFF:
        save_json_setting(message.chat.id, "general_exception_enabled", False)
        bot.reply_to(message, "• تم تعطيل أمر الاستثناء العام")
        return
    # استخدام الاستثناء يتطلب الرد على الرسالة المراد استثناؤها.
    if not bool(load_json_setting(message.chat.id, "general_exception_enabled", False)):
        bot.reply_to(message, "• أمر استثناء العام معطل")
        return
    if not message.reply_to_message:
        bot.reply_to(message,"• لازم ترد على الصورة او الملف او الملصق أولًا."); return
    chat_id=message.chat.id
    target=message.reply_to_message
    name=media_exception_name(target)

    # سجّل الاستثناء وألغِ مهمة التنظيف تحت نفس القفل المستخدم قبل الحذف.
    # بهذا إذا وصل "استثناء" قبل لحظة الحذف، تكون له الأولوية دائماً.
    target_id = int(target.message_id)
    with general_exception_lock:
        key = (int(chat_id), target_id)
        # حماية فورية قبل أي كتابة لقاعدة البيانات.
        # من هذه اللحظة أي مسار حذف داخل البوت ممنوع من لمس الرسالة.
        EXEMPTED_MESSAGE_KEYS.add(key)
        EXCEPTION_HARD_BLOCK.add(key)
        # المصدر الأساسي: صف مستقل لا يعتمد على كاش JSON.
        cursor.execute(
            "INSERT OR IGNORE INTO general_exception_messages(chat_id,message_id,created_at) VALUES(?,?,?)",
            (int(chat_id), target_id, int(time.time()))
        )
        conn.commit()
        # توافق مع النظام السابق.
        load_general_exceptions(chat_id).add(target_id)
        save_general_exceptions(chat_id)
        # علامة إلغاء دائمة أثناء تشغيل البوت.
        general_exception_cancelled.add(key)
        # إيقاظ مهمة التنظيف فوراً إن كانت نائمة داخل Event.wait().
        event = cleaning_delete_events.get(key)
        if event:
            event.set()
        cleaning_delete_pending.discard(key)
        # احذف أي سجل تنظيف عالق بنفس المعرّف من كل البنى الموجودة.
        cleaning_delete_events.pop(key, None)

    # أخرج الرسالة المستثناة من عداد سبام الوسائط فوراً أيضاً،
    # حتى لا يقوم معالج السبام بحذفها لاحقاً ضمن الدفعة.
    spam_key = (int(chat_id), int(getattr(target, "from_user", None).id)) if getattr(target, "from_user", None) else None
    if spam_key and spam_key in photo_spam_tracker:
        photo_spam_tracker[spam_key] = [
            item for item in photo_spam_tracker[spam_key]
            if int(item.get("message_id", -1)) != target_id
        ]
        if not photo_spam_tracker[spam_key]:
            photo_spam_tracker.pop(spam_key, None)

    feminine_types = {"photo", "sticker", "animation"}
    article = "هذا" if getattr(target, "content_type", None) == "sticker" else ("هذي" if getattr(target, "content_type", None) in feminine_types else "هذا")
    bot.reply_to(message,f"• تم استثناء {article} {name} من عملية التنظيف")


@bot.message_handler(
    content_types=[
        "photo", "video", "document", "audio", "animation",
        "voice", "sticker", "video_note", "location", "venue", "poll", "dice"
    ]
)
def media_handler(message):
    if _enforce_persistent_bans_on_message(message):
        return
    # فحص عينة RAD PHOTO أولاً قبل أي مسار قد يستهلك الرسالة أو يعفي المرسل.
    if getattr(message, "content_type", "") in ("photo", "animation", "sticker", "video", "document"):
        try:
            if _ai_scan_media(message):
                return
        except Exception as e:
            print(f"[AI] first-priority media scan error: {type(e).__name__}: {e}", flush=True)
    # الكلمات الممنوعة لها أولوية على فحص الصورة: إذا كان الكابشن/اسم الملف
    # يحتوي كلمة ممنوعة نحذف الرسالة مباشرة ولا نعتمد على نتيجة نموذج الرؤية.
    if check_forbidden_words(message):
        return

    # حماية الأنجليزي تشمل كابشن الوسائط أيضاً: حرف إنجليزي واحد يكفي للحذف.
    if check_english_and_delete(message):
        return

    # الاستثناء العام هو الشيء الوحيد الذي يمنع التنظيف.
    if is_general_exception(message):
        return

    # بعد فحص الحماية 2، سجّل الرسالة وطبّق حماية السبام.
    track_message(message)
    if handle_media_spam_protection(message):
        return

    # بعد حماية السبام، يطبق التنظيف على الوسائط حسب إعداداته.
    if _run_cleaning(message):
        return

    # إذا لم يكن هناك تنظيف أو سبام على هذا النوع، تستمر الحمايات العادية.
    if getattr(message, "from_user", None) and is_user_muted(message.chat.id, message.from_user.id):
        delete_muted_message(message)
        return
    if check_channel_message(message) or check_new_basic_protections(message):
        return
    # افحص التنسيق والاقتباس في كابشن الوسائط أيضاً؛ media_handler قد يستهلكها
    # قبل وصولها إلى main_handler.
    if check_quote_and_delete(message):
        return
    if check_formatting_and_delete(message):
        return
    if is_full_protection_exempt(message.from_user.id, message.chat.id):
        return

    # حماية الملفات لها أولوية قبل التنظيف وباقي معالجات الوسائط.
    if getattr(message, "document", None) and check_file_and_delete(message):
        return

    # الاستفتاءات تدخل لهذا المعالج قبل المعالج الرئيسي في TeleBot،
    # لذلك يجب فحص حماية الاستفتاء هنا أولاً حتى لا يتم تجاوزها.
    if getattr(message, "poll", None) and check_poll_and_delete(message):
        return

    if delete_muted_message(message):
        return
    if handle_forwarded_message(message):
        return
    if handle_phone_number(message):
        return
    if check_link_and_delete(message):
        return
    chat_id = message.chat.id
    if chat_id not in cleaning_mode or cleaning_mode[chat_id] <= 0:
        return
    settings = cleaning_settings.get(chat_id, {})
    content_type = None
    if message.photo:
        content_type = "photo"
    elif message.video:
        content_type = "video"
    elif message.animation:
        content_type = "animation"
    elif message.voice:
        content_type = "voice"
    elif message.audio:
        content_type = "audio"
    elif message.document:
        content_type = "document"
    elif message.sticker:
        content_type = "sticker"
    elif message.video_note:
        content_type = "video_note"
    elif message.location:
        content_type = "location"
    elif message.venue:
        content_type = "venue"
    elif message.poll:
        content_type = "poll"
    elif message.dice:
        content_type = "dice"
    if content_type is None:
        return

    # إذا كانت الرسالة وسائط وبها رابط في النص/الوصف، فإن خيار "روابط"
    # يجعلها تدخل في التنظيف المؤقت أيضاً، دون الاعتماد على نظام الحماية.
    has_link_caption = contains_link(message.caption or "")
    if has_link_caption and settings.get("links", False):
        delay = cleaning_mode.get(chat_id, 0)
        if delay > 0:
            schedule_cleaning_delete(chat_id, message.message_id, delay)
        return

    if not settings.get(content_type, False):
        return
    delay = cleaning_mode.get(chat_id, 0)
    if delay <= 0:
        return
    schedule_cleaning_delete(chat_id, message.message_id, delay)

@bot.message_handler(func=lambda message: bool((getattr(message,"text","") or "").lstrip().startswith("/")), content_types=["text"])
def slash_command_protection_handler(message):
    track_message(message)
    if not is_group(message) or is_basic_protection_exempt(message.from_user.id,message.chat.id):
        return
    # السماح لرتبة Helper باستخدام أوامر البوت دون أن تمنعها حماية الأوامر.
    try:
        if get_rank(message.from_user.id, message.chat.id) == "Helper":
            return
    except Exception:
        pass
    if not basic_protection_enabled(message.chat.id,"commands"): return
    try: safe_delete_message(message.chat.id,message.message_id)
    except Exception: pass
    send_basic_warning(message.chat.id,f"ممنوع ارسال الاوامر - يا {get_mention(message.from_user)}")
    protection_penalty(message.chat.id,message.from_user,"commands")

def _run_cleaning(message):
    """التنظيف مستقل عن الحماية ويطبق على الجميع، بما في ذلك Owner/Developer.
    الاستثناء العام يفحص أولاً حتى لا تُحذف الرسالة المستثناة.
    """
    if not is_group(message) or is_general_exception(message):
        return False
    chat_id = message.chat.id
    # لا ننظف أوامر البوت إذا وصلت إلى المعالج العام لأي سبب.
    if getattr(message, "content_type", None) == "text":
        text_value = (getattr(message, "text", "") or "").strip()
        if text_value in ALL_BOT_COMMANDS if "ALL_BOT_COMMANDS" in globals() else False:
            return False
    if chat_id not in cleaning_mode or cleaning_mode.get(chat_id, 0) <= 0:
        return False
    settings = cleaning_settings.get(chat_id, {})
    content_type = getattr(message, "content_type", None)
    key = content_type if content_type in CLEAN_TYPES else None

    # تنظيف الروابط داخل الرسائل النصية فقط.
    if content_type == "text" and settings.get("links", False):
        text_value = message.text or ""
        # لا نحذف أوامر البوت وإعدادات الإدارة.
        if text_value.strip() in ALL_BOT_COMMANDS if "ALL_BOT_COMMANDS" in globals() else False:
            return False
        if contains_link(text_value):
            delay = cleaning_mode[chat_id]
            schedule_cleaning_delete(chat_id, message.message_id, delay)
            return True
        return False

    # تنظيف الوسائط حسب النوع المختار.
    if key and key != "links" and settings.get(key, False):
        delay = cleaning_mode[chat_id]
        schedule_cleaning_delete(chat_id, message.message_id, delay)
        return True
    return False

@bot.edited_message_handler(
    content_types=[
        "text", "photo", "video", "document", "audio", "animation",
        "voice", "sticker", "video_note", "location", "venue",
        "contact", "poll", "dice"
    ]
)
def edited_message_handler(message):
    if _enforce_persistent_bans_on_message(message):
        return
    # حماية تعديل الرسائل: تجاهل تحديثات تغيّر لقب/بيانات المشرف
    # إذا لم يتغيّر محتوى الرسالة نفسها. نتحقق من بصمة المحتوى
    # المحفوظة قبل تنفيذ الحذف أو إرسال أي تحذير.
    try:
        chat = getattr(message, "chat", None)
        if chat and getattr(chat, "type", None) in ["group", "supergroup"]:
            key = (int(chat.id), int(message.message_id))
            current_fingerprint = _message_content_fingerprint(message)
            previous = message_content_fingerprints.get(key)
            # لا نرسل تحذيرًا إلا إذا كانت لدينا بصمة سابقة تثبت أن محتوى
            # الرسالة تغيّر فعلًا. تيليجرام قد يعيد إرسال رسائل قديمة كـ
            # edited_message عند تغيير لقب/اسم المشرف، حتى لو لم يلمس الرسائل.
            # إذا لم تكن البصمة موجودة (مثلًا بعد إعادة تشغيل البوت)، فلا يمكن
            # إثبات وجود تعديل؛ تجاهل هذا التحديث بدل اتهام العضو وإغراق القروب.
            if previous is None:
                return
            if previous[1] == current_fingerprint:
                # بيانات اللقب/التوقيع تغيّرت فقط؛ محتوى الرسالة نفسه ثابت.
                return
    except Exception as e:
        print(f"[EDITED CONTENT CHECK ERROR] {e}")

    # بعد التأكد من وجود تعديل حقيقي في المحتوى، نسجل الرسالة.
    _remember_edited_for_deletion(message)

    # حماية 2 يجب أن تفحص الوسائط المستبدلة أيضاً، حتى لو كانت حماية التعديلات
    # العادية معطلة. هذا هو المسار الذي كان يجعل الصورة الجديدة تفلت من الفحص.
    if getattr(message, "content_type", "") in ("photo", "animation", "sticker", "video", "document"):
        try:
            if _ai_scan_media(message):
                return
        except Exception as e:
            print(f"[AI2 EDITED MEDIA ERROR] {type(e).__name__}: {e}", flush=True)

    # حماية تعديل الرسائل هي المسؤولة عن الوسائط المستبدلة:
    # لا نعيد فحص الوسائط بحماية 2؛ نحذف الرسالة المعدلة فوراً.
    if not basic_protection_enabled(message.chat.id, "edits"):
        return

    target = message.from_user
    if target and is_full_protection_exempt(target.id, message.chat.id):
        return
    target_id = target.id
    target_mention = get_mention(target)
    try:
        safe_delete_message(message.chat.id, message.message_id)
    except Exception:
        pass
    markup = telebot.types.InlineKeyboardMarkup()
    markup.row(
        telebot.types.InlineKeyboardButton(
            "طرد", callback_data=f"ban_edit:{target_id}"
        ),
        telebot.types.InlineKeyboardButton(
            "كتم", callback_data=f"mute_edit:{target_id}"
        )
    )
    markup.row(
        telebot.types.InlineKeyboardButton(
            "كتم مؤقت", callback_data=f"tempmute_edit:{target_id}"
        ),
        telebot.types.InlineKeyboardButton(
            "تقييد", callback_data=f"restrict_edit:{target_id}"
        )
    )
    markup.add(
        telebot.types.InlineKeyboardButton(
            "إغلاق", callback_data="close", style="danger", icon_custom_emoji_id=COMMANDS_CLOSE_ICON_ID
        )
    )
    # احذف كل رسالة معدلة مخالفة، لكن لا ترسل تحذيرًا جديدًا مع كل تحديث.
    # إذا عدّل العضو رسائل كثيرة خلال دقيقة، يظهر له تحذير واحد فقط.
    try:
        warning_key = (int(message.chat.id), int(target_id))
        now = time.time()
        with edit_warning_lock:
            last_sent = edit_warning_last_sent.get(warning_key, 0)
            should_send_warning = (now - last_sent) >= EDIT_WARNING_COOLDOWN_SECONDS
            if should_send_warning:
                edit_warning_last_sent[warning_key] = now
            # تنظيف السجل دوريًا حتى لا يكبر بلا حدود.
            if len(edit_warning_last_sent) > 10000:
                cutoff = now - (EDIT_WARNING_COOLDOWN_SECONDS * 2)
                for old_key, old_time in list(edit_warning_last_sent.items()):
                    if old_time < cutoff:
                        edit_warning_last_sent.pop(old_key, None)
        if should_send_warning:
            bot.send_message(
                message.chat.id,
                f"تم التعديل على رسالة - {target_mention}",
                reply_markup=markup,
                parse_mode="HTML"
            )
    except Exception as e:
        print(f"[EDIT WARNING DEDUPE ERROR] {e}", flush=True)

@bot.message_handler(func=lambda message: message.text == "فك القيود")
def lift_restrictions(message):
    track_message(message)
    chat_id = message.chat.id
    user_rank = get_rank(message.from_user.id, chat_id)
    if user_rank not in ["Owner", "Owner²", "Helper"] and message.from_user.id not in OWNER_IDS:
        deny_rank(message, "Helper")
        return
    if not message.reply_to_message:
        bot.reply_to(message, "يجب الرد على رسالة المستخدم.")
        return
    target = message.reply_to_message.from_user
    target_id = target.id
    target_mention = get_mention(target)
    statuses = []
    try:
        member = bot.get_chat_member(chat_id, target_id)
    except Exception:
        member = None

    # فك الحظر يحتاج صلاحية حظر الأعضاء.
    if member is not None and member.status in ["kicked", "banned"]:
        rights = get_bot_admin_rights(chat_id)
        if not rights or not rights.get("ban", False):
            bot.reply_to(
                message,
                f"• ماقدرت افك الحظر : ↤︎ 「 {target_mention} 」\n"
                "• 「لازم اعطاء البوت صلاحية الحظر اولًا」",
                parse_mode="HTML"
            )
            return

    # فك التقييد يحتاج صلاحية حظر الأعضاء.
    if member is not None and member.status == "restricted" and not member.can_send_messages:
        rights = get_bot_admin_rights(chat_id)
        if not rights or not rights.get("ban", False):
            bot.reply_to(
                message,
                f"• ماقدرت افك التقييد : ↤︎ 「 {target_mention} 」\n"
                "• 「لازم اعطاء البوت صلاحية الحظر اولًا」",
                parse_mode="HTML"
            )
            return

    # الكتم في هذا البوت يعتمد على تعديل حالة العضو، لذلك نتحقق من صلاحية الحذف كما طلبت.
    if chat_id in muted_users and target_id not in muted_users[chat_id]:
        rights = get_bot_admin_rights(chat_id)
        if not rights or not rights.get("del", False):
            bot.reply_to(
                message,
                f"• ماقدرت اكتم : ↤︎ 「 {target_mention} 」\n"
                "• 「لازم اعطاء البوت صلاحية الحذف اولًا」",
                parse_mode="HTML"
            )
            return

    if chat_id in muted_users and target_id in muted_users[chat_id]:
        del muted_users[chat_id][target_id]
        statuses.append("الكتم")
    cursor.execute(
        "DELETE FROM temp_mutes WHERE chat_id=? AND user_id=?",
        (chat_id, target_id)
    )
    conn.commit()
    try:
        member = bot.get_chat_member(chat_id, target_id)
        if member.status in ["kicked", "banned"]:
            try:
                bot.unban_chat_member(chat_id, target_id)
                moderation_remove(chat_id, target_id, "banned")
                statuses.append("الحظر")
            except Exception as e:
                print(f"خطأ في فك الحظر: {e}")
        elif member.status == "restricted":
            if not member.can_send_messages:
                try:
                    perms = telebot.types.ChatPermissions(
                        can_send_messages=True,
                        can_send_audios=True,
                        can_send_documents=True,
                        can_send_photos=True,
                        can_send_videos=True,
                        can_send_video_notes=True,
                        can_send_voice_notes=True,
                        can_send_polls=True,
                        can_send_other_messages=True,
                        can_add_web_page_previews=True,
                        can_invite_users=True,
                    )
                    bot.restrict_chat_member(chat_id, target_id, permissions=perms)
                    moderation_remove(chat_id, target_id, "restricted")
                    statuses.append("التقييد")
                except Exception as e:
                    print(f"خطأ في فك التقييد: {e}")
    except Exception as e:
        print(f"خطأ في فحص حالة المستخدم: {e}")
    if statuses:
        result = " + ".join(statuses)
        bot.reply_to(
            message,
            f"تم فك القيود عن {target_mention}\n(تم فك: {result})",
            parse_mode="HTML"
        )
    else:
        bot.reply_to(
            message,
            f"تم فك القيود عن {target_mention}\n(لا توجد قيود مسجلة عليه)",
            parse_mode="HTML"
        )

@bot.callback_query_handler(func=lambda call: str(getattr(call,"data","" )).startswith("ai2:"))
def _ai2_callback_handler(call):
    chat_id=call.message.chat.id
    parts=str(call.data).split(":")
    action=parts[1] if len(parts)>1 else ""
    target_id=int(parts[2]) if len(parts)>2 and parts[2].isdigit() else None

    # جميع أزرار إنذار حماية 2 تخص المطور وOwner فقط، بما فيها إغلاق الرسالة.
    if not _ai2_admin_allowed(call.from_user.id, chat_id):
        try:
            bot.answer_callback_query(call.id, "• هذا الامر يخص المطوّر والـ Owner فقط", show_alert=True)
        except Exception:
            try: bot.answer_callback_query(call.id, "• هذا الامر يخص المطوّر والـ Owner فقط")
            except Exception: pass
        return

    if action=="close":
        try: safe_delete_message(chat_id,call.message.message_id)
        except Exception: pass
        try: bot.answer_callback_query(call.id,"تم إغلاق الرسالة")
        except Exception: pass
        return

    if action=="clear" and target_id:
        _ai2_clear_warnings(chat_id,target_id)
        try:
            name="المستخدم"
            try: name=bot.get_chat_member(chat_id,target_id).user.first_name or name
            except Exception: pass
            bot.edit_message_text(f"• تم حذف جميع الإنذارات {name} المستخدم صاروا إنذارات ←0",chat_id,call.message.message_id)
        except Exception as e: print(f"[AI2 CLEAR EDIT ERROR] {e}",flush=True)
        bot.answer_callback_query(call.id,"تم حذف الإنذارات"); return

    if action=="safe" and target_id:
        media_hash=AI2_LAST_ALERT_HASH.pop((chat_id,call.message.message_id),None)
        if media_hash: _ai2_mark_safe(chat_id,media_hash)
        try: bot.edit_message_text("• تم اعتبار الرسالة سليمة ، وسيتم تسجيلها على انها سليمة",chat_id,call.message.message_id)
        except Exception: pass
        bot.answer_callback_query(call.id,"تم تسجيلها كسليمة"); return
    bot.answer_callback_query(call.id)


@bot.callback_query_handler(
    func=lambda call:
        not call.data.startswith("clean:")
        and not call.data.startswith("cleanopt:")
        and not call.data.startswith("owner_clean:")
        and not call.data.startswith("owner_cmd:")
        and not call.data.startswith("advprotect:")
        and not call.data.startswith("basicprotect:")
        and not call.data.startswith("toggle:")
        and not call.data.startswith("devcontact:")
        and not call.data.startswith("join_message:")
        and not call.data.startswith("developer_info:")
        and not call.data.startswith("warnings:")
        and not call.data.startswith("penalty:")
        and not call.data.startswith("stats:")
        and not call.data.startswith("delete_menu:")
        and not call.data.startswith("ai2:")
        and not call.data.startswith("protection3:")
        and not call.data.startswith("restrictpick:")
        and not call.data.startswith("mediaspam:")
        and not call.data.startswith("globalban:")
        and not call.data.startswith("botscan:")
        and not call.data.startswith("top:")
        and not call.data.startswith("autoverify:")
        and call.data != "hide_msg"
)
def callback_handler(call):
    chat_id = call.message.chat.id
    user_rank = get_rank(call.from_user.id, chat_id)
    if call.data == "close":
        bot.answer_callback_query(call.id)
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        return
    if call.data in ["close_list"]:
        bot.answer_callback_query(call.id)
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        return
    if call.data == "back_list":
        markup = telebot.types.InlineKeyboardMarkup(row_width=1)
        if user_rank in ["Helper", "Owner²", "Owner"] or call.from_user.id in OWNER_IDS:
            markup.add(_lock_button("قائمة المكتومين", "list:muted", "primary"))
        if user_rank in ["Owner²", "Owner"] or call.from_user.id in OWNER_IDS:
            markup.add(_lock_button("قائمة المقيدين", "list:restricted", "primary"))
        if user_rank == "Owner" or call.from_user.id in OWNER_IDS:
            markup.add(_lock_button("قائمة المحظورين", "list:banned", "primary"))
        markup.add(_lock_button("اغلاق", "close_list", "primary"))
        try:
            bot.edit_message_text("اختر قائمة التي تريدها :", chat_id, call.message.message_id, reply_markup=markup)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if call.data.startswith("list:"):
        kind = call.data.split(":")[1]
        fake = call.message
        fake.from_user = call.from_user
        show_restriction_list(fake, kind)
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if call.data.startswith("clearlist:"):
        kind = call.data.split(":")[1]
        if kind == "muted":
            if user_rank not in ["Helper", "Owner²", "Owner"] and call.from_user.id not in OWNER_IDS:
                deny_callback_rank(call, "Helper")
                return
            count = len(muted_users.get(chat_id, {}))
            muted_users.pop(chat_id, None)
            msg = f"تم مسح ( {count} ) من المكتومين"
        elif kind == "restricted":
            if user_rank not in ["Owner²", "Owner"] and call.from_user.id not in OWNER_IDS:
                deny_callback_rank(call, "Owner²")
                return
            users = moderation_users(chat_id, "restricted")
            perms = telebot.types.ChatPermissions(
                can_send_messages=True, can_send_audios=True,
                can_send_documents=True, can_send_photos=True,
                can_send_videos=True, can_send_video_notes=True,
                can_send_voice_notes=True, can_send_polls=True,
                can_send_other_messages=True, can_add_web_page_previews=True,
                can_invite_users=True
            )
            count = 0
            for u in users:
                try:
                    bot.restrict_chat_member(chat_id, u.id, permissions=perms)
                    moderation_remove(chat_id, u.id, "restricted")
                    count += 1
                except Exception:
                    pass
            msg = f"• تم مسح التقييد عن ( {count} ) من المقيدين"
        else:
            if user_rank != "Owner" and call.from_user.id not in OWNER_IDS:
                deny_callback_rank(call, "Owner")
                return
            users = moderation_users(chat_id, "banned")
            count = 0
            for u in users:
                try:
                    bot.unban_chat_member(chat_id, u.id)
                    moderation_remove(chat_id, u.id, "banned")
                    count += 1
                except Exception:
                    pass
            msg = f"تم مسح الحظر عن ( {count} ) من المحظورين"
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.send_message(chat_id, msg)
        bot.answer_callback_query(call.id, "تم")
        return
    if call.data == "ranklist:close":
        bot.answer_callback_query(call.id)
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        return
    if call.data == "ranklist:back":
        actor_rank = get_rank(call.from_user.id, chat_id)
        if actor_rank != "Owner" and call.from_user.id not in OWNER_IDS:
            deny_callback_rank(call, "Owner")
            return
        markup = telebot.types.InlineKeyboardMarkup(row_width=2)
        markup.row(
            _lock_button("Owner", "ranklist:Owner", "primary"),
            _lock_button("Owner²", "ranklist:Owner²", "primary")
        )
        markup.row(_lock_button("Helper", "ranklist:Helper", "primary"))
        markup.add(_lock_button("اغلاق", "ranklist:close", "primary"))
        try:
            bot.edit_message_text(
                "هذي القائمة ، يمديك تكشف عن الرتب و تعدل عليهم:",
                chat_id, call.message.message_id, reply_markup=markup
            )
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if call.data.startswith("ranklist:"):
        actor_rank = get_rank(call.from_user.id, chat_id)
        if actor_rank != "Owner" and call.from_user.id not in OWNER_IDS:
            deny_callback_rank(call, "Owner")
            return
        rank = call.data.split(":", 1)[1]
        if rank not in ["Owner", "Owner²", "Helper"]:
            bot.answer_callback_query(call.id)
            return
        users = rank_list_users(chat_id, rank)
        markup = telebot.types.InlineKeyboardMarkup(row_width=2)
        markup.row(_styled_button("مسح الجميع", f"rankclear:{rank}", "primary"))
        markup.row(_back_button("ranklist:back", "success"), _styled_button("اغلاق", "ranklist:close"))
        try:
            bot.edit_message_text(
                format_rank_list(rank, users),
                chat_id,
                call.message.message_id,
                reply_markup=markup,
                parse_mode="HTML"
            )
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return
    if call.data.startswith("rankclear:"):
        actor_rank = get_rank(call.from_user.id, chat_id)
        if actor_rank != "Owner" and call.from_user.id not in OWNER_IDS:
            deny_callback_rank(call, "Owner")
            return
        rank = call.data.split(":", 1)[1]
        if rank not in ["Owner", "Owner²", "Helper"]:
            bot.answer_callback_query(call.id)
            return
        cursor.execute(
            "SELECT COUNT(*) FROM users WHERE chat_id=? AND rank=?",
            (chat_id, rank)
        )
        row = cursor.fetchone()
        count = row[0] if row else 0
        cursor.execute(
            "UPDATE users SET rank=? WHERE chat_id=? AND rank=?",
            ("Member", chat_id, rank)
        )
        conn.commit()
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.send_message(chat_id, f"تم مسح ( {count} ) من رتبة {rank}")
        bot.answer_callback_query(call.id, "تم")
        return
    data = call.data.split(":")
    action = data[0]
    if action == "allperms":
        if user_rank not in ["Owner", "Owner²"] and call.from_user.id not in OWNER_IDS:
            deny_callback_rank(call, "Owner²")
            return
        target_id = int(data[1])
        admin_permissions.setdefault(chat_id, {})
        admin_permissions[chat_id].setdefault(target_id, {
            "info": False, "pin": False, "ban": False, "invite": False,
            "del": False, "call": False, "add": False, "topics": False
        })
        p = admin_permissions[chat_id][target_id]
        allowed_all = ["info", "pin", "invite", "del", "call", "add", "topics"]
        for key in allowed_all:
            p[key] = True
        if user_rank == "Owner" or call.from_user.id in OWNER_IDS:
            p["ban"] = True
        else:
            p["ban"] = False
        save_json_setting(chat_id, "admin_permissions", {
            str(tid): perms for tid, perms in admin_permissions[chat_id].items()
        })
        ok, err = apply_admin_permissions(
            chat_id,
            target_id,
            p,
            actor_is_dev=(user_rank == "Owner" or call.from_user.id in OWNER_IDS),
            promoted_by=call.from_user.id
        )
        if not ok:
            bot.answer_callback_query(call.id, err or "ما قدرت أطبّق كل الصلاحيات، تأكد من صلاحيات البوت.", show_alert=True)
        else:
            bot.answer_callback_query(call.id, "تم تفعيل جميع الصلاحيات")
        try:
            bot.edit_message_reply_markup(
                chat_id, call.message.message_id,
                reply_markup=get_perms_markup(target_id, chat_id)
            )
        except Exception:
            pass
        return
    if action in ["ban", "ban_edit"] and user_rank != "Owner" and call.from_user.id not in OWNER_IDS:
        deny_callback_rank(call, "Owner")
        return
    if action in ["restrict", "restrict_edit", "tempmute_menu", "tempmute_edit", "tmute", "tmute_edit"] and user_rank not in ["Owner", "Owner²"] and call.from_user.id not in OWNER_IDS:
        deny_callback_rank(call, "Owner²")
        return
    if user_rank not in ["Owner", "Owner²", "Helper"] and call.from_user.id not in OWNER_IDS:
        deny_callback_rank(call, "Helper")
        return
    bot.answer_callback_query(call.id)
    if len(data) > 1:
        try:
            target_id = int(data[1])
        except (TypeError, ValueError):
            # بعض أزرار الإغلاق تحتوي على كلمات مثل close، وليست معرف مستخدم.
            return
    else:
        target_id = None
    try:
        target_member = bot.get_chat_member(chat_id, target_id)
        target_user = target_member.user
        mention = get_mention(target_user)
    except Exception:
        mention = f'<a href="tg://user?id={target_id}">المستخدم</a>'
    if action in ["ban", "ban_edit"]:
        try:
            rights = get_bot_admin_rights(chat_id)
            if not rights or not rights.get("ban", False):
                bot.send_message(
                    chat_id,
                    "• ما أقدر أحظر المستخدم\n• لازم أعطائي صلاحية حظر الأعضاء أولًا.",
                    parse_mode="HTML"
                )
                return
            bot.ban_chat_member(chat_id, target_id)
            moderation_add(chat_id, target_id, "banned")
            bot.send_message(chat_id, protection_action_text("تم طرد", mention, "تعديل الرسائل"), parse_mode="HTML")
        except Exception:
            bot.send_message(
                chat_id,
                "• ما أقدر أحظر المستخدم\n• لازم أعطائي صلاحية حظر الأعضاء أولًا.",
                parse_mode="HTML"
            )
    elif action in ["mute", "mute_edit"]:
        rights = get_bot_admin_rights(chat_id)
        if not rights or not rights.get("del", False):
            bot.send_message(
                chat_id,
                f"• ماقدرت اكتم : ↤︎ 「 {mention} 」\n"
                "• 「لازم اعطاء البوت صلاحية الحذف اولًا」",
                parse_mode="HTML"
            )
            return
        if chat_id not in muted_users:
            muted_users[chat_id] = {}
        muted_users[chat_id][target_id] = 0
        cursor.execute(
            "INSERT OR REPLACE INTO temp_mutes(chat_id, user_id, until_time) VALUES(?,?,?)",
            (chat_id, target_id, 0)
        )
        conn.commit()
        bot.send_message(chat_id, protection_action_text("تم كتم", mention, "تعديل الرسائل"), parse_mode="HTML")
    elif action in ["restrict", "restrict_edit"]:
        try:
            rights = get_bot_admin_rights(chat_id)
            if not rights or not rights.get("ban", False):
                bot.send_message(
                    chat_id,
                    "• ما أقدر أقيد المستخدم\n• لازم أعطائي صلاحية تقييد الأعضاء أولًا.",
                    parse_mode="HTML"
                )
                return
            perms = telebot.types.ChatPermissions(can_send_messages=False)
            bot.restrict_chat_member(chat_id, target_id, permissions=perms)
            moderation_add(chat_id, target_id, "restricted")
            bot.send_message(chat_id, protection_action_text("تم تقييد", mention, "تعديل الرسائل"), parse_mode="HTML")
        except Exception as e:
            print(f"خطأ في التقييد: {e}")
            bot.send_message(
                chat_id,
                "• ما أقدر أقيد المستخدم\n• لازم أعطائي صلاحية تقييد الأعضاء أولًا.",
                parse_mode="HTML"
            )
    elif action in ["tempmute_menu", "tempmute_edit"]:
        markup = telebot.types.InlineKeyboardMarkup(row_width=2)
        markup.add(
            telebot.types.InlineKeyboardButton("5 دقائق", callback_data=f"tmute_edit:{target_id}:300", style="primary"),
            telebot.types.InlineKeyboardButton("10 دقائق", callback_data=f"tmute_edit:{target_id}:600", style="primary"),
            telebot.types.InlineKeyboardButton("ساعة", callback_data=f"tmute_edit:{target_id}:3600", style="primary"),
            telebot.types.InlineKeyboardButton("رجوع", callback_data="close", style="primary", icon_custom_emoji_id=BACK_CUSTOM_EMOJI_ID)
        )
        try:
            bot.edit_message_reply_markup(chat_id, call.message.message_id, reply_markup=markup)
        except Exception:
            pass
    elif action in ["tmute", "tmute_edit"]:
        duration = int(data[2])
        until_time = int(time.time()) + duration
        if chat_id not in muted_users:
            muted_users[chat_id] = {}
        muted_users[chat_id][target_id] = until_time
        cursor.execute(
            "INSERT OR REPLACE INTO temp_mutes(chat_id, user_id, until_time) VALUES(?,?,?)",
            (chat_id, target_id, until_time)
        )
        conn.commit()
        mins = duration // 60
        bot.send_message(
            chat_id,
            f"• تم كتم 「 {mention} 」\n• السبب: تعديل الرسائل (لمدة {mins} دقيقة)",
            parse_mode="HTML"
        )

