# الحماية من الكلمات الممنوعة
# =========================================================
FORBIDDEN_WORDS_AR = {
    "جنس اطفال", "جنس الأطفال", "اطفال جنس", "أطفال جنس",
    "استغلال اطفال", "استغلال الأطفال", "استغلال جنسي",
    "عري اطفال", "عري الأطفال", "عُري اطفال", "عُري الأطفال", "عري اطفال",
    "اطفال عري", "أطفال عري", "أطفال عُري", "عري طفل", "عُري طفل",
    "بورن", "اباحي", "إباحي", "porn", "pornography", "xxx",
    "nude", "nudity", "nsfw", "sex", "sexual",
    "مخدر", "مخدرات", "حشيش", "كوكايين", "هيروين", "كراك",
    "meth", "cocaine", "heroin", "weed", "marijuana", "drugs",
    "مسدس", "بندقية", "سلاح", "اسلحة", "أسلحة", "رشاش", "متفجرات",
    "قنبلة", "bomb", "gun", "weapon", "weapons", "explosive",
    "ارهاب", "إرهاب", "ارهابي", "إرهابي", "ارهابيين", "إرهابيين",
    "داعش", "دواعش", "isis", "isil", "daesh", "داعشي",
}
# كلمات ممنوعة ثابتة + تطبيع قوي حتى لا يفلت التحايل بالمسافات/الرموز/التشكيل.
_FORBIDDEN_TRANSLATION = str.maketrans({
    "أ":"ا", "إ":"ا", "آ":"ا", "ٱ":"ا", "ى":"ي", "ة":"ه", "ؤ":"و", "ئ":"ي",
    # بعض الحروف اللاتينية/السيريلية المتشابهة بصرياً.
    "а":"a", "е":"e", "о":"o", "р":"p", "с":"c", "х":"x", "у":"y",
    "Α":"a", "Β":"b", "Ε":"e", "Ο":"o", "Ρ":"p", "Χ":"x", "Υ":"y",
})
FORBIDDEN_WORDS_COMPACT = tuple(
    re.sub(
        r"[^\w\u0600-\u06ff]+",
        "",
        str(w).lower().translate(_FORBIDDEN_TRANSLATION),
        flags=re.UNICODE
    )
    for w in FORBIDDEN_WORDS_AR if w
)
FORBIDDEN_WORDS_COMPACT = tuple(dict.fromkeys(w for w in FORBIDDEN_WORDS_COMPACT if w))
FORBIDDEN_WORDS_COMPACT_SET = frozenset(FORBIDDEN_WORDS_COMPACT)
# الكلمات الأساسية المطلوبة دائماً في حماية الكلمات الممنوعة.
REQUIRED_FORBIDDEN_COMPACT = frozenset({
    "مخدرات", "مخدر", "داعش", "دواعش", "ارهاب", "ارهابي", "ارهابيين",
    "عرياطفال", "عريالاطفال", "اطفال عري",
})

def _normalize_forbidden_text(value):
    value = str(value or "").lower()
    value = value.replace("ـ", "")
    value = re.sub(r"[\u200b\u200c\u200d\ufeff]", "", value)
    value = value.translate(_FORBIDDEN_TRANSLATION)
    value = re.sub(r"[\u064B-\u065F\u0670\u06D6-\u06ED]", "", value)
    # حذف كل الفواصل والمسافات والرموز يسمح بكشف: م س د س / مـسـدس / m-u-s-d-s.
    return re.sub(r"[^\w\u0600-\u06ff]+", "", value, flags=re.UNICODE)

def _forbidden_word_match(value):
    compact = _normalize_forbidden_text(value)
    if not compact:
        return False
    return any(word in compact for word in FORBIDDEN_WORDS_COMPACT_SET) or any(word in compact for word in REQUIRED_FORBIDDEN_COMPACT)

def check_forbidden_words(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if not getattr(message, "chat", None) or message.chat.type not in ("group", "supergroup"):
        return False
    chat_id = message.chat.id
    # مزامنة مباشرة مع التخزين الدائم: حتى لو كانت نسخة الذاكرة قديمة، التفعيل لا يضيع.
    enabled = basic_protection_enabled(chat_id, "forbidden_words")
    if not enabled:
        # توافق مع الإصدارات السابقة التي كانت تحفظها ضمن الحماية المتقدمة.
        try:
            legacy = load_json_setting(chat_id, "advanced_protection", {}) or {}
            if isinstance(legacy, dict) and legacy.get("forbidden_words"):
                enabled = True
                basic_protection.setdefault(chat_id, {})["forbidden_words"] = True
                save_json_setting(chat_id, "basic_protection", basic_protection[chat_id])
                legacy["forbidden_words"] = False
                save_json_setting(chat_id, "advanced_protection", legacy)
        except Exception:
            pass
    if not enabled:
        return False
    user = getattr(message, "from_user", None)
    if not user or is_full_protection_exempt(user.id, chat_id):
        return False
    parts = []
    if getattr(message, "text", None): parts.append(message.text)
    if getattr(message, "caption", None): parts.append(message.caption)
    if not any(_forbidden_word_match(part) for part in parts):
        return False
    try:
        safe_delete_message(chat_id, message.message_id)
    except Exception as e:
        print(f"[FORBIDDEN WORDS] delete error: {type(e).__name__}: {e}", flush=True)
    send_basic_warning(chat_id, f"ممنوع كتابة كلمات ممنوعة - يا {get_mention(user)}")
    try:
        protection_penalty(chat_id, user, "forbidden_words")
    except Exception:
        pass
    return True

def is_repeated_laughter(text):
    """Only flag exceptionally long, standalone Arabic laughter spam.

    Ordinary laughter (for example ههههههه) is allowed. A message is considered
    laughter spam only when it consists solely of laughter letters and contains
    at least 80 of them, so normal sentences containing laughter are not removed.
    """
    if not text:
        return False
    value = re.sub(r"\s+", "", text, flags=re.UNICODE).lower()
    return len(value) >= 80 and re.fullmatch(r"[هح]+", value) is not None

def check_member_spam(message):
    _basic_user = getattr(message, "from_user", None)
    _basic_chat = getattr(message, "chat", None)
    if _basic_user and _basic_chat and is_basic_protection_exempt(_basic_user.id, _basic_chat.id):
        return False
    if message.chat.type not in ["group", "supergroup"]:
        return False
    user = message.from_user
    chat_id = message.chat.id
    if not user:
        return False
    mention = get_mention(user)
    # لا تطبق الحماية الأساسية/المتقدمة على المطور أو رتبة Owner.
    if is_full_protection_exempt(user.id, chat_id):
        return False
    text = message.text or ""
    if basic_protection_enabled(chat_id, "mentions") and get_mention_count(message) >= 3:
        try:
            safe_delete_message(chat_id, message.message_id)
        except Exception:
            pass
        send_basic_warning(chat_id, f"ممنوع المنشن - يا {mention}")
        protection_penalty(chat_id, user, "mentions")
        return True
    # احسب النص الخام بما فيه المسافات؛ بعض الرسائل تكون مجرد رموز وبينها
    # مسافات كثيرة، لذلك نفحص أيضاً سلاسل المسافات الطويلة بشكل صريح.
    has_excessive_whitespace = bool(re.search(r"[ \t\u00a0\u2000-\u200b]{100,}", text))
    if basic_protection_enabled(chat_id, "long_text") and (
        text.count("\n") + 1 > 6 or len(text) > 1000 or has_excessive_whitespace
    ):
        try:
            safe_delete_message(chat_id, message.message_id)
        except Exception:
            pass
        send_basic_warning(chat_id, f"ممنوع نصوص الطويله - يا {mention}")
        protection_penalty(chat_id, user, "long_text")
        return True
    key = (chat_id, user.id)
    # قد يمر التحديث نفسه عبر أكثر من معالج؛ لا تعتبره تكراراً من المستخدم.
    current_message_id = getattr(message, "message_id", None)
    if current_message_id is not None and last_message_ids.get(key) == current_message_id:
        return False
    previous = last_messages.get(key)
    now = time.time()
    previous_time = last_message_times.get(key, 0)
    normalized_text = re.sub(r"[\s\W_]+", "", text, flags=re.UNICODE).lower() if text else ""
    previous_normalized = (
        re.sub(r"[\s\W_]+", "", previous, flags=re.UNICODE).lower() if previous else ""
    )
    # سبام الضحكات: لا نحذف أول رسالة ضحك طويلة، لكن نحذف تكرارها المتتالي
    # إذا أرسلها المستخدم مرة ثانية خلال 10 ثوانٍ.
    if (
        basic_protection_enabled(chat_id, "laughter")
        and text and is_repeated_laughter(text)
        and normalized_text and previous_normalized == normalized_text
        and 0 <= now - previous_time < 10
    ):
        try:
            safe_delete_message(chat_id, message.message_id)
        except Exception:
            pass
        send_basic_warning(chat_id, f"ممنوع سبام ضحكات - يا {mention}")
        protection_penalty(chat_id, user, "laughter")
        return True
    if (basic_protection_enabled(chat_id, "repeat") and text and previous == text
            and 0 <= now - previous_time < 10):
        try:
            safe_delete_message(chat_id, message.message_id)
        except Exception:
            pass
        send_basic_warning(chat_id, f"ممنوع تكرار نفس الرسالة - يا {mention}")
        protection_penalty(chat_id, user, "repeat")
        return True
    if text:
        last_messages[key] = text
        last_message_times[key] = now
        last_message_ids[key] = current_message_id
    return False

