def get_group_owner(chat_id):
    try:
        admins = bot.get_chat_administrators(chat_id)
        for admin in admins:
            if getattr(admin, "status", None) == "creator":
                return admin.user
    except Exception as e:
        print(f"خطأ في جلب مالك القروب: {e}")
    return None


def get_group_link(chat):
    title = html.escape(chat.title or "القروب")
    username = getattr(chat, "username", None)
    if username:
        return f'<a href="https://t.me/{username}">{title}</a>'
    try:
        invite = getattr(chat, "invite_link", None)
        if not invite:
            invite = bot.export_chat_invite_link(chat.id)
        if invite:
            return f'<a href="{html.escape(invite, quote=True)}">{title}</a>'
    except Exception:
        pass
    return title


