def reset_chat_features(chat_id):
    # عند دخول البوت للقروب تبدأ الحماية والتنظيف مقفلة.
    basic = {name: False for name in BASIC_PROTECTION_LABELS}
    advanced = {"info": False, "description": False, "ban": False, "promote": False, "users": False, "photo_spam": False, "channels": False}
    basic_protection[chat_id] = basic
    advanced_protection[chat_id] = advanced
    advanced_add_protection.pop(chat_id, None)
    cleaning_mode.pop(chat_id, None)
    cleaning_settings.pop(chat_id, None)
    cleaning_pending.pop(chat_id, None)
    save_json_setting(chat_id, "basic_protection", basic)
    save_json_setting(chat_id, "advanced_protection", advanced)
    delete_setting(chat_id, "cleaning")


def notify_developers_bot_added(chat, added_by):
    """إشعار جميع Owner IDs عند إضافة البوت لقروب جديد."""
    group_name = html.escape(getattr(chat, "title", None) or "القروب", quote=True)
    # نحاول جلب رابط القروب بشكل موثوق. الرابط العام هو الأفضل،
    # وللقروبات الخاصة نحاول إنشاء/جلب رابط دعوة صالح. إذا تعذر ذلك لا نضع زرًا مكسورًا.
    group_url = None
    try:
        fresh_chat = bot.get_chat(chat.id)
    except Exception:
        fresh_chat = chat
    try:
        username = getattr(fresh_chat, "username", None)
        if username:
            group_url = f"https://t.me/{username}"
        else:
            invite = getattr(fresh_chat, "invite_link", None)
            if invite:
                group_url = invite
            else:
                group_url = bot.export_chat_invite_link(chat.id)
    except Exception as e:
        print(f"[BOT ADDED LINK ERROR] {e}")

    added_name = html.escape(
        getattr(added_by, "first_name", None) or getattr(added_by, "username", None) or "المستخدم",
        quote=True
    ) if added_by else "غير معروف"
    added_url = _security_user_url(added_by) if added_by else None

    text = (
        "• مرحبًا أيها المطور  <tg-emoji emoji-id=\"4918354603281482671\">👋</tg-emoji>\n"
        "• تم أضافة بوت راد سكيورتي في قروب جديد\n"
        f"• اسم اللي ضافني : {added_name}\n"
        f"• اسم القروب : {group_name}"
    )
    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    if group_url:
        markup.row(telebot.types.InlineKeyboardButton(
            group_name, url=group_url, style="primary",
            icon_custom_emoji_id="5341344057996096145"
        ))
    if added_url:
        markup.row(telebot.types.InlineKeyboardButton(
            added_name, url=added_url, style="primary",
            icon_custom_emoji_id="5341344057996096145"
        ))

    for owner_id in OWNER_IDS:
        try:
            bot.send_message(owner_id, text, reply_markup=markup, parse_mode="HTML")
        except Exception as e:
            print(f"[BOT ADDED DEVELOPER ALERT ERROR] {owner_id}: {e}")



@bot.callback_query_handler(func=lambda call: call.data.startswith("botkick:"))
def bot_added_kick_callback(call):
    """زر طرد البوت من رسالة الإضافة في الخاص."""
    try:
        bot.answer_callback_query(call.id, "جاري إخراج البوت من القروب…")
    except Exception:
        pass

    try:
        chat_id = int(call.data.split(":", 1)[1])
    except (ValueError, IndexError):
        return

    if call.from_user.id not in OWNER_IDS:
        try:
            bot.answer_callback_query(call.id, "هذا الزر للمطور فقط", show_alert=True)
        except Exception:
            pass
        return

    # جلب اسم القروب قبل الخروج.
    group_name = "القروب"
    try:
        chat = bot.get_chat(chat_id)
        group_name = getattr(chat, "title", None) or group_name
    except Exception:
        pass

    close_markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    close_markup.add(telebot.types.InlineKeyboardButton(
        "إغلاق",
        callback_data="bot_added:kick_close",
        style="danger",
        icon_custom_emoji_id=COMMANDS_CLOSE_ICON_ID
    ))

    # أرسل التأكيد للخاص. HTML أولاً، وإذا رفضه Telegram نرسل النص العادي فقط.
    confirmation = f"⌯︙تم طرد البوت من القروب ← {html.escape(group_name, quote=True)}"
    sent_private = False
    try:
        bot.send_message(
            call.from_user.id, confirmation,
            reply_markup=close_markup, parse_mode="HTML"
        )
        sent_private = True
    except Exception as e:
        print(f"[BOT KICK HTML MESSAGE ERROR] {call.from_user.id}: {e}")
        try:
            bot.send_message(
                call.from_user.id,
                f"⌯︙تم طرد البوت من القروب ← {group_name}",
                reply_markup=close_markup
            )
            sent_private = True
        except Exception as e2:
            print(f"[BOT KICK PLAIN MESSAGE ERROR] {call.from_user.id}: {e2}")

    # الخروج الحقيقي من القروب بدون أي رسائل خطأ.
    # نستخدم leave_chat مباشرة لأن البوت يغادر بنفسه ولا يحتاج صلاحيات.
    try:
        bot.leave_chat(chat_id)
    except Exception:
        pass

    # تعطيل الزر في رسالة الخاص حتى لا يبقى قابلًا للضغط بعد الخروج.
    try:
        bot.edit_message_reply_markup(
            call.message.chat.id, call.message.message_id, reply_markup=None
        )
    except Exception:
        pass


def _event_recipients_owner_owner2(chat_id):
    """المطورون + Owner و Owner² المسجلون في نفس القروب."""
    ids = set(OWNER_IDS)
    try:
        cursor.execute(
            'SELECT DISTINCT user_id FROM users WHERE chat_id=? AND rank IN ("Owner", "Owner²")',
            (chat_id,)
        )
        ids.update(int(row[0]) for row in cursor.fetchall())
    except Exception as e:
        print(f"[EVENT RECIPIENTS ERROR] {e}")
    return ids

def _admin_permissions_text(member):
    labels = [
        ("can_change_info", "تعديل معلومات"),
        ("can_promote_members", "رفع مشرف"),
        ("can_delete_messages", "مسح الرسائل"),
        ("can_restrict_members", "حظر وتقييد"),
        ("can_invite_users", "دعوة مستخدمين"),
        ("can_pin_messages", "تثبيت الرسائل"),
        ("can_manage_video_chats", "إدارة المكالمات"),
        ("can_manage_topics", "إدارة المواضيع"),
        ("can_manage_chat", "إدارة القروب"),
    ]
    enabled = [label for attr, label in labels if getattr(member, attr, False)]
    return "، ".join(enabled) if enabled else "لا توجد صلاحيات إضافية"

