def notify_admin_promotion_event(event):
    """إرسال إشعار رفع مشرف للمطورين وOwner/Owner² في نفس القروب."""
    new_member = getattr(event, "new_chat_member", None)
    actor = getattr(event, "from_user", None)
    chat = getattr(event, "chat", None)
    if not new_member or not actor or not chat:
        return
    if getattr(new_member, "status", None) != "administrator":
        return

    try:
        bot_id = bot.get_me().id
    except Exception:
        bot_id = None
    if bot_id is not None and actor.id == bot_id:
        return

    target = getattr(new_member, "user", None)
    if not target:
        return

    group_name_raw = getattr(chat, "title", None) or "القروب"
    group_name = html.escape(group_name_raw, quote=True)
    group_url = None
    try:
        if getattr(chat, "username", None):
            group_url = f"https://t.me/{chat.username}"
        else:
            group_url = getattr(chat, "invite_link", None)
            if not group_url:
                group_url = bot.export_chat_invite_link(chat.id)
    except Exception as e:
        # عدم توفر رابط القروب لا يمنع إرسال التنبيه.
        print(f"[PROMOTION GROUP LINK ERROR] {e}")

    actor_mention = get_mention(actor)
    target_mention = get_mention(target)
    perms = _admin_permissions_text(new_member)
    text = (
        "• تحذير يا المالك <tg-emoji emoji-id=\"4915853119839011973\">⚠️</tg-emoji>\n"
        f"• المستخدم ↤︎ {actor_mention}\n"
        f"• قام برفع المستخدم ↤︎ {target_mention}\n"
        "رول بصلاحيات :\n"
        f"[ {html.escape(perms)} ]"
    )

    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    if group_url:
        markup.row(telebot.types.InlineKeyboardButton(
            group_name, url=group_url, style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))
    target_name = html.escape(
        getattr(target, "first_name", None) or getattr(target, "username", None) or "المستخدم",
        quote=True
    )
    target_url = _security_user_url(target)
    if target_url:
        markup.row(telebot.types.InlineKeyboardButton(
            target_name, url=target_url, style="primary",
            icon_custom_emoji_id="4915853119839011973"
        ))

    recipients = _event_recipients_owner_owner2(chat.id)
    for user_id in recipients:
        try:
            bot.send_message(
                user_id, text, reply_markup=markup, parse_mode="HTML"
            )
        except Exception as e:
            # إذا فشل HTML/custom emoji، نجرب إرسال نص بسيط بدل ضياع التنبيه بالكامل.
            try:
                fallback = (
                    "• تحذير يا المالك ⚠️\n"
                    f"• المستخدم ↤︎ {actor_mention}\n"
                    f"• قام برفع المستخدم ↤︎ {target_mention}\n"
                    "رول بصلاحيات :\n"
                    f"[ {perms} ]"
                )
                bot.send_message(user_id, fallback, reply_markup=markup)
            except Exception as e2:
                print(f"[PROMOTION EVENT ALERT ERROR] {user_id}: {e} | fallback: {e2}")


@bot.my_chat_member_handler()
def bot_membership_changed(update):
    chat = update.chat
    if getattr(chat, "type", None) not in ["group", "supergroup"]:
        return

    old_status = getattr(update.old_chat_member, "status", "")
    new_status = getattr(update.new_chat_member, "status", "")
    added_by = getattr(update, "from_user", None)
    chat_id = chat.id

    # دخل البوت: member/administrator بعد أن كان خارج المجموعة.
    joined_statuses = {"member", "administrator"}
    left_statuses = {"left", "kicked"}

    if new_status in joined_statuses and old_status in left_statuses:
        try:
            ensure_original_group_title(chat_id, chat.title)
            register_group_stats(chat, active=1, increment=0)
            reset_chat_features(chat_id)
        except Exception as e:
            print(f"خطأ في تهيئة إعدادات القروب: {e}")

        notify_developers_bot_added(chat, added_by)
        owner = get_group_owner(chat_id)
        added_mention = get_mention(added_by) if added_by else "غير معروف"
        owner_mention = get_mention(owner) if owner else "غير معروف"
        group_link = get_group_link(chat)

        text = (
            "• السلام عليكم ، انا بوت راد للحماية\n"
            "• تم التفعيل تلقائيًا كيف تود مساعدتك اليوم ؟\n\n"
            f"• الي ضافني: 「 {added_mention} 」\n"
            f"• مالك القروب: 「 {owner_mention} 」\n"
            f"• رابط القروب : 「 {group_link} 」\n\n"
            "• كلم للتفعيل :"
        )

        markup = telebot.types.InlineKeyboardMarkup(row_width=1)
        markup.row(
            telebot.types.InlineKeyboardButton(
                "كيرتا",
                url="https://t.me/qy_dl",
                style="primary",
                icon_custom_emoji_id="5123248930124989216"
            )
        )
        markup.row(
            telebot.types.InlineKeyboardButton(
                "زين", url="https://t.me/z6iiin", style="primary",
                icon_custom_emoji_id="5123248930124989216"
            ),
            telebot.types.InlineKeyboardButton(
                "لوسي", url="https://t.me/lossawi", style="primary",
                icon_custom_emoji_id="5123248930124989216"
            )
        )
        markup.row(
            telebot.types.InlineKeyboardButton(
                "RAD channel",
                url="https://t.me/Source_Rad",
                style="success",
                icon_custom_emoji_id="5123248930124989216"
            )
        )
        markup.row(
            telebot.types.InlineKeyboardButton(
                "إغلاق",
                callback_data="join_message:close",
                style="danger",
                icon_custom_emoji_id="5321235390483426212"
            )
        )

        try:
            photo_data = base64.b64decode(JOIN_GROUP_IMAGE_B64)
            photo = io.BytesIO(photo_data)
            photo.name = "join_group.jpg"
            bot.send_photo(
                chat_id,
                photo,
                caption=text,
                reply_markup=markup,
                parse_mode="HTML"
            )
        except Exception as e:
            print(f"خطأ في رسالة إضافة البوت: {e}")

        # بعد رسالة الترحيب مباشرة: إذا كان عدد أعضاء القروب أكثر من 5،
        # يتم توثيق القروب تلقائيًا وتفعيل التنظيف والحماية والحماية المتقدمة.
        _auto_verify_group_if_needed(chat)
        return

    # تم تنزيل البوت من الإشراف أو إزالته من المجموعة.
    demoted_from_admin = old_status == "administrator" and new_status == "member"
    removed_from_group = new_status in left_statuses and old_status not in left_statuses
    if demoted_from_admin or removed_from_group:
        try:
            register_group_stats(chat, active=0, increment=0)
        except Exception:
            pass
        owner = get_group_owner(chat_id)
        actor_mention = get_mention(added_by) if added_by else "غير معروف"
        owner_mention = get_mention(owner) if owner else "غير معروف"
        group_link = get_group_link(chat)
        text = (
            f"• تم تعطيل بوت راد للحماية في 「 {group_link} 」\n"
            f"بواسطة 「 {actor_mention} 」\n"
            f"مالك القروب 「 {owner_mention} 」\n"
            "شكرًا على استضافتي ،"
        )
        try:
            bot.send_message(chat_id, text, parse_mode="HTML", disable_web_page_preview=True)
        except Exception as e:
            print(f"خطأ في رسالة إزالة البوت: {e}")



