def _top_groups_text(limit=5):
    """توب القروبات مع سطر مستقل لكل قروب ونسبة تفاعل محسوبة من إجمالي رسائل القروبات."""
    try:
        db = sqlite3.connect(DB_PATH, timeout=2, check_same_thread=False)
        db.execute("PRAGMA busy_timeout=2000")
        cur = db.cursor()
        rows = cur.execute("""
            SELECT chat_id, COALESCE(title, 'القروب'), COALESCE(message_count, 0)
            FROM group_stats
            WHERE active=1
            ORDER BY COALESCE(message_count,0) DESC, LOWER(COALESCE(title,'')) ASC
            LIMIT ?
        """, (int(limit),)).fetchall()
        total_row = cur.execute("SELECT COALESCE(SUM(message_count),0) FROM group_stats WHERE active=1").fetchone()
        total_messages = int((total_row[0] if total_row else 0) or 0)
        db.close()
    except Exception as e:
        print(f"[TOP GROUPS DATA ERROR] {type(e).__name__}: {e}", flush=True)
        rows = []
        total_messages = 0

    if not rows:
        return "• توب القروبات\n\n• لا توجد رسائل مسجلة للقروبات حتى الآن."

    lines = ["• توب القروبات", ""]
    for index, (chat_id, title, count) in enumerate(rows, 1):
        title = str(title or "القروب").replace("\n", " ").replace("\r", " ").strip() or "القروب"
        if len(title) > 55:
            title = title[:52] + "..."
        count = int(count or 0)
        percentage = int(round((count / total_messages) * 100)) if total_messages > 0 else 0
        safe_title = html.escape(title, quote=True)
        lines.append(f"• {index}) قروب {safe_title}")
        lines.append(f"  {count:,} رسالة | تفاعل القروب {percentage}%")
        lines.append("")
    return "\n".join(lines).rstrip()


def _top_users_text(chat_id, limit=20, viewer_id=None):
    """توب 20 متفاعلين في القروب الحالي مع نسبة مساهمة كل شخص ورسالة you للمستخدم الحالي."""
    try:
        db = sqlite3.connect(DB_PATH, timeout=2, check_same_thread=False)
        db.execute("PRAGMA busy_timeout=2000")
        cur = db.cursor()
        rows = cur.execute("""
            SELECT user_id, COALESCE(first_name,''), COALESCE(last_name,''),
                   COALESCE(username,''), COALESCE(msg_count,0)
            FROM users
            WHERE chat_id=? AND COALESCE(msg_count,0)>0
            ORDER BY msg_count DESC, user_id ASC
            LIMIT ?
        """, (int(chat_id), int(limit))).fetchall()
        total_row = cur.execute("SELECT COALESCE(SUM(msg_count),0) FROM users WHERE chat_id=? AND COALESCE(msg_count,0)>0", (int(chat_id),)).fetchone()
        total_messages = int((total_row[0] if total_row else 0) or 0)
        viewer_row = None
        if viewer_id is not None:
            viewer_row = cur.execute("""
                SELECT user_id, COALESCE(first_name,''), COALESCE(last_name,''),
                       COALESCE(username,''), COALESCE(msg_count,0)
                FROM users WHERE chat_id=? AND user_id=?
            """, (int(chat_id), int(viewer_id))).fetchone()
        db.close()
    except Exception as e:
        print(f"[TOP USERS DATA ERROR] {type(e).__name__}: {e}", flush=True)
        rows = []
        total_messages = 0
        viewer_row = None

    if not rows:
        return "• توب 20 متفاعلين بالقروب :\n\n• لا توجد رسائل مسجلة في هذا القروب حتى الآن."

    def _display_name(row):
        _uid, first_name, last_name, username, _count = row
        display = " ".join(x for x in (str(first_name).strip(), str(last_name).strip()) if x).strip()
        if not display:
            display = str(username).strip() if username else "عضو"
        return html.escape(display[:80] or "عضو", quote=True)

    lines = ["توب 20 متفاعلين بالقروب :", ""]
    for index, row in enumerate(rows, 1):
        _user_id, _first_name, _last_name, _username, msg_count = row
        count = int(msg_count or 0)
        percentage = int(round((count / total_messages) * 100)) if total_messages > 0 else 0
        display = _display_name(row)
        lines.append(f"{index} ) {count:,} msg l {percentage}% l {display}")

    if viewer_row is not None and int(viewer_row[4] or 0) > 0:
        viewer_count = int(viewer_row[4] or 0)
        viewer_percentage = int(round((viewer_count / total_messages) * 100)) if total_messages > 0 else 0
        viewer_display = _display_name(viewer_row)
        lines.extend(["", "━━━━━━━━━━━━━━━━━━━━", f"• you)  {viewer_count:,} msg l  {viewer_percentage}% l {viewer_display}"])
    return "\n".join(lines)

def _send_top_menu(chat_id):
    # عند كتابة «توب» تظهر قائمة التوب كنص فقط بدون صورة.
    text = "• اختر ، اي توب تريد؟"
    markup = _top_menu_markup()
    return bot.send_message(chat_id, text, reply_markup=markup, parse_mode="HTML")


@bot.message_handler(func=lambda message: bool(getattr(message, "text", None)) and message.text.strip() in ("توب", "التوب"), content_types=["text"])
def top_command(message):
    if getattr(message.chat, "type", None) not in ("group", "supergroup"):
        return
    if top_commands_hidden(message.chat.id):
        return
    if not _top_rank_allowed(message.from_user.id, message.chat.id):
        return
    _send_top_menu(message.chat.id)


@bot.callback_query_handler(func=lambda call: str(getattr(call, "data", "")).startswith("top:"))
def top_callback(call):
    try:
        chat_id = int(call.message.chat.id)
        user_id = int(call.from_user.id)
    except Exception:
        return

    if top_commands_hidden(chat_id):
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return

    if not _top_rank_allowed(user_id, chat_id):
        try:
            bot.answer_callback_query(call.id, "هذا الأمر لأصحاب الرتب فقط", show_alert=True)
        except Exception:
            pass
        return

    action = str(call.data).split(":", 1)[1]
    # نؤكد ضغط الزر فورًا حتى لا يبقى زر Telegram في حالة تحميل.
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    if action == "close":
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            try:
                bot.delete_message(chat_id, call.message.message_id)
            except Exception:
                pass
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return

    if action == "back":
        # رجوع إلى قائمة التوب الأساسية مع الاحتفاظ بنفس الصورة.
        try:
            markup = _top_menu_markup()
            try:
                bot.edit_message_caption(
                    chat_id=chat_id, message_id=call.message.message_id,
                    caption="• اختر ، اي توب تريد؟", reply_markup=markup, parse_mode="HTML"
                )
            except Exception:
                bot.edit_message_text(
                    chat_id=chat_id, message_id=call.message.message_id,
                    text="• اختر ، اي توب تريد؟", reply_markup=markup, parse_mode="HTML"
                )
            return
        except Exception as e:
            print(f"[TOP BACK ERROR] {type(e).__name__}: {e}", flush=True)
            return

    def _edit_top_result(text):
        """يعدل نفس رسالة التوب مهما كان نوع الرسالة، مع إبقاء الصورة إن وجدت."""
        markup = _top_results_markup()
        msg_id = call.message.message_id
        # نجرب الكابشن أولًا؛ هذا يحافظ على الصورة حتى لو لم يملأ
        # pyTelegramBotAPI خاصية photo داخل CallbackQueryMessage.
        try:
            bot.edit_message_caption(
                chat_id=chat_id, message_id=msg_id, caption=text,
                reply_markup=markup, parse_mode="HTML"
            )
            return True
        except Exception as caption_error:
            # إذا كانت الرسالة نصية فعلًا، ننتقل إلى تعديل النص.
            try:
                bot.edit_message_text(
                    chat_id=chat_id, message_id=msg_id, text=text,
                    reply_markup=markup, parse_mode="HTML"
                )
                return True
            except Exception as text_error:
                print(
                    f"[TOP EDIT ERROR] caption={type(caption_error).__name__}: {caption_error} | "
                    f"text={type(text_error).__name__}: {text_error}",
                    flush=True
                )
                return False

    if action == "groups":
        # توب القروبات: لا نرسل أي خطأ للمستخدم مهما كان سبب فشل الإحصائيات.
        text = _top_groups_text(5)
        _edit_top_result(text)
        return

    if action == "users":
        # توب المتفاعلين: القروب الحالي فقط.
        text = _top_users_text(chat_id, 20, user_id)
        _edit_top_result(text)
        return

    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass


