STATS_EMOJI_ID = "5346196507752149522"       # 🔔
STATS_VIEW_EMOJI_ID = "5386511085132071500" # ✅
STATS_EYES_EMOJI_ID = "5280881372418816002" # 👀
TOP_LIGHTNING_EMOJI_ID = "5341279899774627181" # ⚡️
STATS_GROUPS_PER_PAGE = 5


def _stats_emoji(emoji, emoji_id):
    return f'<tg-emoji emoji-id="{emoji_id}">{emoji}</tg-emoji>'


def _ensure_existing_group_stats():
    """يهيئ إحصائيات القروبات القديمة التي لم تكن مسجلة قبل إضافة النظام."""
    try:
        cursor.execute("SELECT chat_id, title FROM group_original_info")
        known = {int(cid): title for cid, title in cursor.fetchall()}
        cursor.execute("SELECT DISTINCT chat_id FROM chat_settings")
        for (cid,) in cursor.fetchall():
            known.setdefault(int(cid), None)
        cursor.execute("SELECT DISTINCT chat_id FROM users")
        for (cid,) in cursor.fetchall():
            known.setdefault(int(cid), None)

        for chat_id, title in known.items():
            cursor.execute("SELECT 1 FROM group_stats WHERE chat_id=?", (chat_id,))
            if cursor.fetchone():
                continue
            cursor.execute("SELECT COALESCE(SUM(msg_count),0) FROM users WHERE chat_id=?", (chat_id,))
            count = int(cursor.fetchone()[0] or 0)
            cursor.execute(
                "INSERT OR IGNORE INTO group_stats(chat_id,title,message_count,active,updated_at) VALUES(?,?,?,?,?)",
                (chat_id, title or "القروب", count, 1, int(time.time()))
            )
        conn.commit()
    except Exception as e:
        print(f"[GROUP STATS INIT ERROR] {e}")


def _get_stats_groups():
    _ensure_existing_group_stats()
    cursor.execute(
        """
        SELECT chat_id, title, username, invite_link, message_count
        FROM group_stats
        WHERE active=1
        ORDER BY LOWER(COALESCE(title,'')), chat_id
        """
    )
    rows = cursor.fetchall()
    result = []
    for chat_id, title, username, invite_link, message_count in rows:
        result.append({
            "chat_id": int(chat_id),
            "title": html.unescape(title or str(chat_id)),
            "username": username,
            "invite_link": invite_link,
            "message_count": int(message_count or 0),
        })
    return result


def _get_stats_group(chat_id):
    _ensure_existing_group_stats()
    cursor.execute(
        "SELECT chat_id,title,username,invite_link,message_count FROM group_stats WHERE chat_id=? AND active=1",
        (int(chat_id),)
    )
    row = cursor.fetchone()
    if not row:
        return None
    return {
        "chat_id": int(row[0]),
        "title": html.unescape(row[1] or str(row[0])),
        "username": row[2],
        "invite_link": row[3],
        "message_count": int(row[4] or 0),
    }


def _stats_group_counts(chat_id):
    cursor.execute(
        "SELECT rank, COUNT(*) FROM users WHERE chat_id=? AND rank IN ('Helper','Owner²','Owner') GROUP BY rank",
        (int(chat_id),)
    )
    counts = {"Helper": 0, "Owner²": 0, "Owner": 0}
    for rank, count in cursor.fetchall():
        counts[rank] = int(count or 0)
    counts["total"] = counts["Helper"] + counts["Owner²"] + counts["Owner"]
    return counts


def _stats_groups_markup(page=0):
    groups = _get_stats_groups()
    total_pages = max(1, (len(groups) + STATS_GROUPS_PER_PAGE - 1) // STATS_GROUPS_PER_PAGE)
    page = max(0, min(int(page), total_pages - 1))
    start = page * STATS_GROUPS_PER_PAGE
    items = groups[start:start + STATS_GROUPS_PER_PAGE]

    markup = telebot.types.InlineKeyboardMarkup(row_width=1)
    for item in items:
        title = str(item["title"])
        if len(title) > 55:
            title = title[:52] + "..."
        markup.row(_styled_button(title, f"stats:group:{item['chat_id']}:{page}", "primary"))

    if total_pages > 1:
        if page > 0 and page < total_pages - 1:
            markup.row(
                _styled_button("\u200b", f"stats:page:{page+1}", "primary", "5429404536970164117"),
                _styled_button("\u200b", f"stats:page:{page-1}", "primary", "5429379776483703274")
            )
        elif page == 0:
            markup.row(_styled_button("\u200b", f"stats:page:1", "primary", "5429404536970164117"))
        else:
            markup.row(_styled_button("\u200b", f"stats:page:{page-1}", "primary", "5429379776483703274"))

    markup.row(_back_button("stats:back"))
    markup.row(commands_close_button("stats:close"))
    return markup


def _stats_groups_text():
    return (
        f"• مرحبًا ، هذي قائمة القروبات الموجود فيها البوت {_stats_emoji('👀', STATS_EYES_EMOJI_ID)} :"
    )


def _stats_detail_markup(group):
    markup = telebot.types.InlineKeyboardMarkup(row_width=2)
