# أوامر الحذف اليدوي: «حذف» و«حك» / «حذف الكل»
# =========================================================
DELETE_MENU_ITEMS = [
    ("photo", "صور"),
    ("video", "فيديوهات"),
    ("animation", "قيفات"),
    ("sticker", "ملصقات"),
    ("voice", "فويسات"),
    ("edited", "رسائل معدلة"),
    ("links", "روابط"),
    ("audio", "صوتيات"),
]


def can_use_delete_commands(user_id, chat_id):
    return get_rank_level(user_id, chat_id) >= RANK_LEVELS["Helper"]


def delete_result_text(category, count):
    labels = {
        "photo": "صور",
        "video": "فيديوهات",
        "animation": "صور متحركة قيفات",
        "sticker": "ملصقات",
        "voice": "فويسات",
        "edited": "رسائل معدلة",
        "links": "روابط",
        "audio": "صوتيات",
    }
    label = labels[category]
    if count:
        return f"• حذفت ( {count} ) {label}"
    return f"• لا يوجد في القروب {label}"


def _manual_delete_message(chat_id, message_id):
    """حذف يدوي يتجاوز الاستثناءات عمداً؛ أوامر «حذف/حك» لا تحترم الاستثناء."""
    try:
        _original_bot_delete_message(chat_id, message_id)
        return True
    except Exception as e:
        print(f"[MANUAL DELETE ERROR] {chat_id}/{message_id}: {e}")
        return False


# =========================================================
# مسار خام إضافي لتغيير بايو القروب
# بعض إصدارات pyTelegramBotAPI قد لا تمرر service message
# الخاصة بالوصف إلى message handlers بالشكل المتوقع، لذلك
# نلتقطها من Update نفسه أيضاً. يعمل هذا داخل القروبات الخاصة
# والعامة طالما أن Telegram أرسل التحديث للبوت.
# =========================================================
def _precount_group_messages(updates):
    """يحسب كل رسالة واردة من الأعضاء قبل تشغيل أي handler.
    هذا يمنع أوامر/حمايات الـhandlers المبكرة من إسقاط الرسائل من عداد توب القروبات.
    لا نحسب رسائل البوت ولا edited_message ولا callback.
    """
    counts = {}
    try:
        for update in updates or []:
            msg = getattr(update, "message", None)
            if msg is None:
                continue
            chat = getattr(msg, "chat", None)
            user = getattr(msg, "from_user", None)
            if (chat is None or getattr(chat, "type", None) not in ("group", "supergroup")
                    or user is None or getattr(user, "is_bot", False)):
                continue
            cid = int(chat.id)
            counts[cid] = (chat, counts.get(cid, (chat, 0))[1] + 1)
        for _cid, (chat, count) in counts.items():
            register_group_stats(chat, active=1, increment=count)
    except Exception as e:
        print(f"[GROUP MESSAGE PRECOUNT ERROR] {type(e).__name__}: {e}", flush=True)


def _process_updates_with_description_protection(updates):
    """يمر على الـ Update نفسه قبل تشغيل handlers حتى لا تفلت خدمة تغيير البايو."""
    _precount_group_messages(updates)
    try:
        for update in updates or []:
            msg = getattr(update, "message", None)
            if msg is None:
                continue
            # حماية القنوات تُنفّذ قبل كل الـ handlers؛ خصوصاً المنشورات التي
            # تنتقل تلقائياً من القناة المرتبطة إلى مجموعة النقاش.
            try:
                if check_channel_message(msg):
                    continue
            except Exception as channel_error:
                print(f"[RAW CHANNEL PROTECTION ERROR] {channel_error}", flush=True)
            raw_update = {}
            raw_message = {}
            try:
                raw_update = update.to_dict() if hasattr(update, "to_dict") else {}
                raw_message = raw_update.get("message", {}) if isinstance(raw_update, dict) else {}
            except Exception as raw_error:
                print(f"[DESCRIPTION RAW FIELD ERROR] {raw_error}", flush=True)
            # مصدر الحقيقة هو Update الخام؛ لا نعتمد على content_type أو setattr.
            if isinstance(raw_message, dict) and "new_chat_description" in raw_message:
                raw_desc = raw_message.get("new_chat_description")
                desc = "" if raw_desc is None else str(raw_desc)
            else:
                desc = _extract_new_chat_description(msg)
            if desc is None:
                continue
            # استعادة صاحب التغيير من الـ Update الخام إذا كانت نسخة المكتبة لم تملأ from_user.
            if getattr(msg, "from_user", None) is None:
                try:
                    raw_update = update.to_dict() if hasattr(update, "to_dict") else {}
                    raw_message = raw_update.get("message", {}) if isinstance(raw_update, dict) else {}
                    raw_actor = raw_message.get("from") if isinstance(raw_message, dict) else None
                    if isinstance(raw_actor, dict):
                        try:
                            actor_obj = telebot.types.User.de_json(raw_actor)
                            if actor_obj is not None:
                                setattr(msg, "from_user", actor_obj)
                        except Exception as actor_error:
                            print(f"[DESCRIPTION ACTOR RECOVERY ERROR] {actor_error}", flush=True)
                except Exception as actor_error:
                    print(f"[DESCRIPTION RAW ACTOR ERROR] {actor_error}", flush=True)
            chat = getattr(msg, "chat", None)
            if chat is None or getattr(chat, "type", None) not in ["group", "supergroup"]:
                continue
            if getattr(msg, "_description_protection_handled", False):
                continue
            try:
                print(f"[DESCRIPTION UPDATE DETECTED] chat={chat.id} message_id={getattr(msg, 'message_id', '?')} actor={getattr(getattr(msg, 'from_user', None), 'id', None)}", flush=True)
                handle_group_description_changes(msg, detected_description=desc)
            except Exception as e:
                print(f"[RAW DESCRIPTION PROTECTION ERROR] {e}", flush=True)
    except Exception as e:
        print(f"[RAW UPDATE PREPROCESS ERROR] {e}")

_original_process_new_updates = bot.process_new_updates
def _process_new_updates_with_description_precheck(updates):
    _process_updates_with_description_protection(updates)
    return _original_process_new_updates(updates)

bot.process_new_updates = _process_new_updates_with_description_precheck


def _delete_tracked_messages(chat_id, category=None, exclude_ids=None):
    """يحذف الرسائل المسجلة مع تجاوز الاستثناءات في الحذف اليدوي."""
    exclude_ids = {int(x) for x in (exclude_ids or set())}
    message_ids = _deletion_snapshot(chat_id, category)
    deleted = 0
    for message_id in message_ids:
        if int(message_id) in exclude_ids:
            continue
        try:
            if _manual_delete_message(chat_id, message_id):
                deleted += 1
            _forget_deletion_message(chat_id, message_id)
        except Exception:
            _forget_deletion_message(chat_id, message_id)
    return deleted


def delete_all_tracked(chat_id, exclude_ids=None):
    """يحذف كل الرسائل المسجلة مرة واحدة، بما فيها المستثناة ورسائل البوت."""
    exclude_ids = {int(x) for x in (exclude_ids or set())}
    with delete_history_lock:
        history = dict(delete_history.get(int(chat_id), {}))
    counts = {key: 0 for key, _label in DELETE_MENU_ITEMS}
    for message_id, categories in history.items():
        if int(message_id) in exclude_ids:
            continue
        try:
            if _manual_delete_message(chat_id, message_id):
                # العدّ حسب نوع الرسالة المسجل؛ لا نعد رسالة واحدة مرتين داخل النوع نفسه.
                for key, _label in DELETE_MENU_ITEMS:
                    if key in categories:
                        counts[key] += 1
                _forget_deletion_message(chat_id, message_id)
            else:
                _forget_deletion_message(chat_id, message_id)
        except Exception:
            _forget_deletion_message(chat_id, message_id)
    return counts


