def _send_delete_progress_reply(message, text):
    """يرسل التقدم باقتباس صريح (quote=True) حتى مع إصدارات telebot القديمة."""
    # أولاً نرسل عبر Bot API مباشرة لضمان وصول reply_parameters ككائن JSON،
    # لأن بعض إصدارات pyTelegramBotAPI لا تحتوي ReplyParameters أصلاً.
    try:
        payload = {
            "chat_id": int(message.chat.id),
            "text": text,
            "reply_parameters": {
                "message_id": int(message.message_id),
                "allow_sending_without_reply": True,
                "quote": True
            }
        }
        response = requests.post(
            f"https://api.telegram.org/bot{TOKEN}/sendMessage",
            json=payload,
            timeout=20
        )
        data = response.json()
        if data.get("ok") and data.get("result"):
            sent = telebot.types.Message.de_json(data["result"])
            try:
                _remember_deletion_item(sent)
            except Exception:
                pass
            return sent
        print(f"[DELETE QUOTE API ERROR] {data}")
    except Exception as e:
        print(f"[DELETE QUOTE API EXCEPTION] {e}")

    # fallback: على الأقل يبقى Reply للرسالة الأصلية.
    return bot.send_message(
        message.chat.id,
        text,
        reply_to_message_id=int(message.message_id),
        allow_sending_without_reply=True
    )


@bot.message_handler(func=lambda message: (
    message.chat.type in ["group", "supergroup"]
    and bool(getattr(message, "text", None))
    and message.text.strip() in ["حذف", "مسح الكل", "حذف الكل", "حك"]
))
def delete_commands_handler(message):
    chat_id = message.chat.id
    if not can_use_delete_commands(message.from_user.id, chat_id):
        deny_rank(message, "Helper")
        return

    command = message.text.strip()
    if command in ["مسح الكل", "حذف الكل", "حك"]:
        # خذ لقطة قبل إرسال رسالة التقدم حتى لا نحذف رسالة التقدم نفسها.
        # الرد يكون مقتبساً من أمر «حذف الكل/حك»، ونستثني الأمر ورسالة التقدم
        # نفسها حتى تبقى رسالة التقدم موجودة ليتم تعديلها إلى النتيجة النهائية.
        progress = _send_delete_progress_reply(message, "قاعد احذف جميع الوسائط ...")
        exclude_ids = {message.message_id, getattr(progress, "message_id", 0)}
        counts = delete_all_tracked(chat_id, exclude_ids=exclude_ids)
        result = "\n".join(delete_result_text(key, counts.get(key, 0)) for key, _ in DELETE_MENU_ITEMS)
        try:
            bot.edit_message_text(result, chat_id, progress.message_id, parse_mode="HTML")
        except Exception:
            bot.send_message(chat_id, result, parse_mode="HTML")
        try:
            _actor_m = get_mention(message.from_user)
            add_security_log(chat_id, "مسح الكل", f"{_actor_m} حذف جميع الوسائط المسجلة", _actor_m)
        except Exception:
            pass
        return

    bot.send_message(chat_id, "• هلا , وش تبي تحذف؟", reply_markup=delete_menu_markup())


@bot.callback_query_handler(func=lambda call: call.data.startswith("delete_menu:"))
def delete_menu_callback(call):
    chat_id = call.message.chat.id
    if not can_use_delete_commands(call.from_user.id, chat_id):
        safe_answer_callback(call)
        return

    action = call.data.split(":", 1)[1]
    if action == "close":
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        safe_answer_callback(call)
        return

    if action == "back":
        try:
            edit_commands_message(bot, call, "• هلا , وش تبي تحذف؟", delete_menu_markup())
        except Exception:
            pass
        safe_answer_callback(call)
        return

    labels = dict(DELETE_MENU_ITEMS)
    if action not in labels:
        safe_answer_callback(call)
        return

    count = _delete_tracked_messages(chat_id, action)
    text = delete_result_text(action, count)
    try:
        bot.edit_message_text(text, chat_id, call.message.message_id,
                              reply_markup=delete_result_markup(), parse_mode="HTML")
    except Exception:
        try:
            bot.send_message(chat_id, text, reply_markup=delete_result_markup(), parse_mode="HTML")
        except Exception:
            pass
    safe_answer_callback(call)


def activate_everything(chat_id):
    """تفعيل 1 + 2 + 3 دفعة واحدة: تنظيف 20 ثانية بكل الخيارات،
    والحماية الأساسية والمتقدمة بكل الخيارات، مع حفظ الإعدادات بشكل دائم.
    """
    # التنظيف: 20 ثانية + جميع الأنواع.
    cleaning_mode[chat_id] = 20
    cleaning_settings[chat_id] = {key: True for key in CLEAN_TYPES}
    cleaning_pending.pop(chat_id, None)
    save_json_setting(chat_id, "cleaning", {
        "mode": 20,
        "settings": cleaning_settings[chat_id],
    })

    # الحماية الأساسية: جميع الخيارات.
    basic_states = {key: True for key in BASIC_PROTECTION_LABELS}
    basic_protection[chat_id] = basic_states
    save_json_setting(chat_id, "basic_protection", basic_states)

    # الحماية المتقدمة: جميع الخيارات.
    advanced_states = {
        "info": True,
        "description": True,
        "ban": True,
        "promote": True,
        "users": True,
        "photo_spam": True,
        "channels": True,
        "warning_spam": True,
        "forbidden_words": True,
    }
    advanced_protection[chat_id] = advanced_states
    advanced_add_protection[chat_id] = True
    save_json_setting(chat_id, "advanced_protection", advanced_states)
    try:
        chat_now = bot.get_chat(chat_id)
        ensure_original_group_title(chat_id, getattr(chat_now, "title", None))
        ensure_original_group_description(chat_id, getattr(chat_now, "description", None) or "")
    except Exception:
        pass


def disable_everything(chat_id):
    """تعطيل التنظيف والحماية الأساسية والمتقدمة بالكامل."""
    cleaning_mode.pop(chat_id, None)
    cleaning_settings.pop(chat_id, None)
    cleaning_pending.pop(chat_id, None)
    delete_setting(chat_id, "cleaning")

    basic_states = {key: False for key in BASIC_PROTECTION_LABELS}
    basic_protection[chat_id] = basic_states
    save_json_setting(chat_id, "basic_protection", basic_states)

    advanced_states = {
        "info": False,
        "description": False,
        "ban": False,
        "promote": False,
        "users": False,
        "photo_spam": False,
        "channels": False,
        "warning_spam": False,
        "forbidden_words": False,
    }
    # عند تعطيل الحماية نعيد صلاحية تغيير معلومات القروب إلى حالتها الأصلية.
    saved_change_info = load_json_setting(chat_id, "description_original_can_change_info", None)
    if saved_change_info is not None:
        _set_member_change_info_permission(chat_id, bool(saved_change_info))
    advanced_protection[chat_id] = advanced_states
    advanced_add_protection.pop(chat_id, None)
    save_json_setting(chat_id, "advanced_protection", advanced_states)


@bot.callback_query_handler(func=lambda call: call.data.startswith("owner_cmd:"))
def owner_commands_callback(call):
    chat_id = call.message.chat.id
    # نفس رتبة قفل الأمر الأصلية.
    allowed = call.from_user.id in OWNER_IDS
    if not allowed:
        # الضغط على أزرار قائمة الأوامر من غير المصرح لهم لا يرسل أي رسالة.
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return

    action = call.data.split(":", 1)[1]

    if action == "back":
        edit_commands_message(bot, call, owner_commands_text(), owner_commands_markup())
        bot.answer_callback_query(call.id)
        return

    if action == "close":
        try:
            safe_delete_message(chat_id, call.message.message_id)
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return

    if action == "1":
        edit_commands_message(
            bot, call, "اختر توقيت حذف الوسائط:", cleaning_menu_markup()
        )
        bot.answer_callback_query(call.id)
        return

    if action == "2":
        edit_commands_message(
            bot, call, "اعدادات الحماية المتقدمة:", advanced_menu_markup(chat_id)
        )
        bot.answer_callback_query(call.id)
        return

    if action == "3":
        edit_commands_message(
            bot, call, "تفضل يا قلبي اختر أوامر الي تبي تقفلها او تفعلها:",
            basic_menu_markup(chat_id)
        )
        bot.answer_callback_query(call.id)
        return

    if action == "4":
        edit_commands_message(
            bot, call, "وش تبي تخفي ؟", warning_settings_markup(chat_id)
        )
        bot.answer_callback_query(call.id)
        return

    if action == "5":
        edit_commands_message(
            bot, call, "هلا بك في قائمة العقوبات ، حدد اي امر:",
            penalties_page_markup(chat_id, 0)
        )
        bot.answer_callback_query(call.id)
        return

    if action == "6":
        activate_everything(chat_id)
        edit_commands_message(
            bot, call,
            "• تم تفعيل الكل بنجاح\n"
            "• التنظيف: 20 ثانية ↤︎ جميع الخيارات\n"
            "• الحماية المتقدمة: جميع الخيارات\n"
            "• الحماية: جميع الخيارات",
            owner_back_markup()
        )
        bot.answer_callback_query(call.id, "تم تفعيل الكل")
        return

    if action == "7":
        disable_everything(chat_id)
        edit_commands_message(
            bot, call, "• تم تعطيل التنظيف و الحماية و الحماية المتقدمة",
            owner_back_markup()
        )
        bot.answer_callback_query(call.id, "تم تعطيل الكل")
        return

    bot.answer_callback_query(call.id)


@bot.callback_query_handler(func=lambda call: call.data.startswith("owner_clean:"))
def owner_clean_callback(call):
    if get_rank_level(call.from_user.id, call.message.chat.id) < RANK_LEVELS["Owner²"]:
        try:
            bot.answer_callback_query(call.id)
        except Exception:
            pass
        return

    raw_seconds = call.data.split(":", 1)[1]
    try:
        seconds = int(raw_seconds)
    except (TypeError, ValueError):
        bot.answer_callback_query(call.id)
        return
    chat_id = call.message.chat.id

    if seconds == 0:
        cleaning_mode.pop(chat_id, None)
        cleaning_settings.pop(chat_id, None)
        cleaning_pending.pop(chat_id, None)
        delete_setting(chat_id, "cleaning")
        try:
            edit_commands_message(
                bot, call, "تم تعطيل التنظيف.", cleaning_disable_result_markup()
            )
        except Exception:
            pass
        bot.answer_callback_query(call.id)
        return

    cleaning_pending[chat_id] = {
        "seconds": seconds,
        "photo": False,
        "video": False,
        "animation": False,
        "voice": False,
        "audio": False,
        "document": False,
        "sticker": False,
        "video_note": False,
        "location": False,
        "venue": False,
        "poll": False,
        "dice": False,
        "links": False,
    }
    # الرسالة الأصلية صورة؛ نعدل الكابتشن بدل edit_message_text حتى لا تختفي الصورة.
    edit_commands_message(
        bot, call, "ايش تبي تنظف:", cleaning_options_markup(chat_id), parse_mode="HTML"
    )
    bot.answer_callback_query(call.id)


