def safe_answer_callback(call, text=None):
    try:
        if text is None:
            bot.answer_callback_query(call.id)
        else:
            bot.answer_callback_query(call.id, text)
    except Exception as e:
        # Telegram returns 400 when a callback query is already expired/answered.
        if "query is too old" not in str(e).lower() and "query id is invalid" not in str(e).lower():
            print(f"[CALLBACK ANSWER ERROR] {e}")

