@bot.callback_query_handler(func=lambda call: call.data.startswith("warnings:"))
def warnings_callback(call):
    if call.from_user.id not in OWNER_IDS:
        safe_answer_callback(call)
        return
    chat_id = call.message.chat.id
    action = call.data.split(":", 1)[1]
    if action in dict(WARNING_OPTIONS):
        save_json_setting(chat_id, action, not bool(load_json_setting(chat_id, action, False)))
    elif action == "all_on":
        # تفعيل الإخفاء = إخفاء جميع رسائل التحذيرات/الرتبة/المطور.
        for key, _ in WARNING_OPTIONS:
            save_json_setting(chat_id, key, True)
    elif action == "all_off":
        # تعطيل الإخفاء = إعادة ظهور جميع الرسائل.
        for key, _ in WARNING_OPTIONS:
            save_json_setting(chat_id, key, False)
    elif action == "close":
        try: safe_delete_message(chat_id, call.message.message_id)
        except Exception: pass
        safe_answer_callback(call)
        return
    edit_commands_message(bot, call, "وش تبي تخفي ؟", warning_settings_markup(chat_id))
    safe_answer_callback(call)

