def _reaction_is_custom_emoji(reaction):
    """يتحقق من custom/premium reaction مهما كان شكل الكائن في إصدار TeleBot."""
    if not reaction:
        return False
    if not isinstance(reaction, (list, tuple)):
        reaction = [reaction]
    for item in reaction:
        # كائنات TeleBot الحديثة: type == custom_emoji
        if getattr(item, "type", None) == "custom_emoji":
            return True
        # بعض الإصدارات تعرض المعرّف مباشرة.
        if getattr(item, "custom_emoji_id", None):
            return True
        # دعم القواميس والتمثيل الخام.
        try:
            if isinstance(item, dict):
                if item.get("type") == "custom_emoji" or item.get("custom_emoji_id"):
                    return True
            to_dict = getattr(item, "to_dict", None)
            if callable(to_dict):
                raw = to_dict()
                if isinstance(raw, dict) and (raw.get("type") == "custom_emoji" or raw.get("custom_emoji_id")):
                    return True
        except Exception:
            pass
    return False

def _remove_premium_reaction(update):
    chat=getattr(update,"chat",None); mid=getattr(update,"message_id",None)
    if not chat or mid is None or not basic_protection_enabled(chat.id,"premium_emoji"):
        return
    user=getattr(update,"user",None) or getattr(update,"actor",None)
    if user and is_full_protection_exempt(user.id,chat.id):
        return

    # Telegram يرسل التفاعل الجديد في new_reaction.
    reaction=getattr(update,"new_reaction",None)
    if reaction is None:
        reaction=getattr(update,"reaction",None)

    if not _reaction_is_custom_emoji(reaction):
        return

    try:
        # إزالة التفاعل نفسه فوراً؛ الرسالة الأصلية تبقى كما هي.
        remover = getattr(bot, "set_message_reaction", None)
        if callable(remover):
            remover(chat.id, mid, reaction=[])
        else:
            print("[PREMIUM REACTION ERROR] set_message_reaction غير متوفر في مكتبة TeleBot الحالية")
    except Exception as e:
        print(f"[PREMIUM REACTION ERROR] {e}")

if hasattr(bot,"message_reaction_handler"):
    @bot.message_reaction_handler()
    def premium_reaction_handler(update):
        _remove_premium_reaction(update)

