MEDIA_SPAM_TRACKER = {}
MEDIA_SPAM_LOCK = threading.RLock()

def _media_spam_markup(chat_id, user_id):
    kb = telebot.types.InlineKeyboardMarkup(row_width=1)
    kb.row(_styled_button("• الغاء التقييد", f"mediaspam:unrestrict:{chat_id}:{user_id}", "success"))
    kb.row(commands_close_button(f"mediaspam:close:{chat_id}:{user_id}"))
    return kb

@bot.callback_query_handler(func=lambda c: str(getattr(c, "data", "")).startswith("mediaspam:"))
def media_spam_callback(call):
    try:
        _, action, chat_raw, user_raw = call.data.split(":", 3)
        chat_id, user_id, actor_id = int(chat_raw), int(user_raw), int(call.from_user.id)
        rank = get_rank(actor_id, chat_id)
        allowed = actor_id in OWNER_IDS or rank in ("Owner", "Owner²", "Owner2", "O2")
        if action == "close":
            if not allowed:
                bot.answer_callback_query(call.id, "هذا الأمر يخص الـ Owner وما فوق", show_alert=True); return
            bot.delete_message(call.message.chat.id, call.message.message_id)
            bot.answer_callback_query(call.id); return
        if not allowed:
            bot.answer_callback_query(call.id, "هذا الأمر يخص الـ Owner وما فوق", show_alert=True); return
        member = bot.get_chat_member(chat_id, user_id)
        user = member.user
        # فك تقييد الوسائط فقط مع إعادة السماح بكل أنواع الإرسال.
        bot.restrict_chat_member(chat_id, user_id, permissions=telebot.types.ChatPermissions(
            can_send_messages=True, can_send_audios=True, can_send_documents=True,
            can_send_photos=True, can_send_videos=True, can_send_video_notes=True,
            can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True,
            can_add_web_page_previews=True
        ))
        moderation_remove(chat_id, user_id, "media_restricted")
        try:
            mention = get_mention(user)
        except Exception:
            mention = f'<a href="tg://user?id={user_id}">المستخدم</a>'
        bot.edit_message_text(f"• تم الفك التقييد عن ↤︎ {mention}", chat_id, call.message.message_id, parse_mode="HTML")
        bot.answer_callback_query(call.id, "تم فك التقييد")
    except Exception as e:
        print(f"[MEDIA SPAM CALLBACK ERROR] {e}", flush=True)
        try: bot.answer_callback_query(call.id, "تعذر تنفيذ الطلب", show_alert=True)
        except Exception: pass

def handle_media_spam_protection(message):
    """إذا تتابعت 3 صور/ملصقات/GIF من المستخدم خلال أقل من 30 ثانية، احذف عناصر السلسلة وقيّده."""
    if not is_group(message) or is_general_exception(message):
        return False
    kind = getattr(message, "content_type", None)
    if kind not in ("photo", "sticker", "animation"):
        return False
    chat_id = int(message.chat.id)
    user = getattr(message, "from_user", None)
    if not user or not advanced_protection_enabled(chat_id, "photo_spam"):
        return False
    if user.id in OWNER_IDS or get_rank(user.id, chat_id) in ("Owner", "Owner²", "Owner2", "O2", "Developer"):
        return False
    # إذا كان العضو مقيد وسائط بالفعل، لا ترسل التحذير مرة ثانية؛ احذف الوسائط الجديدة فقط.
    try:
        cursor.execute("SELECT 1 FROM moderation WHERE chat_id=? AND user_id=? AND status=? LIMIT 1",
                       (int(chat_id), int(user.id), "media_restricted"))
        already_restricted = cursor.fetchone() is not None
    except Exception:
        already_restricted = False
    if already_restricted:
        try: safe_delete_message(chat_id, int(message.message_id))
        except Exception: pass
        return True
    now = time.time()
    key = (chat_id, int(user.id))
    with MEDIA_SPAM_LOCK:
        items = [x for x in MEDIA_SPAM_TRACKER.get(key, []) if now - x["time"] < 30]
        items.append({"message_id": int(message.message_id), "time": now, "kind": kind})
        MEDIA_SPAM_TRACKER[key] = items
    if len(items) < 3:
        return False
    # لا نكرر تقييد/تحذير لكل رسالة ضمن نفس سلسلة السبام.
    if len(items) >= 3:
        with MEDIA_SPAM_LOCK:
            MEDIA_SPAM_TRACKER.pop(key, None)
        deleted = False
        for item in items:
            try:
                safe_delete_message(chat_id, item["message_id"]); deleted = True
            except Exception as e:
                print(f"[MEDIA SPAM DELETE ERROR] {e}", flush=True)
        try:
            bot.restrict_chat_member(chat_id, user.id, permissions=telebot.types.ChatPermissions(can_send_messages=True, can_send_audios=False, can_send_documents=False, can_send_photos=False, can_send_videos=False, can_send_video_notes=False, can_send_voice_notes=False, can_send_polls=False, can_send_other_messages=False, can_add_web_page_previews=False))
            moderation_add(chat_id, user.id, "media_restricted")
            labels = {"sticker": "ملصقات", "photo": "صور", "animation": "قيفات"}
            label = labels.get(kind, "وسائط")
            try: mention = get_mention(user)
            except Exception: mention = f'<a href="tg://user?id={user.id}">{user.first_name or "المستخدم"}</a>'
            bot.send_message(chat_id, f"• تحذير من سورس راد سكيورتي\n• هذا المستخدم ↤︎ {mention}\n• قام بسبام {label}\n• تم تقييده عن وسائط", parse_mode="HTML", reply_markup=_media_spam_markup(chat_id, user.id))
        except Exception as e:
            print(f"[MEDIA SPAM RESTRICT ERROR] {e}", flush=True)
        return True
    # أثناء استمرار السلسلة احذف الوسائط الإضافية أيضًا.
    try: safe_delete_message(chat_id, int(message.message_id))
    except Exception: pass
    return True



