def _ai_make_contact_sheet(raw, mime_type, max_frames=12):
    """يحوّل GIF/WEBP/صور الملصقات المتحركة إلى صورة مركبة من عدة إطارات للفحص."""
    try:
        if not _PILLOW_AVAILABLE:
            return None
        from PIL import Image
        src = Image.open(io.BytesIO(raw))
        n = int(getattr(src, "n_frames", 1) or 1)
        if n <= 1:
            out = io.BytesIO()
            src.convert("RGB").save(out, "JPEG", quality=88)
            return out.getvalue()
        count = min(max_frames, n)
        idxs = sorted(set(int(round(i * (n - 1) / max(1, count - 1))) for i in range(count)))
        frames=[]
        for idx in idxs:
            try:
                src.seek(idx)
                im=src.convert("RGB")
                im.thumbnail((512,512))
                canvas=Image.new("RGB",(512,512),"white")
                x=(512-im.width)//2; y=(512-im.height)//2
                canvas.paste(im,(x,y))
                frames.append(canvas)
            except Exception:
                pass
        if not frames:
            return None
        cols=2
        rows=(len(frames)+cols-1)//cols
        sheet=Image.new("RGB",(cols*512,rows*512),"white")
        for i,im in enumerate(frames):
            sheet.paste(im,((i%cols)*512,(i//cols)*512))
        out=io.BytesIO()
        sheet.save(out,"JPEG",quality=88)
        return out.getvalue()
    except Exception as e:
        print(f"[AI] contact sheet failed: {type(e).__name__}: {e}",flush=True)
        return None


def _ai_render_tgs_contact_sheet(raw, max_frames=12):
    """يرندر TGS فعلياً قبل الفحص بدلاً من الاعتماد على thumbnail فقط."""
    try:
        # python-lottie يدعم TGS (gzip JSON) ويمكنه تصديره إلى GIF.
        try:
            import lottie
            from lottie.parsers.tgs import parse_tgs
            from lottie.exporters.gif import export_gif
        except Exception:
            import subprocess, sys
            subprocess.run(
                [sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
                 "--no-input", "lottie[GIF]"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                timeout=240, check=False
            )
            from lottie.parsers.tgs import parse_tgs
            from lottie.exporters.gif import export_gif

        src = io.BytesIO(raw)
        anim = parse_tgs(src)
        end_frame = int(getattr(anim, "end_frame", 60) or 60)
        start_frame = int(getattr(anim, "in_point", 0) or 0)
        total = max(1, end_frame - start_frame)
        skip = max(1, int(total / max(1, max_frames)))

        gif = io.BytesIO()
        export_gif(anim, gif, dpi=96, skip_frames=skip)
        gif_bytes = gif.getvalue()
        if not gif_bytes:
            return None
        return _ai_make_contact_sheet(gif_bytes, "image/gif", max_frames)
    except Exception as e:
        print(f"[AI] TGS render failed: {type(e).__name__}: {e}", flush=True)
        return None

def _ai_sticker_thumbnail(message):
    """يستخدم thumbnail الخاص بملصق TGS إذا تعذر تحويل ملفه المتحرك."""
    try:
        sticker=getattr(message,"sticker",None)
        thumb=getattr(sticker,"thumbnail",None) or getattr(sticker,"thumb",None)
        if thumb and getattr(thumb,"file_id",None):
            f=bot.get_file(thumb.file_id)
            raw=bot.download_file(f.file_path)
            return raw, "image/jpeg"
    except Exception as e:
        print(f"[AI] sticker thumbnail failed: {type(e).__name__}: {e}",flush=True)
    return None, None

def _ai_image_to_jpeg(raw, max_size=2048):
    """يحّول أي صورة WebP/GIF/PNG إلى JPEG قياسي قبل إرسالها إلى Gemini."""
    try:
        if not _PILLOW_AVAILABLE:
            return raw, None
        from PIL import Image, ImageOps
        src = Image.open(io.BytesIO(raw))
        # أول إطار فقط هنا؛ GIF المتحرك يعالج عبر contact sheet.
        src.seek(0)
        if getattr(src, "mode", "") in ("RGBA", "LA", "P"):
            src = src.convert("RGBA")
            bg = Image.new("RGB", src.size, "white")
            bg.paste(src, mask=src.getchannel("A"))
            src = bg
        else:
            src = src.convert("RGB")
        src.thumbnail((max_size, max_size))
        out = io.BytesIO()
        src.save(out, "JPEG", quality=92, optimize=True)
        return out.getvalue(), "image/jpeg"
    except Exception as e:
        print(f"[AI] image convert failed: {type(e).__name__}: {e}", flush=True)
        return raw, None

def _ai_video_thumbnail(raw):
    """يأخذ عدة لقطات من WebM/MP4 عند توفر ffmpeg، لاستخدامها عند تعذر إرسال الفيديو مباشرة."""
    try:
        import subprocess, tempfile, os as _os
        with tempfile.TemporaryDirectory() as td:
            inp=_os.path.join(td,"in.webm")
            out=_os.path.join(td,"frame.jpg")
            with open(inp,"wb") as f: f.write(raw)
            cmd=["ffmpeg","-y","-loglevel","error","-ss","0","-i",inp,"-frames:v","1","-vf","scale=1024:-1",out]
            r=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=20)
            if r.returncode==0 and _os.path.exists(out):
                return Path(out).read_bytes()
    except Exception as e:
        print(f"[AI] video thumbnail failed: {type(e).__name__}: {e}",flush=True)
    return None

def _ai_media_info(message):
    """يجهز كل الوسائط بصيغة آمنة لـ Gemini: الصور/GIF/الملصقات والفيديو."""
    content_type = getattr(message, "content_type", "")
    if content_type == "photo" and getattr(message, "photo", None):
        f=bot.get_file(message.photo[-1].file_id)
        raw=bot.download_file(f.file_path)
        converted,mime=_ai_image_to_jpeg(raw)
        return converted, (mime or "image/jpeg")
    if content_type == "animation" and getattr(message, "animation", None):
        f=bot.get_file(message.animation.file_id); raw=bot.download_file(f.file_path)
        # نفحص عدة إطارات، وليس أول إطار فقط.
        sheet=_ai_make_contact_sheet(raw,"image/gif",8)
        if sheet: return sheet,"image/jpeg"
        converted,mime=_ai_image_to_jpeg(raw)
        return converted,(mime or "image/jpeg")
    if content_type == "video" and getattr(message, "video", None):
        f=bot.get_file(message.video.file_id); raw=bot.download_file(f.file_path)
        mime=getattr(message.video,"mime_type",None) or "video/mp4"
        return raw,mime
    if content_type == "sticker" and getattr(message, "sticker", None):
        sticker=message.sticker
        f=bot.get_file(sticker.file_id); raw=bot.download_file(f.file_path)
        if getattr(sticker,"is_animated",False):
            # TGS هو Lottie مضغوط؛ thumbnail هو fallback الآمن إذا لم تتوفر مكتبة Lottie.
            thumb_raw,thumb_mime=_ai_sticker_thumbnail(message)
            if thumb_raw:
                converted,mime=_ai_image_to_jpeg(thumb_raw)
                return converted,(mime or "image/jpeg")
            return None,None
        if getattr(sticker,"is_video",False):
            thumb=_ai_video_thumbnail(raw)
            if thumb:
                converted,mime=_ai_image_to_jpeg(thumb)
                return converted,(mime or "image/jpeg")
            thumb_raw,thumb_mime=_ai_sticker_thumbnail(message)
            if thumb_raw:
                converted,mime=_ai_image_to_jpeg(thumb_raw)
                return converted,(mime or "image/jpeg")
            return raw,"video/webm"
        converted,mime=_ai_image_to_jpeg(raw)
        return converted,(mime or "image/jpeg")
    return None,None

def _ai_extract_json(text):
    """استخراج JSON مع fallback للرد المقطوع من Gemini."""
    text=(text or "").strip()
    text=re.sub(r"^```(?:json)?\s*", "", text, flags=re.I)
    text=re.sub(r"\s*```$", "", text).strip()
    decoder=json.JSONDecoder()
    for pos,ch in enumerate(text):
        if ch != "{":
            continue
        try:
            obj,_=decoder.raw_decode(text[pos:])
            if isinstance(obj,dict):
                return obj
        except json.JSONDecodeError:
            pass
    # Gemini أحياناً يرجع JSON مقطوعاً رغم responseMimeType=json.
    m=re.search(r'"violation"\s*:\s*(true|false)', text, re.I)
    if m:
        violation=m.group(1).lower()=="true"
        tm=re.search(r'"type"\s*:\s*"([^"\n\r}]*)', text, re.I)
        cm=re.search(r'"confidence"\s*:\s*(\d+)', text, re.I)
        return {
            "violation": violation,
            "type": tm.group(1).strip() if tm else ("other" if violation else "none"),
            "confidence": int(cm.group(1)) if cm else (100 if violation else 0),
        }
    raise ValueError("Gemini returned invalid JSON")


