def _ai_upload_file_for_gemini(raw, mime_type, display_name="telegram_media"):
    """يرفع الوسائط الكبيرة إلى Gemini Files API ثم يرجع file URI."""
    try:
        init_url = "https://generativelanguage.googleapis.com/upload/v1beta/files"
        headers = {
            "x-goog-api-key": GEMINI_API_KEY,
            "X-Goog-Upload-Protocol": "resumable",
            "X-Goog-Upload-Command": "start",
            "X-Goog-Upload-Header-Content-Length": str(len(raw)),
            "X-Goog-Upload-Header-Content-Type": mime_type,
            "Content-Type": "application/json",
        }
        r = requests.post(init_url, headers=headers, json={"file": {"display_name": display_name}}, timeout=30)
        if r.status_code >= 400:
            print(f"[AI] File API start error: {r.status_code} {r.text[:1000]}", flush=True); return None
        upload_url = r.headers.get("X-Goog-Upload-URL") or r.headers.get("x-goog-upload-url")
        if not upload_url:
            print(f"[AI] File API missing upload URL: {r.headers}", flush=True); return None
        r2 = requests.post(upload_url, headers={
            "Content-Length": str(len(raw)), "X-Goog-Upload-Offset": "0",
            "X-Goog-Upload-Command": "upload, finalize"
        }, data=raw, timeout=120)
        if r2.status_code >= 400:
            print(f"[AI] File API upload error: {r2.status_code} {r2.text[:1000]}", flush=True); return None
        file_obj=(r2.json() or {}).get("file") or {}
        uri=file_obj.get("uri"); name=file_obj.get("name")
        if not uri:
            print(f"[AI] File API no URI: {r2.text[:1500]}", flush=True); return None
        return uri, name
    except Exception as e:
        print(f"[AI] File API exception: {type(e).__name__}: {e}", flush=True); return None

def _ai_delete_uploaded_file(file_name):
    if not file_name: return
    try:
        requests.delete(f"https://generativelanguage.googleapis.com/v1beta/{file_name}", headers={"x-goog-api-key": GEMINI_API_KEY}, timeout=20)
    except Exception: pass

