_NSFW_MODEL = None
_NSFW_PROCESSOR = None
_NSFW_LOAD_LOCK = threading.Lock()

def _local_nsfw_classify(images):
    """يفحص الإباحية/العري بمصنّف مفتوح المصدر محلياً؛ لا يحدد استغلال الأطفال وحده."""
    global _NSFW_MODEL, _NSFW_PROCESSOR
    if not images:
        return False, "none", 0
    if _NSFW_MODEL is None:
        with _NSFW_LOAD_LOCK:
            if _NSFW_MODEL is None:
                try:
                    import torch
                    from transformers import AutoImageProcessor, AutoModelForImageClassification
                    model_id = "Falconsai/nsfw_image_detection"
                    _NSFW_PROCESSOR = AutoImageProcessor.from_pretrained(model_id)
                    _NSFW_MODEL = AutoModelForImageClassification.from_pretrained(model_id)
                    _NSFW_MODEL.eval()
                    print("[AI2] local NSFW classifier loaded", flush=True)
                except Exception as e:
                    print(f"[AI2] NSFW model load failed: {type(e).__name__}: {e}", flush=True)
                    return False, "none", 0
    try:
        from PIL import Image
        import torch
        best_key, best_score = "none", 0.0
        for raw in images:
            image = Image.open(io.BytesIO(raw)).convert("RGB")
            inputs = _NSFW_PROCESSOR(images=image, return_tensors="pt")
            with torch.no_grad():
                logits = _NSFW_MODEL(**inputs).logits[0]
                probs = torch.softmax(logits, dim=-1).cpu().tolist()
            id2label = getattr(_NSFW_MODEL.config, "id2label", {}) or {}
            for idx, prob in enumerate(probs):
                label = str(id2label.get(idx, id2label.get(str(idx), ""))).lower()
                score = float(prob) * 100.0
                if label in ("porn", "hentai") and score > best_score and score >= 55:
                    best_key, best_score = "pornography", score
                elif label == "sexy" and score > best_score and score >= 78:
                    best_key, best_score = "nudity", score
        return (best_key != "none", best_key, int(round(best_score)))
    except Exception as e:
        print(f"[AI2] NSFW classify failed: {type(e).__name__}: {e}", flush=True)
        return False, "none", 0

