def _local_ai_video_frames(raw, count=12):
    try:
        import subprocess, tempfile, os as _os
        try:
            import imageio_ffmpeg
            ffmpeg = imageio_ffmpeg.get_ffmpeg_exe()
        except Exception:
            import sys
            subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--no-input", "imageio-ffmpeg"],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=180, check=False)
            import imageio_ffmpeg
            ffmpeg = imageio_ffmpeg.get_ffmpeg_exe()
        with tempfile.TemporaryDirectory() as td:
            inp=_os.path.join(td,"media.webm")
            outpat=_os.path.join(td,"frame_%02d.jpg")
            with open(inp,"wb") as fh: fh.write(raw)
            cmd=[ffmpeg,"-y","-loglevel","error","-i",inp,"-vf",f"fps=2,scale=768:-2","-frames:v",str(count),outpat]
            subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60,check=False)
            paths=sorted(Path(td).glob("frame_*.jpg"))
            return [q.read_bytes() for q in paths[:count]]
    except Exception as e:
        print(f"[AI] local video frame extraction failed: {type(e).__name__}: {e}", flush=True)
        return []


def _local_ai_classify(images):
    if not images:
        return False, "none", 0
    # يبدأ بالمصنّف المتخصص للإباحية والعري، ثم يستخدم CLIP للفئات الأخرى.
    nsfw_violation, nsfw_type, nsfw_conf = _local_nsfw_classify(images)
    if nsfw_violation:
        return True, nsfw_type, nsfw_conf
    if not _local_ai_install_and_load():
        return False, "none", 0
    try:
        from PIL import Image
        import torch
        labels=[]
        keys=[]
        for key, descs in _LOCAL_AI_LABELS.items():
            keys.append(key)
            labels.append(" or ".join(descs))
        all_texts = labels + ["safe ordinary content"]
        best_key="none"; best_score=0.0
        for raw in images:
            img=Image.open(io.BytesIO(raw)).convert("RGB")
            inputs=_LOCAL_AI_PROCESSOR(text=all_texts, images=img, return_tensors="pt", padding=True)
            with torch.no_grad():
                out=_LOCAL_AI_MODEL(**inputs)
                probs=out.logits_per_image.softmax(dim=1)[0].cpu().tolist()
            idx=max(range(len(probs)), key=lambda i: probs[i])
            score=float(probs[idx])*100.0
            if idx < len(keys) and score > best_score:
                best_key=keys[idx]; best_score=score
        # CLIP is only a fallback classifier. Use a conservative threshold so
        # ordinary/safe images are not treated as violations by weak zero-shot matches.
        if best_key == "none":
            return False, "none", 0
        if best_score < AI2_MIN_CONFIDENCE:
            return False, "none", int(round(best_score))
        return True, best_key, int(min(100, round(best_score)))
    except Exception as e:
        print(f"[AI] local classify failed: {type(e).__name__}: {e}", flush=True)
        return False, "none", 0


