# =========================================================
AI2_MIN_CONFIDENCE = 35
# حماية أشد للمحتوى الجنسي/العري/الاستغلال، خصوصاً عندما يتعلق بقاصر.
# لا نحتاج ثقة 35% كاملة حتى نوقف محتوى عالي الخطورة إذا أعاد المصنف violation=true.
AI2_HIGH_RISK_TYPES = frozenset({
    "pornography", "nudity", "sexual_act", "child_exploitation"
})
AI2_HIGH_RISK_MIN_CONFIDENCE = 20
AI2_WARNINGS_SETTING = "ai2_warnings"
AI2_SAFE_MEDIA_SETTING = "ai2_safe_media"
AI2_WARNINGS_LOCK = threading.Lock()
AI2_LAST_ALERT_HASH = {}
AI2_COUNTED_MESSAGES = set()
AI2_COUNTED_MESSAGES_LIMIT = 20000

def _ai2_admin_allowed(user_id, chat_id):
    try:
        return int(user_id) in OWNER_IDS or str(get_rank(int(user_id), int(chat_id))).strip() in ("Owner", "Developer")
    except Exception: return False

def _ai2_get_warnings(chat_id):
    try:
        raw=load_json_setting(chat_id, AI2_WARNINGS_SETTING, {}) or {}
        if not isinstance(raw, dict):
            return {}
        cleaned={}
        for k,v in raw.items():
            try:
                iv=max(0,min(3,int(v or 0)))
            except Exception:
                iv=0
            if iv:
                cleaned[str(k)]=iv
        return cleaned
    except Exception: return {}

def _ai2_set_warnings(chat_id,data):
    cleaned={str(k):max(0,min(3,int(v or 0))) for k,v in (data or {}).items() if int(v or 0) > 0}
    save_json_setting(chat_id, AI2_WARNINGS_SETTING, cleaned)

def _ai2_add_warning(chat_id,user_id,message_id=None):
    with AI2_WARNINGS_LOCK:
        # يمنع احتساب نفس الرسالة مرتين إذا مرّت على أكثر من media handler.
        message_key=None
        if message_id is not None:
            try: message_key=(int(chat_id),int(message_id),int(user_id))
            except Exception: message_key=None
        if message_key is not None and message_key in AI2_COUNTED_MESSAGES:
            return int(_ai2_get_warnings(chat_id).get(str(user_id),0) or 0)
        data=_ai2_get_warnings(chat_id)
        count=min(3,int(data.get(str(user_id),0))+1)
        data[str(user_id)]=count
        _ai2_set_warnings(chat_id,data)
        if message_key is not None:
            AI2_COUNTED_MESSAGES.add(message_key)
            if len(AI2_COUNTED_MESSAGES) > AI2_COUNTED_MESSAGES_LIMIT:
                # set ليس مرتباً؛ نحذف دفعة من العناصر القديمة بشكل محدود.
                for item in list(AI2_COUNTED_MESSAGES)[:5000]:
                    AI2_COUNTED_MESSAGES.discard(item)
        return count

def _ai2_clear_warnings(chat_id,user_id):
    with AI2_WARNINGS_LOCK:
        data=_ai2_get_warnings(chat_id)
        # الحذف الفعلي للمفتاح يمنع بقاء قيمة قديمة أو دمجها مع إنذار لاحق.
        data.pop(str(user_id), None)
        _ai2_set_warnings(chat_id,data)
        # امسح أثر عدّ الرسائل السابقة للمستخدم بعد تصفيره.
        for item in list(AI2_COUNTED_MESSAGES):
            if item[0] == int(chat_id) and item[2] == int(user_id):
                AI2_COUNTED_MESSAGES.discard(item)

def _ai2_media_hash(frames):
    h=hashlib.sha256()
    for raw in frames[:12]: h.update(hashlib.sha256(raw).digest())
    return h.hexdigest()

def _ai2_safe_hashes(chat_id):
    try: return set(load_json_setting(chat_id, AI2_SAFE_MEDIA_SETTING, []) or [])
    except Exception: return set()

def _ai2_mark_safe(chat_id, media_hash):
    if not media_hash: return
    try:
        values=_ai2_safe_hashes(chat_id); values.add(str(media_hash)); save_json_setting(chat_id, AI2_SAFE_MEDIA_SETTING, list(values)[-2000:])
    except Exception as e: print(f"[AI2 SAFE SAVE ERROR] {e}",flush=True)

def _ai2_warning_markup(chat_id,user):
    name=str(getattr(user,"first_name",None) or getattr(user,"username",None) or "المستخدم").replace("\n"," ").strip()[:40]
    # كل زر في صف مستقل كما طلبت.
    markup=telebot.types.InlineKeyboardMarkup(row_width=1)
    markup.row(telebot.types.InlineKeyboardButton(
        f"حذف إنذارات {name}",
        callback_data=f"ai2:clear:{int(user.id)}",
        style="success",
        icon_custom_emoji_id="5879915802815107172"
    ))
    markup.row(telebot.types.InlineKeyboardButton(
        "الرسالة ليست مخالفة",
        callback_data=f"ai2:safe:{int(user.id)}",
        style="primary",
        icon_custom_emoji_id="5931409969613116639"
    ))
    markup.row(commands_close_button("ai2:close"))
    return markup

def _ai2_mention(user):
    try: return get_mention(user)
    except Exception: return f'<a href="tg://user?id={int(user.id)}">المستخدم</a>'

def _ai2_restrict_user(chat_id,user_id):
    try:
        member = bot.get_chat_member(chat_id, bot.get_me().id)
        rights = getattr(member, "can_restrict_members", False)
        if not rights:
            print(f"[AI2 RESTRICT SKIP] bot lacks can_restrict_members in chat={chat_id}", flush=True)
            return False
        bot.restrict_chat_member(
            chat_id, user_id,
            permissions=telebot.types.ChatPermissions(can_send_messages=False)
        )
        try: moderation_add(chat_id,user_id,"restricted")
        except Exception: pass
        return True
    except Exception as e:
        print(f"[AI2 RESTRICT ERROR] {chat_id}/{user_id}: {e}",flush=True)
        return False

AI2_LOCAL_FALLBACK_CONFIDENCE = 55


def _ai2_block_unscannable(message, reason):
    """وضع fail-closed: لا تمر أي وسائط لم يتم فحصها بنجاح."""
    try:
        warning_count = _ai2_add_warning(message.chat.id, message.from_user.id, message.message_id)
    except Exception:
        warning_count = 1

    deleted = False
    # استخدم الدالة الأصلية أولاً حتى لا يمنع wrapper الحذف بالخطأ.
    for deleter in (
        globals().get("_original_bot_delete_message"),
        getattr(bot, "delete_message", None)
    ):
        if not callable(deleter):
            continue
        try:
            deleter(message.chat.id, message.message_id)
            deleted = True
            break
        except Exception as e:
            print(f"[AI2] fail-closed delete error: {type(e).__name__}: {e}", flush=True)

    actor = _ai2_mention(message.from_user)
    try:
        add_security_log(
            message.chat.id,
            "حماية 2",
            f"{actor} — تم حظر وسائط غير قابلة للفحص — {html.escape(str(reason))} — إنذار {warning_count}/3",
            actor
        )
    except Exception:
        pass

    try:
        sent = bot.send_message(
            message.chat.id,
            "• تم حظر الوسائط لأن حماية 2 لم تستطع فحصها.\n"
            f"• اللي خالف : {actor}\n"
            f"• السبب : {html.escape(str(reason))}\n"
            f"• إنذار ({warning_count}/3)",
            parse_mode="HTML",
            reply_markup=_ai2_warning_markup(message.chat.id, message.from_user)
        )
        if warning_count >= 3:
            _ai2_restrict_user(message.chat.id, message.from_user.id)
    except Exception as e:
        print(f"[AI2] fail-closed notification error: {type(e).__name__}: {e}", flush=True)

    setattr(message, "_ai2_violation_handled", True)
    return True


# بصمات إدراكية لعينات RAD PHOTO المضافة. لا نخزن الصور نفسها داخل السورس.
# البصمة الإدراكية تتسامح مع تغيير الدقة وإعادة الضغط وتغيير الأبعاد.
_AI2_RAD_PHOTO_PHASHES = (
    ("9877666e43a85729", "other"),  # عينة تدخين
    ("e7370be8252b2b46", "drugs"),  # عينة مواد/أقراص وأدوات تعاطٍ
    ("a0a52e495f61df26", "other"),  # عينة إشارة غير لائقة
    # بصمات إدراكية فقط لعينات استغلال/عري قاصرين؛ لا تُخزَّن الصور الأصلية.
    ("d278664fc89b2396", "child_exploitation"),
    ("e75316546ece0b4a", "child_exploitation"),
)


def _ai2_phash_distance(hash_a, hash_b):
    try:
        return (int(hash_a, 16) ^ int(hash_b, 16)).bit_count()
    except Exception:
        return 64


def _ai2_image_phash(raw):
    """بصمة pHash ثابتة نسبياً أمام اختلاف المقاس والضغط."""
    try:
        import math
        import numpy as np
        from PIL import Image, ImageOps
        with Image.open(io.BytesIO(raw)) as source:
            img = ImageOps.exif_transpose(source).convert("L").resize((32, 32), Image.Resampling.LANCZOS)
        pixels = np.asarray(img, dtype=np.float64)
        n = 32
        basis = np.cos((2 * np.arange(n)[:, None] + 1) * np.arange(n)[None, :] * math.pi / (2 * n))
        basis[:, 0] *= 1 / math.sqrt(2)
        coeff = (2 / n) * (basis.T @ pixels @ basis)
        low = coeff[:8, :8].reshape(-1)
        median = float(np.median(low[1:]))
        value = 0
        for bit in (low > median):
            value = (value << 1) | int(bit)
        return f"{value:016x}"
    except Exception as exc:
        print(f"[AI2] RAD PHOTO hash failed: {type(exc).__name__}: {exc}", flush=True)
        return None


def _ai2_match_rad_photo(images):
    for raw in images or []:
        current = _ai2_image_phash(raw)
        if not current:
            continue
        for reference, label in _AI2_RAD_PHOTO_PHASHES:
            # حد محافظ لتقليل المطابقات الخاطئة مع صور مختلفة.
            if _ai2_phash_distance(current, reference) <= 5:
                return label
    return None


def _ai_scan_media(message):
    """حماية 2: يفحص الصور/الملصقات/GIF/الفيديو محلياً دون API خارجي، ثم يحذف المخالف."""
    if not getattr(message, "chat", None) or message.chat.type not in ("group", "supergroup"):
        return False
    if not _ai_protection_enabled(message.chat.id):
        return False
    # افحص عينات الحظر المرجعية حتى لو كان المرسل Owner/Dev أو الرسالة مستثناة؛
    # ثم احترم الإعفاءات لبقية الوسائط غير المطابقة.
    if not getattr(message, "from_user", None):
        return False
    if getattr(message, "_ai2_scanned", False):
        return bool(getattr(message, "_ai2_violation_handled", False))
    # لا نضع علامة scanned إلا بعد تجهيز الوسائط بنجاح؛ إذا فشل التنزيل/التحويل
    # يمكن لمسار لاحق إعادة المحاولة بدلاً من اعتبار الرسالة مفحوصة.

    print(f"[AI] scan start chat={getattr(getattr(message, 'chat', None), 'id', None)} type={getattr(message, 'content_type', None)} msg={getattr(message, 'message_id', None)}", flush=True)
    try:
        frames = _local_ai_frames(message)
        if not frames:
            print(f"[AI] no frames extracted: type={getattr(message, 'content_type', None)}", flush=True)
            if getattr(message, "content_type", "") == "photo":
                setattr(message, "_ai2_scanned", True)
                return _ai2_block_unscannable(message, "تعذر تنزيل الصورة أو تحويلها للفحص")
            return False
        media_hash=_ai2_media_hash(frames)

        # عينات الحظر لها أولوية دائماً على قائمة الوسائط المسموح بها.
        # هذا يمنع تجاوز الحماية إذا سبق وضع الصورة نفسها في القائمة الآمنة.
        rad_photo_type = _ai2_match_rad_photo(frames)
        if rad_photo_type:
            local_violation, local_type, local_conf = True, rad_photo_type, 99
            verdict_source = "rad_photo_reference"
            print(f"[AI2] RAD PHOTO reference matched type={rad_photo_type}", flush=True)
        elif is_general_exception(message) or _ai_sender_exempt(message):
            print("[AI2] exempt sender/message skipped after blocked-reference check",flush=True)
            setattr(message, "_ai2_scanned", True)
            return False
        elif media_hash in _ai2_safe_hashes(message.chat.id):
            print("[AI2] known-safe media skipped (no blocked-reference match)",flush=True)
            setattr(message, "_ai2_scanned", True)
            return False
        else:
            # الفحص المحلي المعتاد عند عدم وجود تطابق مرجعي.
            local_violation, local_type, local_conf = _local_ai_classify(frames)
            verdict_source = "local"
        verdict = {
            "violation": bool(local_violation),
            "type": local_type if local_violation else "none",
            "confidence": int(local_conf),
            "source": verdict_source
        }
        print(f"[AI2] local-only verdict={local_violation} type={local_type} confidence={local_conf}", flush=True)

        # لا نثبت حالة scanned إلا بعد أن أعاد Gemini/المصنف المحلي نتيجة صالحة.
        setattr(message, "_ai2_scanned", True)
        violation = bool(verdict.get("violation", False))
        typ = str(verdict.get("type", "none") or "none").strip().lower()
        confidence = max(0, min(100, int(verdict.get("confidence", 0) or 0)))

        print(f"[AI] verdict={violation} confidence={confidence} type={typ} frames={len(frames)}", flush=True)

        # للمحتوى عالي الخطورة: أي verdict=true موثوق نسبياً يُحظر،
        # مع عتبة أقل من باقي أنواع المخالفات حتى لا تفلت الحالات الحساسة.
        required_confidence = (
            AI2_HIGH_RISK_MIN_CONFIDENCE
            if typ in AI2_HIGH_RISK_TYPES
            else AI2_MIN_CONFIDENCE
        )
        if not violation or confidence < required_confidence:
            return False

        warning_count=_ai2_add_warning(message.chat.id,message.from_user.id,message.message_id)

        deleted = False
        try:
            # لا نستخدم safe_delete_message هنا لأن حماية 2 نفسها يجب أن تقدر
            # على حذف الرسالة المخالفة، بينما safe_delete_message مخصص لمسارات
            # الحذف التي يجب أن تحترم استثناءات الحماية العامة.
            bot.delete_message(message.chat.id, message.message_id)
            deleted = True
        except Exception as e:
            print(f"[AI] delete error: {type(e).__name__}: {e}", flush=True)

        if not deleted:
            # محاولة ثانية مباشرة؛ ثم لا نسمح للمعالج التالي باعتبار الرسالة سليمة.
            try:
                _original_bot_delete_message(message.chat.id, message.message_id)
                deleted = True
            except Exception as e:
                print(f"[AI] hard delete retry error: {type(e).__name__}: {e}", flush=True)

        if not deleted:
            print(f"[AI2] BLOCKED BUT NOT DELETED chat={message.chat.id} msg={message.message_id}", flush=True)
            try:
                bot.send_message(
                    message.chat.id,
                    "• تم اكتشاف محتوى مخالف، لكن تعذر حذفه.\n"
                    "• تأكد أن البوت يملك صلاحية حذف الرسائل.",
                    parse_mode="HTML"
                )
            except Exception:
                pass
            return True

        label=_ai_type_label(typ); actor=_ai2_mention(message.from_user)
        if warning_count>=3: _ai2_restrict_user(message.chat.id,message.from_user.id)
        try: add_security_log(message.chat.id,"حماية 2",f"{actor} — {html.escape(label)} — الثقة {confidence}% — إنذار {warning_count}/3",actor)
        except Exception: pass
        setattr(message,"_ai2_violation_handled",True)
        try:
            text=("• تم حذف رسالة المخالفة بواسطة سورس راد\n" f"• اللي خالف : {actor}\n" f"• نوع المخالفة : {html.escape(label)}\n" f"• النسبة : {confidence}%\n" f"• تم إعطاؤه انذار ({warning_count}/3)")
            sent=bot.send_message(message.chat.id,text,parse_mode="HTML",reply_markup=_ai2_warning_markup(message.chat.id,message.from_user))
            AI2_LAST_ALERT_HASH[(message.chat.id,sent.message_id)]=media_hash
            if warning_count>=3: bot.send_message(message.chat.id,f"• تم تقييد {actor} بسبب إنذاراته",parse_mode="HTML")
        except Exception as e: print(f"[AI] notification error: {type(e).__name__}: {e}",flush=True)
        return True
    except Exception as e:
        print(f"[AI] scan error: {type(e).__name__}: {e}", flush=True)
        return False


def _ai_gemini_classify_one(raw,index, model=None):
    """One HTTP request per media frame/batch. Never burn quota with retries."""
    import base64
    model = (model or GEMINI_MODEL).strip()
    prompt=(
        "You are a Telegram content-moderation classifier. Inspect the actual pixels. "
        "Return ONLY one JSON object with exactly these keys: violation (boolean), type, confidence (integer 0-100). "
        "type must be one of pornography,nudity,sexual_act,child_exploitation,drugs,weapons,violence,terrorism,hate,self_harm,illegal_sale,other,none. "
        "Prioritize detection of child sexual abuse/exploitation: if a minor is visibly nude, sexually exposed, or involved in sexualized/exploitative imagery, return type=child_exploitation with violation=true. Do not downgrade a clear minor-related sexual violation to generic nudity. Also flag explicit sexual imagery, exposed intimate anatomy, sexual acts, and clearly illicit drugs, visible weapons, violence, terrorism, hate, self-harm, or illegal sales. "
        "Do not refuse because the image is sensitive; this is moderation classification. "
        "Only mark violation=true when the violation is clearly visible and unambiguous. "
        "Do not guess, do not infer from clothing, poses, colors, memes, cartoons, or ordinary objects. "
        "For a clear violation use confidence 36-100. If unsure or ordinary/safe, return violation=false,type=none,confidence=0."
    )
    parts=[{"text":prompt},{"inline_data":{"mime_type":"image/jpeg","data":base64.b64encode(raw).decode("ascii")}}]
    url=f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
    payload={"contents":[{"parts":parts}],"generationConfig":{"temperature":0,"responseMimeType":"application/json","maxOutputTokens":256},
             "safetySettings":[
                 {"category":"HARM_CATEGORY_SEXUALLY_EXPLICIT","threshold":"BLOCK_NONE"},
                 {"category":"HARM_CATEGORY_HATE_SPEECH","threshold":"BLOCK_NONE"},
                 {"category":"HARM_CATEGORY_HARASSMENT","threshold":"BLOCK_NONE"},
                 {"category":"HARM_CATEGORY_DANGEROUS_CONTENT","threshold":"BLOCK_NONE"}]}
    try:
        r=requests.post(url,headers={"x-goog-api-key":GEMINI_API_KEY,"Content-Type":"application/json"},json=payload,timeout=45)
        if r.status_code>=400:
            print(f"[AI] Gemini HTTP {r.status_code} model={model} frame={index}: {r.text[:900]}",flush=True)
            return None, r.status_code
        data=r.json(); text=""
        for cand in data.get("candidates",[]):
            for part in cand.get("content",{}).get("parts",[]):
                if part.get("text"): text+=part["text"]
        if not text:
            print(f"[AI] Gemini returned no text model={model} frame={index}; feedback={data.get('promptFeedback')}",flush=True)
            return None, 200
        v=_ai_extract_json(text)
        return (v if isinstance(v,dict) else None), 200
    except Exception as e:
        print(f"[AI] Gemini frame {index} error model={model}: {type(e).__name__}: {e}",flush=True)
        return None, 0


def _ai_gemini_classify_frames(images):
    """Send all extracted frames in ONE request, with a one-time model fallback."""
    if not GEMINI_API_KEY or GEMINI_API_KEY.startswith("YOUR_") or not images:
        return None
    imgs=list(images[:8])
    def run(model):
        import base64
        parts=[{"text":(
            "Telegram moderation. Inspect ALL supplied image frames together. "
            "Return ONLY JSON: {\"violation\":boolean,\"type\":string,\"confidence\":integer}. "
            "type must be pornography,nudity,sexual_act,child_exploitation,drugs,weapons,violence,terrorism,hate,self_harm,illegal_sale,other,none. "
            "Prioritize child sexual abuse/exploitation: if a minor is visibly nude, sexually exposed, or involved in sexualized/exploitative imagery, return type=child_exploitation and violation=true; do not downgrade a clear minor-related violation to generic nudity. Also flag clearly visible explicit sexual content, nudity/intimate anatomy, sexual acts, illicit drugs, weapons, violence, terrorism, hate, self-harm or illegal sales. "
            "Only mark violation=true when the violation is clearly visible and unambiguous in at least one frame. "
            "Do not guess or infer from ambiguous images, ordinary clothing, poses, cartoons, memes, or normal objects. "
            "For a clear violation use confidence 36-100. If unsure or safe, return violation=false,type=none,confidence=0."
        )}]
        for raw in imgs:
            parts.append({"inline_data":{"mime_type":"image/jpeg","data":base64.b64encode(raw).decode("ascii")}})
        url=f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
        payload={"contents":[{"parts":parts}],"generationConfig":{"temperature":0,"responseMimeType":"application/json","maxOutputTokens":256},
                 "safetySettings":[
                     {"category":"HARM_CATEGORY_SEXUALLY_EXPLICIT","threshold":"BLOCK_NONE"},
                     {"category":"HARM_CATEGORY_HATE_SPEECH","threshold":"BLOCK_NONE"},
                     {"category":"HARM_CATEGORY_HARASSMENT","threshold":"BLOCK_NONE"},
                     {"category":"HARM_CATEGORY_DANGEROUS_CONTENT","threshold":"BLOCK_NONE"}]}
        try:
            r=requests.post(url,headers={"x-goog-api-key":GEMINI_API_KEY,"Content-Type":"application/json"},json=payload,timeout=45)
            if r.status_code>=400:
                print(f"[AI] Gemini batch HTTP {r.status_code} model={model}: {r.text[:1000]}",flush=True)
                return None, r.status_code
            data=r.json(); text=""
            for cand in data.get("candidates",[]):
                for part in cand.get("content",{}).get("parts",[]):
                    if part.get("text"): text+=part["text"]
            if not text:
                print(f"[AI] Gemini batch empty model={model}; feedback={data.get('promptFeedback')}",flush=True)
                return None, 200
            v=_ai_extract_json(text)
            return (v if isinstance(v,dict) else None), 200
        except Exception as e:
            print(f"[AI] Gemini batch error model={model}: {type(e).__name__}: {e}",flush=True)
            return None, 0
    verdict,status=run(GEMINI_MODEL)
    if verdict is not None:
        return verdict
    # جرّب النموذج الاحتياطي أيضاً عند الاستجابة الفارغة/غير القابلة للتحليل،
    # وليس فقط عند أكواد HTTP محددة؛ هذا يمنع مرور المحتوى بسبب فشل JSON أو حجب الاستجابة.
    if GEMINI_FALLBACK_MODEL and GEMINI_FALLBACK_MODEL != GEMINI_MODEL:
        print(f"[AI] primary model unavailable/unusable ({status}); trying fallback {GEMINI_FALLBACK_MODEL}",flush=True)
        verdict,status2=run(GEMINI_FALLBACK_MODEL)
        if verdict is not None:
            return verdict
        print(f"[AI] fallback unavailable status={status2}; local classifier will be tried",flush=True)
    return None


def _ping_grade(ms):
    if ms < 100:
        return "ممتاز"
    if ms < 300:
        return "متوسط"
    return "ضعيف"


@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and m.text.strip().lower() in ("بنق", "/ping"), content_types=["text"])
def owner_ping_command(message):
    """اختبار أداء خاص بمعرّفات مالك البوت فقط."""
    user = getattr(message, "from_user", None)
    if not user or user.id not in OWNER_IDS:
        return

    # عمر الرسالة عند وصولها لمعالج البوت (تقريبي لأن تاريخ Telegram بدقة الثواني).
    now_epoch = time.time()
    msg_date = getattr(message, "date", None)
    bot_ms = max(0.0, (now_epoch - float(msg_date)) * 1000.0) if msg_date else 0.0

    # زمن اتصال TCP من السيرفر إلى Telegram، دون تنفيذ طلب API كامل.
    server_ms = None
    try:
        t0 = time.perf_counter()
        with _gemini_socket.create_connection(("api.telegram.org", 443), timeout=4):
            pass
        server_ms = (time.perf_counter() - t0) * 1000.0
    except Exception as e:
        print(f"[PING SERVER ERROR] {e}", flush=True)

    # زمن استجابة Telegram API بطلب getMe مباشر.
    api_ms = None
    try:
        t0 = time.perf_counter()
        resp = requests.get(f"https://api.telegram.org/bot{TOKEN}/getMe", timeout=6)
        api_ms = (time.perf_counter() - t0) * 1000.0
        if not resp.ok:
            print(f"[PING API HTTP] {resp.status_code}", flush=True)
    except Exception as e:
        print(f"[PING API ERROR] {e}", flush=True)

    # قياس محلي بسيط لزمن معالجة CPU في العملية الحالية.
    t0 = time.perf_counter()
    checksum = 0
    for i in range(12000):
        checksum = (checksum + (i * i) % 997) % 1000003
    local_ms = (time.perf_counter() - t0) * 1000.0

    def fmt(value):
        return "تعذر القياس" if value is None else f"{value:.2f} ms"

    reply = (
        "• نتائج البنق\n"
        f"• سرعة البوت ↤ {fmt(bot_ms)} — {_ping_grade(bot_ms)}\n"
        f"• سرعة السيرفر ↤ {fmt(server_ms)} — {_ping_grade(server_ms) if server_ms is not None else 'تعذر القياس'}\n"
        f"• Telegram API ↤ {fmt(api_ms)}\n"
        f"• معالجة محلية ↤ {fmt(local_ms)}"
    )
    try:
        bot.reply_to(message, reply)
    except Exception as e:
        print(f"[PING REPLY ERROR] {e}", flush=True)


