@bot.message_handler(func=lambda m: bool(getattr(m, "text", None)) and re.match(r"^(?:تقييد|تق)(?:\s+.*)?$", m.text.strip()) and not any(x in m.text.strip() for x in ("وسائط", "رسائل")), content_types=["text"])
def restrict_member_command(message):
    if not is_group(message): return
    chat_id = int(message.chat.id)
    uid = int(message.from_user.id)
    if not can_use_locked_command(uid, chat_id, "تقييد"):
        locked_command_denied(message, "تقييد"); return
    if bool(load_json_setting(chat_id, "hide_restrict_command", False)):
        return
    if uid not in OWNER_IDS and get_rank_level(uid, chat_id) < RANK_LEVELS["Helper"]:
        bot.reply_to(message, "• هذا الامر يخص ↤ ｢ Helper وما فوق ｣"); return
    command_text = (message.text or "").strip()
    target_text = command_text[2:].strip() if command_text.startswith("تق") else command_text[len("تقييد"):].strip()
    target = resolve_target_user(message, target_text)
    if not target:
        bot.reply_to(message, "• يجب الرد على رسالة المستخدم أو كتابة @منشن أو ID المستخدم."); return
    kb = telebot.types.InlineKeyboardMarkup(row_width=2)
    kb.row(_styled_button("• الرسائل", f"restrictpick:messages:{chat_id}:{target.id}", "success"), _styled_button("• الوسائط", f"restrictpick:media:{chat_id}:{target.id}", "success"))
    kb.row(commands_close_button(f"restrictpick:close:{chat_id}:{target.id}"))
    bot.reply_to(message, "• تبي تقيده من أرسال ؟", reply_markup=kb)

@bot.callback_query_handler(func=lambda c: str(getattr(c, "data", "")).startswith("restrictpick:"))
def restrict_member_callback(call):
    try:
        parts=call.data.split(":"); action=parts[1]; chat_id=int(parts[2]); target_id=int(parts[3])
        uid=int(call.from_user.id)
        if uid not in OWNER_IDS and get_rank_level(uid, chat_id) < RANK_LEVELS["Helper"]:
            bot.answer_callback_query(call.id, "• هذا الامر يخص ↤ ｢ Helper وما فوق ｣", show_alert=True); return
        if action == "close":
            bot.delete_message(call.message.chat.id, call.message.message_id); bot.answer_callback_query(call.id); return
        if action == "messages":
            perms=telebot.types.ChatPermissions(can_send_messages=False, can_send_media_messages=False, can_send_polls=False, can_send_other_messages=False, can_add_web_page_previews=False)
            label="رسائل"
        else:
            perms=telebot.types.ChatPermissions(can_send_messages=True, can_send_media_messages=False, can_send_polls=False, can_send_other_messages=False, can_add_web_page_previews=False)
            label="وسائط"
        bot.restrict_chat_member(chat_id, target_id, permissions=perms)
        try: target=bot.get_chat_member(chat_id,target_id).user; mention=get_mention(target)
        except Exception: mention=f'<a href="tg://user?id={target_id}">المستخدم</a>'
        bot.send_message(chat_id, f"• المستخدم ذا ↤︎「 {mention} 」\n• قيدته {label}", parse_mode="HTML")
        bot.delete_message(call.message.chat.id, call.message.message_id)
        bot.answer_callback_query(call.id, "تم التقييد")
    except Exception as e:
        print(f"[RESTRICT PICK ERROR] {e}", flush=True)
        try: bot.answer_callback_query(call.id, "تعذر تنفيذ التقييد", show_alert=True)
        except Exception: pass

