@bot.message_handler(func=lambda m: is_group(m) and bool(getattr(m, "text", None)) and re.match(r"^تحديد\s+\S+\s+\d+\s*$", m.text.strip()), content_types=["text"])
def add_targeted_cleanup_command(message):
    if not _can_manage_targeted_cleanup(message.from_user.id, message.chat.id):
        deny_rank(message, "Owner²"); return
    parts = message.text.strip().split()
    target_text, seconds_text = parts[1], parts[2]
    seconds = int(seconds_text)
    if seconds < 10 or seconds > 86400:
        bot.reply_to(message, "• المدة المتاحة من 10 ثوانٍ إلى 24 ساعة"); return
    target = resolve_target_user(message, target_text)
    if not target:
        bot.reply_to(message, "• ما قدرت أحدد المستخدم. تأكد أنه بالقروب أو رد على رسالته."); return
    if getattr(target, "is_bot", False) and int(target.id) == int(bot.get_me().id):
        bot.reply_to(message, "• ما تقدر تحدد البوت نفسه."); return
    chat_id = int(message.chat.id)
    # يبدأ العد من لحظة التحديد؛ لا نحذف رسائل قديمة أُرسلت قبل الأمر.
    cursor.execute("DELETE FROM targeted_cleanup_messages WHERE chat_id=? AND user_id=?", (chat_id, int(target.id)))
    cursor.execute("""
        INSERT OR REPLACE INTO targeted_cleanup_rules(chat_id,user_id,username,first_name,interval_seconds,next_run_at,enabled)
        VALUES(?,?,?,?,?,?,1)
    """, (chat_id, int(target.id), getattr(target,"username",None), getattr(target,"first_name",None) or "مستخدم", seconds, int(time.time()) + seconds))
    conn.commit()
    mention = get_mention(target)
    bot.reply_to(message, f"• حددت رسايل ← {mention}\n• تنحذف كل {_format_cleanup_interval(seconds)}", parse_mode="HTML")


@bot.message_handler(func=lambda m: is_group(m) and bool(getattr(m, "text", None)) and " ".join(m.text.strip().split()) in {"تعطيل تنظيف التحديد", "تفعيل تنظيف التحديد"}, content_types=["text"])
def toggle_targeted_cleanup_command(message):
    if not _can_manage_targeted_cleanup(message.from_user.id, message.chat.id):
        deny_rank(message, "Owner²"); return
    enabled = int("تفعيل" in message.text.strip())
    cursor.execute("UPDATE targeted_cleanup_rules SET enabled=?, next_run_at=? WHERE chat_id=?", (enabled, int(time.time()) + 10, int(message.chat.id)))
    if not enabled:
        cursor.execute("DELETE FROM targeted_cleanup_messages WHERE chat_id=?", (int(message.chat.id),))
    conn.commit()
    bot.reply_to(message, "• تم تفعيل تنظيف التحديد" if enabled else "• تم تعطيل تنظيف التحديد")


@bot.message_handler(func=lambda m: is_group(m) and bool(getattr(m, "text", None)) and " ".join(m.text.strip().split()) in {"المحددين", "قائمة المحددين", "قائمه المحددين"}, content_types=["text"])
def list_targeted_cleanup_command(message):
    if not _can_manage_targeted_cleanup(message.from_user.id, message.chat.id):
        deny_rank(message, "Owner²"); return
    rows = _targeted_cleanup_list(message.chat.id)
    lines = ["قائمة المحددين لمسح رسايلهم:", "━━━━━━━━━"]
    if not rows:
        lines.append("لا يوجد")
    else:
        for uid, username, first_name, seconds, enabled in rows:
            label = "@" + username if username else (first_name or str(uid))
